/// Serialize successful live-open projection fixtures within this test binary.
///
/// Production deliberately admits only one worst-case projection at a time
/// through `RealtimeOpenProjectionAdmission::global()` and rejects concurrent
/// opens as backpressured. Tests that require a successful projection must not
/// race each other for that process-global production budget.
#[cfg(test)]
pub(crate) async fn realtime_open_projection_test_guard() -> tokio::sync::OwnedMutexGuard<()> {
    static LOCK: std::sync::OnceLock<Arc<tokio::sync::Mutex<()>>> = std::sync::OnceLock::new();
    Arc::clone(LOCK.get_or_init(|| Arc::new(tokio::sync::Mutex::new(()))))
        .lock_owned()
        .await
}

// The existing exact-input capacity ledger also owns a claimed deferred seed.
// Only actual native admission may make that claim available to the executor.
struct RuntimePreAdmissionEntry {
    input_id: InputId,
    admission: RpcRuntimePreAdmission,
}

/// Per session, the inputs whose admitting request opted out of its turn's
/// `session/event` copies.
type TurnSessionEventOptOuts = Arc<StdMutex<HashMap<SessionId, HashSet<InputId>>>>;

/// A request's opt-out of its turn's `session/event` copies, held while the
/// request runs. Dropping it forgets the input, whether or not its turn ran:
/// a turn no request waits on (a resumed run, a requeued input) writes its
/// events as usual.
pub(crate) struct TurnSessionEventsOptOut {
    opt_outs: TurnSessionEventOptOuts,
    session_id: SessionId,
    input_id: InputId,
}

impl Drop for TurnSessionEventsOptOut {
    fn drop(&mut self) {
        let mut opt_outs = self
            .opt_outs
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(inputs) = opt_outs.get_mut(&self.session_id) {
            inputs.remove(&self.input_id);
            if inputs.is_empty() {
                opt_outs.remove(&self.session_id);
            }
        }
    }
}

pub(crate) struct RpcRuntimePreAdmission {
    admission: Option<RuntimePreAdmission>,
    #[cfg(feature = "local-authorization")]
    promotion: Option<PendingPromotionCleanup>,
    #[cfg(feature = "local-authorization")]
    unresolved: bool,
}

impl RpcRuntimePreAdmission {
    fn ordinary(admission: RuntimePreAdmission) -> Self {
        Self {
            admission: Some(admission),
            #[cfg(feature = "local-authorization")]
            promotion: None,
            #[cfg(feature = "local-authorization")]
            unresolved: false,
        }
    }

    fn can_apply(&self) -> bool {
        #[cfg(feature = "local-authorization")]
        if self.unresolved {
            return false;
        }
        true
    }

    async fn prepare(mut self) -> Result<RuntimePreAdmission, RpcError> {
        #[cfg(feature = "local-authorization")]
        if let Some(mut promotion) = self.promotion.take() {
            if !promotion.finish_now().await {
                promotion.retain_unresolved();
                return Err(runtime_driver_error_to_rpc(
                    crate::governed_jsonl::unsupported(),
                ));
            }
            promotion.disarm();
        }
        self.admission.take().ok_or_else(|| RpcError {
            code: error::INTERNAL_ERROR,
            message: "native input has no retained capacity".into(),
            data: None,
        })
    }
}

/// Whether the current caller must acquire the stable service turn boundary
/// before applying an LLM identity reconfiguration, and whether a cold
/// attach's tail settle waits for that boundary or runs under the one the
/// caller holds.
#[derive(Clone, Copy)]
pub(crate) enum LlmReconfigureBoundaryOwnership {
    /// Direct control-plane call: acquire the boundary in the adapter.
    Acquire,
    /// Runtime-loop apply: the executor's outer boundary remains held.
    AlreadyHeld,
}

impl LlmReconfigureBoundaryOwnership {
    /// Where this apply's pre-turn staleness check runs.
    fn staleness_position(self) -> LiveStalenessPosition {
        match self {
            Self::Acquire => LiveStalenessPosition::OutsideTurnBoundary,
            Self::AlreadyHeld => LiveStalenessPosition::TurnBoundaryHeld,
        }
    }
}

