/// The WorkGraph store scope must come from the typed realm owner (the realm
/// manifest) — never an invented `"default"` slug. `None` means this
/// persistence bundle carries no realm identity, in which case no default
/// WorkGraph dispatcher is composed and the factory's fail-closed rule
/// (WorkGraph enabled with no dispatcher and no realm identity is a build
/// error) applies.
fn workgraph_default_realm_id(persistence: &PersistenceBundle) -> Option<String> {
    #[cfg(not(target_arch = "wasm32"))]
    if let Some(manifest) = persistence.manifest() {
        return Some(manifest.realm.as_str().to_owned());
    }

    let _ = persistence;
    None
}

fn set_default_workgraph_tools(
    builder: &FactoryAgentBuilder,
    store: Arc<dyn meerkat::WorkGraphStore>,
    default_realm_id: Option<String>,
) {
    let Some(default_realm_id) = default_realm_id else {
        // No realm identity: composing a dispatcher under an invented scope
        // would mint surface-owned store truth. Leave the default slot empty.
        return;
    };
    let service = meerkat::WorkGraphService::with_scope(
        store,
        default_realm_id,
        meerkat::WorkNamespace::default(),
    );
    meerkat::surface::set_default_workgraph_namespace_grant(
        builder,
        Some(service.namespace_grant().clone()),
    );
    let dispatcher =
        Arc::new(meerkat::WorkGraphToolSurface::new(service)) as Arc<dyn AgentToolDispatcher>;
    meerkat::surface::set_default_workgraph_tools(builder, Some(dispatcher));
}

#[derive(Clone, Copy)]
enum GuardedSessionCleanupOperation {
    Archive,
    DiscardLive,
}

#[cfg(test)]
#[derive(Default)]
struct PendingPromotionPreTurnHook {
    reached_flag: std::sync::atomic::AtomicBool,
    reached: Notify,
    release: Notify,
}

async fn await_guarded_session_cleanup(
    service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
    session_id: SessionId,
    operation: GuardedSessionCleanupOperation,
    runtime_cleanup: Option<ArchiveRuntimeCleanup>,
) -> Result<(), SessionError> {
    let result_session_id = session_id.clone();
    let operation_name = match operation {
        GuardedSessionCleanupOperation::Archive => "archive",
        GuardedSessionCleanupOperation::DiscardLive => "discard_live_session",
    };
    let (result_tx, result_rx) = tokio::sync::oneshot::channel();
    tokio::spawn(async move {
        let result = match operation {
            GuardedSessionCleanupOperation::Archive => match runtime_cleanup.as_ref() {
                Some(cleanup) => cleanup.archive_service(&service, &session_id).await,
                None => Err(SessionError::Agent(
                    meerkat_core::error::AgentError::InternalError(
                        "runtime-backed archive cleanup requires MachineSessionArchiveProtocol"
                            .to_string(),
                    ),
                )),
            },
            GuardedSessionCleanupOperation::DiscardLive => {
                service.discard_live_session(&session_id).await
            }
        };
        if matches!(operation, GuardedSessionCleanupOperation::Archive)
            && matches!(result, Ok(()) | Err(SessionError::NotFound { .. }))
            && let Some(cleanup) = runtime_cleanup.as_ref()
            && let Err(error) = cleanup.run(&session_id).await
        {
            let _ = result_tx.send(Err(error));
            return;
        }
        let _ = result_tx.send(result);
    });
    result_rx
        .await
        .map_err(|_| {
            SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
                "session service {operation_name} task ended before reporting a result for {result_session_id}"
            )))
        })?
}

#[allow(clippy::too_many_arguments)]
async fn await_guarded_staged_archive(
    service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
    staged_sessions: Arc<StagedSessionRegistry>,
    staged_capacity_admissions: StagedCapacityAdmissions,
    mut staged_capacity_admission: Option<ActiveCapacityGuard>,
    runtime_cleanup: ArchiveRuntimeCleanup,
    session_id: SessionId,
    mut staged_archive_guard: StagedArchiveRollbackGuard,
    #[cfg(test)] after_service_hook: Option<Arc<PendingPromotionPreTurnHook>>,
) -> Result<(), SessionError> {
    let result_session_id = session_id.clone();
    let (result_tx, result_rx) = tokio::sync::oneshot::channel();
    tokio::spawn(async move {
        let result = match runtime_cleanup.archive_service(&service, &session_id).await {
            Ok(()) | Err(SessionError::NotFound { .. }) => {
                if let Err(error) = runtime_cleanup.run(&session_id).await {
                    let _ = staged_sessions.restore_archive(&session_id).await;
                    staged_archive_guard.disarm();
                    if let Some(admission) = staged_capacity_admission.take() {
                        restore_staged_capacity_admission(
                            &staged_capacity_admissions,
                            session_id.clone(),
                            admission,
                        );
                    }
                    let _ = result_tx.send(Err(error));
                    return;
                }
                #[cfg(test)]
                if let Some(hook) = after_service_hook {
                    hook.reached_flag
                        .store(true, std::sync::atomic::Ordering::SeqCst);
                    hook.reached.notify_waiters();
                    hook.release.notified().await;
                }
                let _ = staged_sessions.finish_archive(&session_id).await;
                staged_archive_guard.disarm();
                drop(staged_capacity_admission.take());
                Ok(())
            }
            Err(err) => {
                let _ = staged_sessions.restore_archive(&session_id).await;
                staged_archive_guard.disarm();
                if let Some(admission) = staged_capacity_admission.take() {
                    restore_staged_capacity_admission(
                        &staged_capacity_admissions,
                        session_id.clone(),
                        admission,
                    );
                }
                Err(err)
            }
        };
        let _ = result_tx.send(result);
    });
    result_rx
        .await
        .map_err(|_| {
            SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
                "session service staged archive task ended before reporting a result for {result_session_id}"
            )))
        })?
}

async fn await_session_archive_with_runtime_cleanup(
    service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
    runtime_cleanup: ArchiveRuntimeCleanup,
    session_id: SessionId,
) -> Result<(), SessionError> {
    let result_session_id = session_id.clone();
    let (result_tx, result_rx) = tokio::sync::oneshot::channel();
    tokio::spawn(async move {
        let result = runtime_cleanup.archive_service(&service, &session_id).await;
        let service_not_found = matches!(&result, Err(SessionError::NotFound { .. }));
        if (result.is_ok() || service_not_found)
            && let Err(error) = runtime_cleanup.run(&session_id).await
        {
            let _ = result_tx.send(Err(error));
            return;
        }
        let _ = result_tx.send(result);
    });
    result_rx.await.map_err(|_| {
        SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
            "session service archive task ended before reporting a result for {result_session_id}"
        )))
    })?
}

pub(crate) use meerkat::session_runtime::staged_promotion::{
    PendingPromotionCleanup, PendingPromotionCleanupMode,
};

/// Body-free archive and presence answer for `session_id`'s committed
/// source: `None` when no committed session exists, otherwise whether the
/// RuntimeStore holds an absorbing archive terminal for it.
///
/// It reads [`PersistentSessionService::observe_live_durable_source`], which
/// applies the archive rule of `session_archived_by_authority` (a rule that
/// never reads the body) and never materializes the session body. A body read
/// of the committed boundary refuses with `TranscriptRevisionConflict` from a
/// durable run's first HeadCanonical round commit until its boundary commit,
/// so a precheck that needs only presence and archive state reads no body. A
/// classification this build does not know is a fault, never presence.
async fn committed_source_archived(
    service: &PersistentSessionService<FactoryAgentBuilder>,
    session_id: &SessionId,
) -> Result<Option<bool>, SessionError> {
    match service.observe_live_durable_source(session_id).await? {
        meerkat::LiveDurableSourceObservation::Absent => Ok(None),
        meerkat::LiveDurableSourceObservation::Archived => Ok(Some(true)),
        meerkat::LiveDurableSourceObservation::Committed { .. } => Ok(Some(false)),
        other => Err(SessionError::Agent(
            meerkat_core::error::AgentError::InternalError(format!(
                "the durable source of session {session_id} answered a classification this build does not know: {other:?}"
            )),
        )),
    }
}

#[cfg(feature = "mob")]
type RpcMobCallbackRouteSlots = Arc<
    StdMutex<
        HashMap<meerkat_mob::MobId, Vec<Weak<crate::callback_dispatcher::MobCallbackRouteSlot>>>,
    >,
>;

#[cfg(feature = "mob")]
type RpcMobActorWitnesses = Arc<StdRwLock<HashMap<SessionId, meerkat::LiveSessionActorWitness>>>;

#[cfg(feature = "mob")]
struct RpcMobSessionService {
    service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
    staged_sessions: Arc<StagedSessionRegistry>,
    runtime_adapter: Arc<MeerkatMachine>,
    mob_state: Arc<StdRwLock<Option<Arc<meerkat_mob_mcp::MobMcpState>>>>,
    actor_witnesses: RpcMobActorWitnesses,
    runtime_actor_witness_slots:
        Arc<StdRwLock<HashMap<SessionId, meerkat::LiveSessionActorWitnessSlot>>>,
    runtime_publication_handles: Arc<StdRwLock<HashMap<SessionId, RpcPublicationAttachment>>>,
    /// The runtime's admission and registration fence: a member session is a
    /// registration on the runtime, refused once its shutdown began.
    registration_fence: Arc<RuntimeRegistrationFence>,
    #[cfg(test)]
    direct_create_after_ack_hook: Option<Arc<PendingPromotionPreTurnHook>>,
}

#[cfg(feature = "mob")]
impl RpcMobSessionService {
    fn archive_runtime_cleanup(&self) -> ArchiveRuntimeCleanup {
        ArchiveRuntimeCleanup {
            runtime_adapter: Arc::clone(&self.runtime_adapter),
            pending_session_event_streams: None,
            mcp_state: None,
            #[cfg(feature = "mob")]
            mob_state: self.mob_state.read().ok().and_then(|slot| {
                slot.as_ref().map(|state| {
                    Arc::new(RpcMobStateAdapter {
                        state: Arc::clone(state),
                    }) as Arc<dyn ArchiveRuntimeMobState>
                })
            }),
            #[cfg(not(feature = "mob"))]
            mob_state: None,
        }
    }

    // Each part is a distinct runtime-owned handle the service shares with
    // the runtime that composes it; none has a default.
    #[allow(clippy::too_many_arguments)]
    fn new(
        service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
        staged_sessions: Arc<StagedSessionRegistry>,
        runtime_adapter: Arc<MeerkatMachine>,
        mob_state: Arc<StdRwLock<Option<Arc<meerkat_mob_mcp::MobMcpState>>>>,
        actor_witnesses: RpcMobActorWitnesses,
        runtime_actor_witness_slots: Arc<
            StdRwLock<HashMap<SessionId, meerkat::LiveSessionActorWitnessSlot>>,
        >,
        runtime_publication_handles: Arc<StdRwLock<HashMap<SessionId, RpcPublicationAttachment>>>,
        registration_fence: Arc<RuntimeRegistrationFence>,
    ) -> Self {
        Self {
            service,
            staged_sessions,
            runtime_adapter,
            mob_state,
            actor_witnesses,
            runtime_actor_witness_slots,
            runtime_publication_handles,
            registration_fence,
            #[cfg(test)]
            direct_create_after_ack_hook: None,
        }
    }

    #[cfg(test)]
    fn with_direct_create_after_ack_hook(mut self, hook: Arc<PendingPromotionPreTurnHook>) -> Self {
        self.direct_create_after_ack_hook = Some(hook);
        self
    }

    fn ensure_create_session_id(req: &mut CreateSessionRequest) -> SessionId {
        let build = req.build.get_or_insert_with(Default::default);
        if let Some(session) = build.resume_session.as_ref() {
            return session.id().clone();
        }
        let session_id = SessionId::new();
        build.mint_session_with_id(session_id.clone());
        session_id
    }

    fn record_actor_witness(&self, actor_witness: meerkat::LiveSessionActorWitness) {
        self.actor_witnesses
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(actor_witness.session_id().clone(), actor_witness);
    }

    fn publication_attachment_witness(
        &self,
        session_id: &SessionId,
    ) -> Option<meerkat_runtime::RuntimeExecutorAttachmentWitness> {
        self.runtime_publication_handles
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(session_id)
            .map(|attachment| attachment.witness.clone())
    }

    fn clear_publication_sidecars_if_current(
        &self,
        session_id: &SessionId,
        expected_attachment: Option<&meerkat_runtime::RuntimeExecutorAttachmentWitness>,
    ) {
        clear_rpc_publication_sidecars_if_current(
            session_id,
            expected_attachment,
            &self.runtime_publication_handles,
            &self.runtime_actor_witness_slots,
            &self.actor_witnesses,
        );
    }

    fn capture_published_actor(
        &self,
        actor_witness_slot: &meerkat::LiveSessionActorWitnessSlot,
        result: meerkat_core::RunResult,
    ) -> Result<meerkat_core::RunResult, SessionError> {
        let actor_witness = actor_witness_slot.witness().ok_or_else(|| {
            SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
                "session service materialized {} without publishing exact actor authority",
                result.session_id
            )))
        })?;
        if actor_witness.session_id() != &result.session_id {
            return Err(SessionError::Agent(
                meerkat_core::error::AgentError::InternalError(format!(
                    "session service published actor authority for {}, not materialized session {}",
                    actor_witness.session_id(),
                    result.session_id
                )),
            ));
        }
        self.record_actor_witness(actor_witness);
        Ok(result)
    }

    fn is_pre_run_start_turn_failure(result: &Result<RunResult, SessionError>) -> bool {
        matches!(
            result,
            Err(SessionError::Agent(
                meerkat_core::error::AgentError::NoPendingBoundary
            ))
        )
    }

    pub(crate) fn is_pre_run_apply_runtime_turn_failure(
        result: &Result<CoreApplyOutput, SessionError>,
    ) -> bool {
        matches!(
            result,
            Err(SessionError::Agent(
                meerkat_core::error::AgentError::NoPendingBoundary
            ))
        ) || matches!(
            result,
            Ok(output) if matches!(output.terminal, Some(CoreApplyTerminal::NoPendingBoundary))
        )
    }

    fn is_archived_create_rejection(error: &SessionError) -> bool {
        matches!(error, SessionError::NotFound { .. })
    }

    async fn pending_live_first_turn_is_still_deferred(
        service: &PersistentSessionService<FactoryAgentBuilder>,
        session_id: &SessionId,
    ) -> Result<bool, SessionError> {
        service.live_deferred_first_turn_pending(session_id).await
    }

    async fn should_restore_deferred_start_turn_admission(
        service: &PersistentSessionService<FactoryAgentBuilder>,
        session_id: &SessionId,
        result: &Result<RunResult, SessionError>,
    ) -> Result<bool, SessionError> {
        if Self::is_pre_run_start_turn_failure(result) {
            return Ok(true);
        }
        if result.is_err() {
            Self::pending_live_first_turn_is_still_deferred(service, session_id).await
        } else {
            Ok(false)
        }
    }

    async fn should_restore_deferred_apply_runtime_turn_admission(
        service: &PersistentSessionService<FactoryAgentBuilder>,
        session_id: &SessionId,
        result: &Result<CoreApplyOutput, SessionError>,
    ) -> Result<bool, SessionError> {
        if Self::is_pre_run_apply_runtime_turn_failure(result) {
            return Ok(true);
        }
        if result.is_err() {
            Self::pending_live_first_turn_is_still_deferred(service, session_id).await
        } else {
            Ok(false)
        }
    }

    async fn reject_archived_persisted_session(
        &self,
        session_id: &SessionId,
    ) -> Result<(), SessionError> {
        self.reject_archived_persisted_session_with_boundary_mode(session_id, false)
            .await
    }

    async fn reject_archived_persisted_session_under_runtime_turn_boundary(
        &self,
        session_id: &SessionId,
    ) -> Result<(), SessionError> {
        self.reject_archived_persisted_session_with_boundary_mode(session_id, true)
            .await
    }

    async fn reject_archived_persisted_session_with_boundary_mode(
        &self,
        session_id: &SessionId,
        turn_boundary_already_held: bool,
    ) -> Result<(), SessionError> {
        if committed_source_archived(&self.service, session_id).await? == Some(true) {
            if self.staged_sessions.contains(session_id).await {
                return Ok(());
            }
            // Keep the runtime registration as the retry anchor until live
            // state has been discarded successfully. The machine-owned
            // unregister saga runs only after that phase is proven complete.
            let discard_result = if turn_boundary_already_held {
                self.service
                    .discard_live_session_under_runtime_turn_boundary(session_id)
                    .await
            } else {
                self.service.discard_live_session(session_id).await
            };
            match discard_result {
                Ok(()) | Err(SessionError::NotFound { .. }) => {}
                Err(error) => return Err(error),
            }
            // A runtime-owned apply already holds the exact executor. It must
            // return NotFound so the outer runtime can publish a typed teardown
            // and hand that executor back before the machine-owned unregister
            // saga runs. Direct service calls have no such handback boundary
            // and can complete #875's cleanup immediately.
            if !turn_boundary_already_held {
                self.archive_runtime_cleanup().run(session_id).await?;
            }
            return Err(SessionError::NotFound {
                id: session_id.clone(),
            });
        }
        Ok(())
    }

    async fn reserve_turn_admission(
        &self,
        session_id: &SessionId,
    ) -> Result<ActiveCapacityGuard, SessionError> {
        self.service
            .reserve_runtime_turn_admission(session_id)
            .await
    }

    async fn await_guarded_start_turn(
        service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
        runtime_adapter: Arc<MeerkatMachine>,
        session_id: SessionId,
        req: StartTurnRequest,
        admission: ActiveCapacityGuard,
    ) -> Result<RunResult, SessionError> {
        let result_session_id = session_id.clone();
        let (result_tx, result_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let result = service
                .run_machine_committed_live_turn(
                    MachineServiceTurnCommitProtocol::from_machine(runtime_adapter.as_ref()),
                    &session_id,
                    req,
                    admission,
                )
                .await
                .map_err(|(error, _admission)| error);
            let _ = result_tx.send(result);
        });
        result_rx
            .await
            .map_err(|_| {
                SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
                    "session service start_turn task ended before reporting a result for {result_session_id}"
                )))
            })?
    }

    async fn await_guarded_apply_runtime_turn(
        service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
        session_id: SessionId,
        run_id: RunId,
        req: StartTurnRequest,
        boundary: RunApplyBoundary,
        contributing_input_ids: Vec<InputId>,
        admission: ActiveCapacityGuard,
    ) -> Result<CoreApplyOutput, SessionError> {
        let result_session_id = session_id.clone();
        let (result_tx, result_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let result = service
                .apply_runtime_turn_with_reserved_admission(
                    &session_id,
                    run_id,
                    req,
                    boundary,
                    contributing_input_ids,
                    admission,
                )
                .await;
            let _ = result_tx.send(result);
        });
        result_rx
            .await
            .map_err(|_| {
                SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
                    "session service apply_runtime_turn task ended before reporting a result for {result_session_id}"
                )))
            })?
    }

    async fn await_guarded_create_session(
        service: Arc<PersistentSessionService<FactoryAgentBuilder>>,
        session_id: SessionId,
        _initial_turn: InitialTurnPolicy,
        req: CreateSessionRequest,
        admission: ActiveCapacityGuard,
        actor_witness_slot: meerkat::LiveSessionActorWitnessSlot,
        #[cfg(test)] after_ack_hook: Option<Arc<PendingPromotionPreTurnHook>>,
    ) -> Result<RunResult, SessionError> {
        let result_session_id = session_id.clone();
        let (result_tx, result_rx) = tokio::sync::oneshot::channel();
        tokio::spawn(async move {
            let result = service
                .create_session_with_reserved_admission_and_actor_witness(
                    req,
                    admission,
                    &actor_witness_slot,
                )
                .await;
            #[cfg(test)]
            if _initial_turn == InitialTurnPolicy::Defer
                && result.is_ok()
                && let Some(hook) = after_ack_hook
            {
                hook.reached_flag
                    .store(true, std::sync::atomic::Ordering::SeqCst);
                hook.reached.notify_waiters();
                hook.release.notified().await;
                if result_tx.is_closed() {
                    let _ = service.discard_live_session(&session_id).await;
                    return;
                }
            }
            let _ = result_tx.send(result);
        });
        result_rx.await.map_err(|_| {
            SessionError::Agent(meerkat_core::error::AgentError::InternalError(format!(
                "session service create_session task ended before reporting a result for {result_session_id}"
            )))
        })?
    }
}

#[cfg(feature = "mob")]
#[async_trait::async_trait]
impl SessionService for RpcMobSessionService {
    async fn read_tool_application_observations(
        &self,
        id: &meerkat_core::SessionId,
    ) -> Result<Vec<meerkat_core::ToolApplicationObservation>, meerkat_core::service::SessionError>
    {
        self.service.read_tool_application_observations(id).await
    }

    async fn tool_application(
        self: Arc<Self>,
        control: Arc<meerkat_core::ToolApplicationControlRequest>,
    ) -> Result<serde_json::Value, SessionError> {
        Arc::clone(&self.service).tool_application(control).await
    }

    async fn create_session(
        &self,
        mut req: CreateSessionRequest,
    ) -> Result<RunResult, SessionError> {
        let initial_turn = req.initial_turn;
        if initial_turn == InitialTurnPolicy::RunImmediately {
            return Err(SessionError::Unsupported(
                "runtime-backed eager create_session must route through the MeerkatMachine service-turn commit protocol"
                    .to_string(),
            ));
        }
        let session_id = Self::ensure_create_session_id(&mut req);
        // This create admits no input (an eager create is refused above), so
        // every rollback of the registration it prepares keeps the inputs
        // that registration recovered from the store (rollback_now): a
        // refused resume of a durable member session ends nothing a later
        // start would run.
        // A member session is a registration on this runtime: none is made
        // once the runtime's shutdown began. The gate is held until the
        // registration below is in place (or, for bindings a mob prepared,
        // until it is known that this create still runs), so a shutdown that
        // begins later waits for it and tears it down with the rest. A mob
        // that prepared the bindings rolls its claim back on this refusal.
        let registration_admission = self
            .registration_fence
            .admit(&session_id)
            .await
            .map_err(runtime_shutting_down_session_error)?;
        if let Some(session) = req
            .build
            .as_ref()
            .and_then(|build| build.resume_session.as_ref())
            && self
                .service
                .session_archived_by_authority(session.id(), session)
                .await?
        {
            return Err(SessionError::NotFound { id: session_id });
        }
        self.reject_archived_persisted_session(&session_id).await?;
        let admission = self.service.reserve_create_session_admission().await?;
        let provided_bindings =
            req.build
                .as_ref()
                .and_then(|build| match &build.runtime_build_mode {
                    meerkat_core::RuntimeBuildMode::SessionOwned(bindings) => Some(bindings),
                    meerkat_core::RuntimeBuildMode::StandaloneEphemeral => None,
                });
        if let Some(bindings) = provided_bindings {
            if bindings.session_id() != &session_id {
                return Err(SessionError::Agent(
                    meerkat_core::error::AgentError::InternalError(format!(
                        "preprepared mob session bindings target {}, not {session_id}",
                        bindings.session_id()
                    )),
                ));
            }
            if !meerkat_runtime::session_runtime_bindings_have_machine_authority(bindings) {
                return Err(SessionError::Agent(
                    meerkat_core::error::AgentError::InternalError(
                        "preprepared mob session bindings are missing MeerkatMachine authority"
                            .to_string(),
                    ),
                ));
            }
        }
        let (bindings, mut prepared_materialization) = match provided_bindings.cloned() {
            Some(bindings) => (bindings, None),
            None => {
                let mut prepared = self
                    .runtime_adapter
                    .prepare_session_materialization(session_id.clone())
                    .await
                    .map_err(|error| {
                        SessionError::Agent(
                            meerkat_core::error::AgentError::InternalError(format!(
                                "failed to prepare runtime materialization for direct mob session {session_id}: {error}"
                            )),
                        )
                    })?;
                if let Err(error) = meerkat::surface::install_prepared_runtime_interrupt_handle(
                    &self.service,
                    &self.runtime_adapter,
                    prepared.bindings(),
                )
                .await
                {
                    let rollback_error = prepared.rollback_now().await.err();
                    let rollback_detail = rollback_error
                        .map(|rollback_error| {
                            format!("; exact rollback also failed: {rollback_error}")
                        })
                        .unwrap_or_default();
                    return Err(SessionError::Agent(
                        meerkat_core::error::AgentError::InternalError(format!(
                            "failed to install prepared runtime handles for direct mob session {session_id}: {error}{rollback_detail}"
                        )),
                    ));
                }
                let bindings = prepared.bindings_clone();
                (bindings, Some(prepared))
            }
        };
        drop(registration_admission);
        req.build
            .get_or_insert_with(Default::default)
            .runtime_build_mode = meerkat_core::RuntimeBuildMode::SessionOwned(bindings);
        let actor_witness_slot = meerkat::LiveSessionActorWitnessSlot::default();
        let result = Self::await_guarded_create_session(
            Arc::clone(&self.service),
            session_id.clone(),
            initial_turn,
            req,
            admission,
            actor_witness_slot.clone(),
            #[cfg(test)]
            self.direct_create_after_ack_hook.clone(),
        )
        .await;
        match result {
            Ok(result) => {
                if let Some(prepared) = prepared_materialization.as_mut() {
                    if result.session_id != session_id {
                        let returned_session_id = result.session_id.clone();
                        let discard_error = self
                            .service
                            .discard_live_session(&returned_session_id)
                            .await
                            .err();
                        let rollback_error = prepared.rollback_now().await.err();
                        let discard_detail = discard_error
                            .map(|error| format!("; returned actor discard also failed: {error}"))
                            .unwrap_or_default();
                        let rollback_detail = rollback_error
                            .map(|error| format!("; exact rollback also failed: {error}"))
                            .unwrap_or_default();
                        return Err(SessionError::Agent(
                            meerkat_core::error::AgentError::InternalError(format!(
                                "direct mob session create returned {returned_session_id}, not prepared session {session_id}{discard_detail}{rollback_detail}"
                            )),
                        ));
                    }
                    if let Err(commit_error) = prepared.commit_actor_unattached().await {
                        let discard_error =
                            self.service.discard_live_session(&session_id).await.err();
                        let rollback_error = prepared.rollback_now().await.err();
                        let discard_detail = discard_error
                            .map(|error| format!("; live actor discard also failed: {error}"))
                            .unwrap_or_default();
                        let rollback_detail = rollback_error
                            .map(|error| format!("; exact rollback also failed: {error}"))
                            .unwrap_or_default();
                        return Err(SessionError::Agent(
                            meerkat_core::error::AgentError::InternalError(format!(
                                "failed to commit prepared runtime materialization for direct mob session {session_id}: {commit_error}{discard_detail}{rollback_detail}"
                            )),
                        ));
                    }
                }
                self.capture_published_actor(&actor_witness_slot, result)
            }
            Err(error) => {
                if let Some(prepared) = prepared_materialization.as_mut()
                    && let Err(rollback_error) = prepared.rollback_now().await
                {
                    return Err(SessionError::Agent(
                        meerkat_core::error::AgentError::InternalError(format!(
                            "direct mob session {session_id} create failed: {error}; exact prepared materialization rollback failed: {rollback_error}"
                        )),
                    ));
                }
                // Provided bindings remain owned by the caller's exact
                // preparation guard. A generic unregister here would race its
                // generation-checked rollback and could erase a same-ID
                // replacement.
                Err(error)
            }
        }
    }

    async fn start_turn(
        &self,
        id: &SessionId,
        req: StartTurnRequest,
    ) -> Result<RunResult, SessionError> {
        self.reject_archived_persisted_session(id).await?;
        if self.staged_sessions.contains(id).await {
            return Err(SessionError::Busy { id: id.clone() });
        }
        let admission = self.reserve_turn_admission(id).await?;
        Self::await_guarded_start_turn(
            Arc::clone(&self.service),
            Arc::clone(&self.runtime_adapter),
            id.clone(),
            req,
            admission,
        )
        .await
    }

    async fn reconcile_runtime_compaction_projections(
        &self,
        id: &SessionId,
        intents: Vec<meerkat_core::CompactionProjectionIntent>,
    ) -> Result<(), SessionError> {
        self.service
            .reconcile_runtime_compaction_projections(id, intents)
            .await
    }

    async fn acknowledge_runtime_compaction_finalization(
        &self,
        id: &SessionId,
        authority: &meerkat_core::CommittedSessionBoundaryAuthority,
    ) -> Result<(), SessionError> {
        self.service
            .acknowledge_runtime_compaction_finalization(id, authority)
            .await
    }

    async fn abort_uncommitted_compaction_projections(
        &self,
        id: &SessionId,
    ) -> Result<(), SessionError> {
        self.service
            .abort_uncommitted_compaction_projections(id)
            .await
    }

    async fn abort_rejected_runtime_run_projections(
        &self,
        id: &SessionId,
    ) -> Result<(), SessionError> {
        self.service
            .abort_rejected_runtime_run_projections(id)
            .await
    }

    async fn interrupt(&self, id: &SessionId) -> Result<(), SessionError> {
        Err(SessionError::Unsupported(format!(
            "interrupt for runtime-backed session {id} must route through SessionRuntime::interrupt / MeerkatMachine::hard_cancel_current_run"
        )))
    }

    async fn cancel_after_boundary(&self, id: &SessionId) -> Result<(), SessionError> {
        Err(SessionError::Unsupported(format!(
            "cancel_after_boundary for runtime-backed session {id} must route through SessionRuntime::interrupt_yielding / MeerkatMachine::cancel_after_boundary"
        )))
    }

    async fn set_session_client(
        &self,
        id: &SessionId,
        client: Arc<dyn meerkat_core::AgentLlmClient>,
    ) -> Result<(), SessionError> {
        self.service.set_session_client(id, client).await
    }

    async fn hot_swap_session_llm_identity(
        &self,
        id: &SessionId,
        client: Arc<dyn meerkat_core::AgentLlmClient>,
        identity: SessionLlmIdentity,
        request_policy: meerkat_core::SessionLlmRequestPolicy,
    ) -> Result<(), SessionError> {
        self.service
            .hot_swap_session_llm_identity(id, client, identity, request_policy)
            .await
    }

    async fn set_session_tool_visibility_state(
        &self,
        id: &SessionId,
        state: Option<meerkat_core::SessionToolVisibilityState>,
    ) -> Result<(), SessionError> {
        self.service
            .set_session_tool_visibility_state(id, state)
            .await
    }

    async fn update_session_mob_authority_context(
        &self,
        id: &SessionId,
        authority_context: Option<MobToolAuthorityContext>,
    ) -> Result<(), SessionError> {
        self.service
            .update_session_mob_authority_context(id, authority_context)
            .await
    }

    async fn update_session_mcp_attachment_intent(
        &self,
        id: &SessionId,
        mutation: meerkat_core::McpAttachmentIntentMutation,
    ) -> Result<meerkat_core::McpAttachmentIntentRecorded, SessionError> {
        Arc::clone(&self.service)
            .update_session_mcp_attachment_intent_owned(id, mutation)
            .await
    }

    async fn has_live_session(&self, id: &SessionId) -> Result<bool, SessionError> {
        self.service.has_live_session(id).await
    }

    async fn set_session_tool_filter(
        &self,
        id: &SessionId,
        filter: meerkat_core::ToolFilter,
    ) -> Result<(), SessionError> {
        self.service.set_session_tool_filter(id, filter).await
    }

    async fn read(&self, id: &SessionId) -> Result<SessionView, SessionError> {
        self.service.read(id).await
    }

    async fn list(&self, query: SessionQuery) -> Result<Vec<SessionSummary>, SessionError> {
        self.service.list(query).await
    }

    async fn archive(&self, id: &SessionId) -> Result<(), SessionError> {
        if self.staged_sessions.contains(id).await {
            return Err(SessionError::Busy { id: id.clone() });
        }
        let expected_attachment = self.publication_attachment_witness(id);
        let cleanup = self.archive_runtime_cleanup();
        let result = self
            .service
            .archive_with_machine_protocol(
                id,
                MachineSessionArchiveProtocol::from_machine(self.runtime_adapter.as_ref()),
            )
            .await;
        let service_not_found = matches!(&result, Err(SessionError::NotFound { .. }));
        if result.is_ok() || service_not_found {
            cleanup.run(id).await?;
            self.clear_publication_sidecars_if_current(id, expected_attachment.as_ref());
        }
        result
    }

    async fn subscribe_session_events(&self, id: &SessionId) -> Result<EventStream, StreamError> {
        self.service.subscribe_session_events(id).await
    }

    async fn subscribe_session_events_from(
        &self,
        id: &SessionId,
        cursor: meerkat_core::comms::SessionEventCursor,
    ) -> Result<meerkat_core::comms::SessionEventSubscription, StreamError> {
        self.service.subscribe_session_events_from(id, cursor).await
    }
}

