fn session_error_to_runtime_driver(err: SessionError) -> RuntimeDriverError {
    match err {
        SessionError::NotFound { .. } => RuntimeDriverError::NotReady {
            state: meerkat_runtime::RuntimeState::Destroyed,
        },
        other => RuntimeDriverError::Internal(other.to_string()),
    }
}

fn runtime_driver_error_to_session_error(err: RuntimeDriverError) -> SessionError {
    if let Some(in_progress) = err.teardown_in_progress_session_error() {
        return in_progress;
    }
    SessionError::Agent(meerkat_core::error::AgentError::InternalError(
        err.to_string(),
    ))
}

pub(crate) fn runtime_driver_error_to_rpc(err: RuntimeDriverError) -> RpcError {
    #[cfg(feature = "local-authorization")]
    if let Some(detail) = meerkat::surface::native_admission_error_detail(&err) {
        return match detail.to_wire_error() {
            Ok(wire) => RpcError {
                code: wire.code.jsonrpc_code(),
                message: wire.message.into_owned(),
                data: wire.details,
            },
            Err(_) => RpcError {
                code: error::INTERNAL_ERROR,
                message: "input error projection unavailable".into(),
                data: None,
            },
        };
    }
    // A teardown that outlived its bounded wait is still running: answer the
    // retryable busy class with its typed data, not an internal error.
    if let Some(in_progress) = err.teardown_in_progress_session_error() {
        return session_error_to_rpc(in_progress);
    }
    // A session another runtime owner hosts keeps its typed refusal (#1813).
    if let Some(hosting) = err.hosting_session_error() {
        return session_error_to_rpc(hosting);
    }
    match err {
        RuntimeDriverError::ValidationFailed { reason } => RpcError {
            code: error::INVALID_PARAMS,
            message: reason,
            data: None,
        },
        // The caller reused a key for different input: its own parameters
        // conflict, and the data names the input the key is bound to.
        RuntimeDriverError::InputIdempotencyConflict { existing_id } => RpcError {
            code: error::INVALID_PARAMS,
            message: format!("input idempotency conflicts with existing input {existing_id}"),
            data: Some(serde_json::json!({
                "code": "INPUT_IDEMPOTENCY_CONFLICT",
                "existing_id": existing_id.to_string(),
            })),
        },
        // The runtime's lifecycle state admits no such request now.
        RuntimeDriverError::NotReady { state } => RpcError {
            code: error::INVALID_REQUEST,
            message: format!("the session runtime is {state} and does not admit this request"),
            data: None,
        },
        RuntimeDriverError::NotFound { runtime_id } => RpcError {
            code: error::SESSION_NOT_FOUND,
            message: format!("runtime not found: {runtime_id}"),
            data: None,
        },
        RuntimeDriverError::Destroyed => RpcError {
            code: error::SESSION_NOT_FOUND,
            message: "runtime destroyed".to_string(),
            data: None,
        },
        // Nothing was registered or admitted; the refusal clears once the
        // consent owner's settlement completes.
        error @ RuntimeDriverError::ConsentOwnerLossUnsettled { .. } => RpcError {
            code: meerkat_contracts::ErrorCode::SessionRuntimeUnavailable.jsonrpc_code(),
            message: error.to_string(),
            data: None,
        },
        RuntimeDriverError::Internal(message) => RpcError {
            code: error::INTERNAL_ERROR,
            message,
            data: None,
        },
        other => RpcError {
            code: error::INTERNAL_ERROR,
            message: other.to_string(),
            data: None,
        },
    }
}

fn combine_rpc_cleanup_error(
    mut primary_error: RpcError,
    _cleanup_error: impl std::fmt::Display,
    _context: &str,
) -> RpcError {
    primary_error.message.push_str("; required cleanup failed");
    primary_error
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum InterruptNoopTarget {
    Present,
    Missing,
}

fn interrupt_noop_target_for_presence(present: bool) -> InterruptNoopTarget {
    if present {
        InterruptNoopTarget::Present
    } else {
        InterruptNoopTarget::Missing
    }
}

