    /// The runtime's default MCP credential source (see
    /// [`meerkat::default_mcp_auth_resolver`]).
    #[cfg(feature = "mcp")]
    pub fn default_mcp_auth_resolver(&self) -> Option<Arc<dyn meerkat::McpAuthResolver>> {
        let persistence = match self.provider_auth_persistence() {
            Ok(persistence) => persistence,
            Err(error) => {
                tracing::warn!(error = %error, "provider-auth persistence unavailable for MCP OAuth");
                None
            }
        };
        // A realm's sessions resolve only that realm's MCP credentials.
        let authority = self.provider_auth_runtime_authority();
        match self.realm_id() {
            Some(realm) => {
                meerkat::default_mcp_auth_resolver_in_realm(persistence, authority, realm)
            }
            None => meerkat::default_mcp_auth_resolver(persistence, authority),
        }
    }

