    fn archive_runtime_cleanup(&self) -> ArchiveRuntimeCleanup {
        ArchiveRuntimeCleanup {
            runtime_adapter: Arc::clone(&self.runtime_adapter),
            pending_session_event_streams: Some(Arc::clone(&self.pending_session_event_streams)),
            #[cfg(feature = "mcp")]
            mcp_state: Some(Arc::new(RpcMcpStateAdapter {
                sessions: Arc::clone(&self.mcp_sessions),
            }) as Arc<dyn ArchiveRuntimeMcpState>),
            #[cfg(not(feature = "mcp"))]
            mcp_state: None,
            #[cfg(feature = "mob")]
            mob_state: self.mob_state().map(|state| {
                Arc::new(RpcMobStateAdapter { state }) as Arc<dyn ArchiveRuntimeMobState>
            }),
            #[cfg(not(feature = "mob"))]
            mob_state: None,
        }
    }

    async fn cleanup_recovered_runtime_if_new(
        &self,
        session_id: &SessionId,
        runtime_was_registered: bool,
    ) -> Result<(), SessionError> {
        if runtime_was_registered {
            return Ok(());
        }
        self.archive_runtime_cleanup().run(session_id).await
    }

    async fn combine_with_recovered_runtime_cleanup(
        &self,
        session_id: &SessionId,
        runtime_was_registered: bool,
        primary_error: RpcError,
        context: &'static str,
    ) -> RpcError {
        match self
            .cleanup_recovered_runtime_if_new(session_id, runtime_was_registered)
            .await
        {
            Ok(()) => primary_error,
            Err(cleanup_error) => {
                tracing::warn!(
                    session_id = %session_id,
                    error = %cleanup_error,
                    context,
                    "recovered runtime cleanup failed"
                );
                combine_rpc_cleanup_error(primary_error, cleanup_error, context)
            }
        }
    }

