    pub async fn fail_assistant_output_publication(
        &self,
        session_id: &SessionId,
        address: &meerkat_live::LiveAssistantOutputAddress,
    ) -> Result<(), SessionError> {
        let reservation = self
            .runtime_adapter
            .reserve_live_assistant_output_handle(
                session_id,
                &address.channel_id,
                &address.output_id,
            )
            .await
            .map_err(|error| {
                SessionError::Agent(meerkat_core::error::AgentError::ConfigError(
                    error.to_string(),
                ))
            })?;
        let handle = reservation.handle();
        let (response_id, item_id, content_index) = handle.__target().ok_or_else(|| {
            SessionError::Agent(meerkat_core::error::AgentError::ConfigError(
                "assistant output publication failure has no exact target".to_string(),
            ))
        })?;
        self.service
            .commit_live_assistant_playback_truncation(
                session_id,
                address.channel_id.clone(),
                handle.interaction_id(),
                response_id.clone(),
                item_id,
                content_index,
                meerkat_core::LiveAssistantPlaybackEvidence::Unmeasured,
            )
            .await?;
        self.runtime_adapter
            .commit_live_assistant_output_terminal(reservation)
            .map_err(|error| {
                SessionError::Agent(meerkat_core::error::AgentError::ConfigError(
                    error.to_string(),
                ))
            })?;
        self.append_realtime_transcript_event(
            session_id,
            meerkat_core::RealtimeTranscriptEvent::AssistantTurnInterrupted { response_id },
        )
        .await?;
        Ok(())
    }

    /// Return distinct in-flight provider `response_id`s for the realtime
    /// transcript state of `session_id`. CC4: lets the live projection sink
    /// fan `AssistantTurnInterrupted` events to every staged response on
    /// barge-in so deltas-in-flight do not survive into the next turn's
    /// `AssistantTurnCompleted` materializer sweep.
    pub async fn in_flight_realtime_assistant_response_ids(
        &self,
        session_id: &SessionId,
    ) -> Result<Vec<String>, SessionError> {
        let Some(session) = self.service.load_authoritative_session(session_id).await? else {
            return Ok(Vec::new());
        };
        Ok(session.in_flight_realtime_assistant_response_ids())
    }

    /// The concrete persistent service (phase 6b: `ServiceMemberLiveHost`
    /// composition on the live-capable RPC surface).
    pub(crate) fn persistent_service(&self) -> Arc<PersistentSessionService<FactoryAgentBuilder>> {
        Arc::clone(&self.service)
    }

    #[cfg(feature = "mob")]
    pub fn session_service(&self) -> Arc<dyn meerkat_mob::MobSessionService> {
        Arc::new(RpcMobSessionService::new(
            Arc::clone(&self.service),
            Arc::clone(&self.staged_sessions),
            Arc::clone(&self.runtime_adapter),
            Arc::clone(&self.mob_state),
            Arc::clone(&self.mob_actor_witnesses),
            Arc::clone(&self.runtime_actor_witness_slots),
            Arc::clone(&self.runtime_publication_handles),
            Arc::clone(&self.runtime_registration_fence),
        ))
    }

    /// Pre-initialize the process-default callback channel and return the
    /// receiver half.
    ///
    /// For a single-client stdio/embedded server: call this before any code
    /// that reads `callback_request_tx()` (e.g. mob resume that invokes an
    /// `ExternalToolsProvider`). The server constructor that accepts a
    /// pre-created rx reuses this route instead of creating a new one.
    /// Connection-owned TCP servers do not use this route.
    pub fn init_callback_channel(&self) -> mpsc::Receiver<CallbackRequestEnvelope> {
        let (tx, rx) = mpsc::channel(crate::NOTIFICATION_CHANNEL_CAPACITY);
        self.install_default_callback_route(crate::callback_dispatcher::CallbackRoute::new(tx));
        rx
    }

    /// Replace the process-default callback route.
    ///
    /// Deprecated: a runtime shared by several connections must not have one
    /// connection overwrite another's route. Connection-owned servers keep
    /// their route on their own router; use [`Self::init_callback_channel`]
    /// for the single-client default channel.
    #[deprecated(
        since = "0.8.51",
        note = "callback routes are connection-owned; use init_callback_channel for the single-client default route"
    )]
    pub fn set_callback_channel(
        &self,
        tx: mpsc::Sender<CallbackRequestEnvelope>,
        id_counter: Arc<std::sync::atomic::AtomicU64>,
    ) {
        self.install_default_callback_route(crate::callback_dispatcher::CallbackRoute::from_parts(
            tx,
            id_counter,
            Arc::new(crate::callback_dispatcher::CallbackToolRegistry::default()),
        ));
    }

    fn install_default_callback_route(&self, route: crate::callback_dispatcher::CallbackRoute) {
        *self
            .default_callback_route
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(route);
    }

    /// The process-default callback route, if one was initialized.
    pub fn default_callback_route(&self) -> Option<crate::callback_dispatcher::CallbackRoute> {
        self.default_callback_route
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    }

    /// Get a clone of the process-default callback request sender, if configured.
    pub fn callback_request_tx(&self) -> Option<mpsc::Sender<CallbackRequestEnvelope>> {
        self.default_callback_route().map(|route| route.sender())
    }

    /// Get the process-default callback ID counter.
    pub fn callback_id_counter(&self) -> Arc<std::sync::atomic::AtomicU64> {
        self.default_callback_route()
            .map(|route| route.id_counter())
            .unwrap_or_default()
    }

    /// Get the process-default callback registry mutation/epoch authority.
    pub fn callback_tool_registry(&self) -> Arc<crate::callback_dispatcher::CallbackToolRegistry> {
        self.default_callback_route()
            .map(|route| route.registry())
            .unwrap_or_else(
                || Arc::new(crate::callback_dispatcher::CallbackToolRegistry::default()),
            )
    }

    /// Build a dispatcher on the process-default callback route.
    pub fn callback_tool_dispatcher(
        &self,
        inline_tools: Vec<meerkat_core::ToolDef>,
    ) -> Option<crate::callback_dispatcher::CallbackToolDispatcher> {
        let route = self.default_callback_route()?;
        Some(self.callback_tool_dispatcher_for_route(&route, inline_tools))
    }

    /// Build a dispatcher bound to one exact callback route.
    pub fn callback_tool_dispatcher_for_route(
        &self,
        route: &crate::callback_dispatcher::CallbackRoute,
        inline_tools: Vec<meerkat_core::ToolDef>,
    ) -> crate::callback_dispatcher::CallbackToolDispatcher {
        match self.realm_id() {
            Some(realm_id) => {
                crate::callback_dispatcher::CallbackToolDispatcher::from_route_with_job_runtime(
                    route,
                    inline_tools,
                    realm_id.to_string(),
                    self.job_store.clone(),
                    self.blob_store(),
                )
            }
            None => {
                crate::callback_dispatcher::CallbackToolDispatcher::from_route(route, inline_tools)
            }
        }
    }

    /// Build a dispatcher for a mob's members on the mob's claimable
    /// callback route slot: it follows every later claim of the slot.
    #[cfg(feature = "mob")]
    pub fn callback_tool_dispatcher_for_mob_slot(
        &self,
        slot: &Arc<crate::callback_dispatcher::MobCallbackRouteSlot>,
        inline_tools: Vec<meerkat_core::ToolDef>,
    ) -> crate::callback_dispatcher::CallbackToolDispatcher {
        match self.realm_id() {
            Some(realm_id) => {
                crate::callback_dispatcher::CallbackToolDispatcher::from_mob_slot_with_job_runtime(
                    Arc::clone(slot),
                    inline_tools,
                    realm_id.to_string(),
                    self.job_store.clone(),
                    self.blob_store(),
                )
            }
            None => crate::callback_dispatcher::CallbackToolDispatcher::from_mob_slot(
                Arc::clone(slot),
                inline_tools,
            ),
        }
    }

    /// Index `slot` as the newest callback route slot of the mob `mob_id`,
    /// once that mob is in the mob state's managed set (a build whose mob
    /// never gets there is never indexed).
    ///
    /// Slots nothing holds any more leave the index. An earlier slot under
    /// the same id stays until it dies (a mob re-created under the id of one
    /// still shutting down), and the lookup skips it.
    #[cfg(feature = "mob")]
    pub(crate) fn index_mob_callback_route_slot(
        &self,
        mob_id: meerkat_mob::MobId,
        slot: &Arc<crate::callback_dispatcher::MobCallbackRouteSlot>,
    ) {
        let mut slots = self
            .mob_callback_route_slots
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        slots.retain(|_, indexed| {
            indexed.retain(|slot| slot.strong_count() > 0);
            !indexed.is_empty()
        });
        slots.entry(mob_id).or_default().push(Arc::downgrade(slot));
    }

    /// The newest callback route slot of the mob `mob_id` that its members
    /// still hold.
    #[cfg(feature = "mob")]
    pub(crate) fn mob_callback_route_slot(
        &self,
        mob_id: &meerkat_mob::MobId,
    ) -> Option<Arc<crate::callback_dispatcher::MobCallbackRouteSlot>> {
        self.mob_callback_route_slots
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(mob_id)
            .and_then(|indexed| indexed.iter().rev().find_map(Weak::upgrade))
    }

    /// Bind `session_id` to the callback route it was created on.
    pub fn bind_session_callback_route(
        &self,
        session_id: SessionId,
        route: crate::callback_dispatcher::CallbackRoute,
    ) {
        self.session_callback_routes
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(session_id, route);
    }

    /// The callback route `session_id` is bound to, falling back to the
    /// process-default route for an unbound session. Never another
    /// connection's route.
    pub fn session_callback_route(
        &self,
        session_id: &SessionId,
    ) -> Option<crate::callback_dispatcher::CallbackRoute> {
        self.session_callback_routes
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(session_id)
            .cloned()
            .or_else(|| self.default_callback_route())
    }

    fn unbind_session_callback_route(&self, session_id: &SessionId) {
        self.session_callback_routes
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(session_id);
    }

    /// P1#5: attach the live adapter host so the runtime can fan out
    /// `Refresh`/`Close` commands to active live channels when an upstream
    /// model/provider resolution change requires a re-seed.
    ///
    /// Takes `&self` so it can be called after the runtime is wrapped in
    /// `Arc` (matches the `set_callback_channel` pattern). Called by
    /// `RpcServer`/router construction immediately after `with_live_ws`.
    pub fn set_live_adapter_host(&self, host: Arc<meerkat_live::LiveAdapterHost>) {
        if let Ok(mut slot) = self.live_adapter_host.write() {
            *slot = Some(host);
        }
    }

    /// Read the current live adapter host, if attached.
    pub fn live_adapter_host(&self) -> Option<Arc<meerkat_live::LiveAdapterHost>> {
        self.live_adapter_host
            .read()
            .ok()
            .and_then(|guard| guard.clone())
    }

    async fn active_live_channel_for_session(
        &self,
        session_id: &SessionId,
    ) -> Option<(
        Arc<meerkat_live::LiveAdapterHost>,
        meerkat_live::LiveChannelId,
    )> {
        let host = self.live_adapter_host()?;
        let channel_id = self
            .runtime_adapter
            .live_active_channel_for_session(session_id)
            .await?;
        if matches!(
            host.channel_session(&channel_id).await,
            Ok(bound_session_id) if &bound_session_id == session_id
        ) {
            Some((host, channel_id))
        } else {
            None
        }
    }

    fn live_text_from_runtime_primitive(primitive: &RunPrimitive) -> Option<String> {
        let mut parts = Vec::new();
        let prompt = primitive.model_projection_content_input().text_content();
        if !prompt.trim().is_empty() {
            parts.push(prompt);
        }
        let text = parts.join("\n\n").trim().to_string();
        (!text.is_empty()).then_some(text)
    }

    async fn live_interrupt_requested_for_runtime_primitive(
        &self,
        session_id: &SessionId,
        primitive: &RunPrimitive,
    ) -> bool {
        let contributing_input_ids = primitive.contributing_input_ids();
        if contributing_input_ids.is_empty() {
            return false;
        }
        // #338: the admission transition emits the typed `live_interrupt_required`
        // verdict, carried end-to-end on the per-input
        // `MeerkatAdmittedInputSnapshot`. The shell reads the machine-owned fact
        // exclusively — there is no `handling_mode == Steer` re-derivation, not
        // even from the primitive's own turn metadata (that projection carries
        // the queue-normalized execution mode, not live-interrupt intent).
        self.runtime_adapter
            .meerkat_machine_spine_snapshot(session_id)
            .await
            .is_some_and(|snapshot| {
                snapshot.inputs.admission_order.iter().any(|input| {
                    input.live_interrupt_required
                        && contributing_input_ids.contains(&input.input_id)
                })
            })
    }

    /// Project runtime-routed peer/external input into an active live adapter.
    ///
    /// A live-only session can receive peer ingress while the provider-hosted
    /// realtime conversation is already open. In that case the runtime loop is
    /// still the admission/receipt authority, but the apply side is the live
    /// adapter, not a second vanilla LLM turn. The adapter will project the
    /// resulting provider observations back into canonical session history.
    pub(crate) async fn try_forward_runtime_primitive_to_live_adapter(
        &self,
        session_id: &SessionId,
        run_id: RunId,
        primitive: &RunPrimitive,
    ) -> Result<Option<CoreApplyOutput>, String> {
        let Some((host, channel_id)) = self.active_live_channel_for_session(session_id).await
        else {
            return Ok(None);
        };
        let Some(text) = Self::live_text_from_runtime_primitive(primitive) else {
            return Ok(None);
        };

        if self
            .live_interrupt_requested_for_runtime_primitive(session_id, primitive)
            .await
        {
            host.send_command(
                &channel_id,
                meerkat_core::live_adapter::LiveAdapterCommand::Interrupt,
            )
            .await
            .map_err(|err| err.to_string())?;
        }

        host.send_command(
            &channel_id,
            meerkat_core::live_adapter::LiveAdapterCommand::SendInput {
                chunk: meerkat_core::live_adapter::LiveInputChunk::Text { text },
            },
        )
        .await
        .map_err(|err| err.to_string())?;

        let message_count = self
            .load_persisted_session(session_id)
            .await
            .ok()
            .flatten()
            .map(|session| session.messages().len())
            .unwrap_or(0);

        let receipt = RunBoundaryReceiptDraft {
            run_id,
            boundary: primitive.apply_boundary(),
            contributing_input_ids: primitive.contributing_input_ids().to_vec(),
            conversation_digest: None,
            message_count,
        };
        Ok(Some(CoreApplyOutput::without_terminal(receipt, None)))
    }

    /// Phase 4 R1: thin RPC shim — delegates to
    /// `LiveOrchestrator::propagate_config_to_live_channels`.
    ///
    /// The hot-swap rule is: skip when the session's current model
    /// already equals the new global; otherwise propagate. See
    /// `should_apply_global_model_hot_swap` for the rationale (s72
    /// regression fix: a session that pinned a model at `session/create`
    /// against a different global must still re-resolve when the global
    /// is patched, so the next `live/open` precheck enforces B19 against
    /// the new resolution).
    pub async fn propagate_config_to_live_channels(&self) -> LiveConfigPropagationReport {
        let snapshot = self.realm_context_snapshot();
        let cleanup = self.archive_runtime_cleanup();
        self.live_orchestrator(&snapshot, cleanup, None)
            .propagate_config_to_live_channels()
            .await
    }

    /// Refused, and logged, once shutdown has started.
    #[cfg(feature = "mob")]
    pub fn set_mob_state(&self, mob_state: Arc<meerkat_mob_mcp::MobMcpState>) {
        if let Ok(mut slot) = self.mob_state.write() {
            if self.mob_composition_closed.load(Ordering::SeqCst) {
                tracing::warn!("mob state not set: the runtime is shutting down");
                return;
            }
            *slot = Some(mob_state);
        }
    }

    #[cfg(feature = "mob")]
    pub fn mob_state(&self) -> Option<Arc<meerkat_mob_mcp::MobMcpState>> {
        self.mob_state.read().ok().and_then(|slot| slot.clone())
    }

    /// Replace the notification sink used by lazily-created session executors.
    ///
    /// Called by `serve_tcp_connection` when a new TCP client connects — each
    /// connection has its own transport writer so the sink must be updated to
    /// route events to the currently-connected client.
    /// Read the current notification sink (for use by executors at apply time).
    pub fn current_notification_sink(&self) -> crate::router::NotificationSink {
        self.notification_sink
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    }

    pub fn set_notification_sink(&self, sink: crate::router::NotificationSink) {
        if let Ok(mut slot) = self.notification_sink.write() {
            *slot = sink;
        }
    }

    /// Wire an external comms runtime as the peer-ingress source for a session.
    ///
    /// This enables the session to receive incoming comms messages (peer
    /// requests/responses) between turns. The session must already be
    /// registered via `create_session` (which calls `prepare_bindings`).
    ///
    /// The comms drain starts once an executor is attached (i.e., on the first
    /// `turn/start`). Calling this before the first turn is safe — the drain
    /// context is stored and will be reconciled when the executor materializes.
    ///
    /// Used by the kennel hive agent where the comms runtime is shared at the
    /// factory level (not per-session via `comms_name`).
    #[cfg(feature = "comms")]
    pub async fn enable_comms_drain(
        self: &Arc<Self>,
        session_id: &meerkat_core::types::SessionId,
        comms_runtime: Arc<dyn meerkat_core::agent::CommsRuntime>,
    ) -> Result<(), RpcError> {
        // Only store the comms context — don't create an executor yet.
        // The executor is created lazily on first turn/start, and it needs
        // the per-connection notification sink (not the startup noop sink).
        self.runtime_adapter
            .update_peer_ingress_context(session_id, true, Some(comms_runtime))
            .await
            .map_err(runtime_driver_error_to_rpc)?;
        Ok(())
    }

    /// Wire an external comms runtime and eagerly attach the runtime executor.
    ///
    /// Long-lived autonomous hosts, such as remote TUX targets, must drain
    /// incoming peer requests even when no user-driven `turn/start` is
    /// currently active. This keeps peer ingress on the same runtime surface
    /// used by RPC/TUX turns instead of relying on a separate helper surface.
    #[cfg(feature = "comms")]
    pub async fn enable_autonomous_comms_drain(
        self: &Arc<Self>,
        session_id: &meerkat_core::types::SessionId,
        comms_runtime: Arc<dyn meerkat_core::agent::CommsRuntime>,
    ) -> Result<(), RpcError> {
        self.ensure_runtime_executor(session_id).await?;
        self.runtime_adapter
            .update_peer_ingress_context(session_id, true, Some(comms_runtime))
            .await
            .map_err(runtime_driver_error_to_rpc)?;
        Ok(())
    }

    /// SESSION-OWNED half of the `live/open` peer-ingress reconciliation
    /// (DEC-P6B-L5): `live/open` may be the first thing that materializes a
    /// deferred keep-alive session, which never runs a `turn/start`, so the
    /// turn-owned comms drain reconciliation never fires. The mob-owned
    /// skip now lives in the shared pipeline
    /// (`LiveOrchestrator::ensure_live_peer_ingress`) — the ONE owner of
    /// that fact; this body carries only the RPC-private executor + drain
    /// context reconciliation, reached via [`RpcLiveIngressReconciler`].
    #[cfg(feature = "comms")]
    async fn ensure_session_owned_live_ingress_impl(
        self: &Arc<Self>,
        session_id: &meerkat_core::types::SessionId,
    ) -> Result<(), meerkat::session_runtime::errors::LiveIngressError> {
        use meerkat::session_runtime::errors::LiveIngressError;

        let keep_alive = self
            .persisted_keep_alive(session_id)
            .await
            .map_err(|err| LiveIngressError::Internal(err.message))?;
        let peer_ingress_enabled = self
            .preserve_existing_peer_ingress(session_id, keep_alive)
            .await
            .map_err(|err| LiveIngressError::Internal(err.message))?;
        if !peer_ingress_enabled {
            return Ok(());
        }

        let comms_rt = self.service.comms_runtime(session_id).await;
        if keep_alive
            && comms_rt.is_none()
            && !self
                .runtime_adapter
                .session_has_comms(session_id)
                .await
                .map_err(|err| {
                    LiveIngressError::Internal(runtime_driver_error_to_rpc(err).message)
                })?
        {
            // ADJ-P6B-8: the frozen INVALID_PARAMS message is the typed
            // variant's fixed text — this hook never re-authors it.
            return Err(LiveIngressError::InvalidSession);
        }

        self.ensure_runtime_executor(session_id)
            .await
            .map_err(|err| LiveIngressError::Internal(err.message))?;
        if let Some(comms_rt) = comms_rt {
            self.runtime_adapter
                .update_peer_ingress_context(session_id, true, Some(comms_rt))
                .await
                .map_err(|err| {
                    LiveIngressError::Internal(runtime_driver_error_to_rpc(err).message)
                })?;
        }
        Ok(())
    }

    pub fn set_skill_identity_registry(&self, registry: SourceIdentityRegistry) {
        if let Ok(mut slot) = self.skill_identity_registry.write() {
            slot.registry = registry;
        }
    }

    pub fn set_skill_identity_registry_for_generation(
        &self,
        generation: u64,
        registry: SourceIdentityRegistry,
    ) {
        if let Ok(mut slot) = self.skill_identity_registry.write()
            && generation >= slot.generation
        {
            slot.generation = generation;
            slot.registry = registry;
        }
    }

    pub(crate) async fn ensure_runtime_executor(
        self: &Arc<Self>,
        session_id: &SessionId,
    ) -> Result<(), RpcError> {
        self.ensure_runtime_executor_on_adapter(&self.runtime_adapter, session_id)
            .await
    }

    /// [`Self::ensure_runtime_executor`] for an apply that may already hold
    /// the session's turn-finalization boundary (see
    /// [`Self::prepare_cold_attach_with_turn_boundary`]).
    async fn ensure_runtime_executor_with_turn_boundary(
        self: &Arc<Self>,
        session_id: &SessionId,
        boundary: LlmReconfigureBoundaryOwnership,
    ) -> Result<(), RpcError> {
        self.ensure_runtime_executor_on_adapter_with_turn_boundary(
            &self.runtime_adapter,
            session_id,
            boundary,
        )
        .await
    }

    /// The typed refusal of work that reaches admission or registration
    /// after this runtime's shutdown began: `-32032` (session runtime
    /// unavailable) with `data.kind` `runtime_shutting_down`. Nothing of the
    /// request was registered or admitted, so none of it runs in this
    /// process.
    fn runtime_shutting_down_rpc(session_id: &SessionId) -> RpcError {
        RpcError {
            code: meerkat_contracts::ErrorCode::SessionRuntimeUnavailable.jsonrpc_code(),
            message: format!(
                "the session runtime is shutting down and admits no work for session {session_id}"
            ),
            data: Some(serde_json::json!({
                "kind": RUNTIME_SHUTTING_DOWN_KIND,
                "session_id": session_id.to_string(),
            })),
        }
    }

    /// The typed refusal of an input to a session whose task ended with the
    /// host's runtime it ran on, once the session's registration waits for
    /// its reload: `-32032` (session runtime unavailable) with `data.kind`
    /// `host_runtime_stopped`. The first such input was admitted and its
    /// pre-dequeue check degraded the registration; the registration admits
    /// nothing until it reloads, and a reload in this process would only meet
    /// the stopped runtime again. Nothing of the input was admitted, so
    /// nothing is kept for it: it is sent again after the session's next
    /// start.
    fn host_runtime_stopped_rpc(session_id: &SessionId) -> RpcError {
        RpcError {
            code: meerkat_contracts::ErrorCode::SessionRuntimeUnavailable.jsonrpc_code(),
            message: format!(
                "session {session_id} lost its session task to the runtime it ran on, and its \
                 registration waits for a reload at the session's next start; the input was not \
                 admitted"
            ),
            data: Some(serde_json::json!({
                "kind": HOST_RUNTIME_STOPPED_KIND,
                "session_id": session_id.to_string(),
            })),
        }
    }

    /// Refuse a request that reaches admission after this runtime's shutdown
    /// began ([`Self::runtime_shutting_down_rpc`]).
    ///
    /// A request can wait before its admission for as long as a turn runs:
    /// its staleness check waits on the turn boundary the running turn
    /// holds. The shutdown's registration teardown neither keeps nor answers
    /// such a request, because nothing of it is in the runtime yet, so it
    /// must not be admitted once the shutdown began: it would register its
    /// session again on a runtime that has stopped, and run there. Ingress
    /// asks this after the waits that come before its admission.
    pub(crate) fn refuse_admission_after_shutdown(
        &self,
        session_id: &SessionId,
    ) -> Result<(), RpcError> {
        self.runtime_registration_fence.refuse(session_id)
    }

    /// Admit one new runtime registration of `session_id`, or refuse it once
    /// this runtime's shutdown began. The returned guard holds the
    /// registration gate shared: hold it until the registration is in place,
    /// so the shutdown, which closes the gate exclusively before its
    /// registration teardown takes its snapshot, either waits for this
    /// registration and tears it down, or makes this path refuse.
    async fn admit_runtime_registration(
        &self,
        session_id: &SessionId,
    ) -> Result<tokio::sync::RwLockReadGuard<'_, bool>, RpcError> {
        self.runtime_registration_fence.admit(session_id).await
    }

    /// Close runtime registration for the shutdown:
    /// - refuse every later admission and registration;
    /// - close the mob state's admission, so the state admits no new mob
    ///   and every mob it manages refuses new members, work, flows and
    ///   resumes (`AdmissionClosed`, reason `StandDown`): a mob registers no
    ///   member session from then on;
    /// - wait, within [`RUNTIME_REGISTRATION_CLOSE_GRACE`], for the
    ///   registrations already under way, the mob session service's
    ///   included, so the registration teardown's snapshot includes them.
    ///
    /// A registration still under way at the bound, or a mob admission that
    /// did not close, is logged; nothing new is admitted either way.
    async fn close_runtime_registration(&self) {
        self.runtime_registration_fence.begin_close();
        #[cfg(feature = "mob")]
        self.close_mob_admission_for_shutdown().await;
        self.runtime_registration_fence.finish_close().await;
    }

    /// Close the mob state's admission for the shutdown
    /// ([`meerkat_mob_mcp::MobMcpState::close_admission`]), within
    /// [`MOB_STATE_STAND_DOWN_GRACE`]. The state's stand-down, later in the
    /// shutdown, closes it again (it is idempotent) and reports what did not
    /// settle.
    #[cfg(feature = "mob")]
    async fn close_mob_admission_for_shutdown(&self) {
        let Some(state) = self.mob_state() else {
            return;
        };
        let deadline = std::time::Instant::now() + MOB_STATE_STAND_DOWN_GRACE;
        match state.close_admission(deadline).await {
            meerkat_mob_mcp::MobStateStandDown::Clean => {}
            unsettled => tracing::warn!(
                ?unsettled,
                "the mob state's admission did not close cleanly at the start of the shutdown"
            ),
        }
    }

    pub(crate) fn runtime_actor_witness_slot(
        &self,
        session_id: &SessionId,
    ) -> meerkat::LiveSessionActorWitnessSlot {
        self.runtime_actor_witness_slots
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .entry(session_id.clone())
            .or_default()
            .clone()
    }

    fn replace_runtime_actor_witness_slot(
        &self,
        session_id: &SessionId,
    ) -> meerkat::LiveSessionActorWitnessSlot {
        let slot = meerkat::LiveSessionActorWitnessSlot::default();
        self.runtime_actor_witness_slots
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(session_id.clone(), slot.clone());
        slot
    }

    fn runtime_actor_witness(
        &self,
        session_id: &SessionId,
    ) -> Result<meerkat::LiveSessionActorWitness, RpcError> {
        self.runtime_actor_witness_slots
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(session_id)
            .and_then(meerkat::LiveSessionActorWitnessSlot::witness)
            .filter(meerkat::LiveSessionActorWitness::is_live)
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "session {session_id} has no captured live actor authority for runtime executor publication"
                ),
                data: None,
            })
    }

    fn record_runtime_publication_handle(
        &self,
        witness: meerkat_runtime::RuntimeExecutorAttachmentWitness,
        publication_handle: crate::session_executor::RpcRuntimePublicationHandle,
        owner: RpcPublicationOwner,
    ) {
        #[cfg(feature = "mob")]
        if matches!(&owner, RpcPublicationOwner::Persistent) {
            self.mob_actor_witnesses
                .write()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .remove(witness.session_id());
        }
        self.runtime_publication_handles
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(
                witness.session_id().clone(),
                RpcPublicationAttachment {
                    witness,
                    publication_handle,
                    owner,
                },
            );
    }

    fn publication_attachment_witness(
        &self,
        session_id: &SessionId,
    ) -> Option<meerkat_runtime::RuntimeExecutorAttachmentWitness> {
        self.runtime_publication_handles
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(session_id)
            .map(|attachment| attachment.witness.clone())
    }

    fn clear_publication_sidecars_if_current(
        &self,
        session_id: &SessionId,
        expected_attachment: Option<&meerkat_runtime::RuntimeExecutorAttachmentWitness>,
    ) -> bool {
        clear_rpc_publication_sidecars_if_current(
            session_id,
            expected_attachment,
            &self.runtime_publication_handles,
            &self.runtime_actor_witness_slots,
            #[cfg(feature = "mob")]
            &self.mob_actor_witnesses,
        )
    }

    fn runtime_publication_handle_for_attachment(
        &self,
        witness: &meerkat_runtime::RuntimeExecutorAttachmentWitness,
    ) -> Result<crate::session_executor::RpcRuntimePublicationHandle, RpcError> {
        let attachments = self
            .runtime_publication_handles
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        attachments
            .get(witness.session_id())
            .filter(|attachment| attachment.witness == *witness)
            .map(|attachment| attachment.publication_handle.clone())
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "runtime attachment for session {} has no exact RPC publication authority",
                    witness.session_id()
                ),
                data: None,
            })
    }

    /// Whether work this runtime routes to `witness`, a session's committed
    /// executor attachment on `adapter`, reaches an owner that publishes it:
    /// this runtime, through its exact publication authority for that
    /// attachment, or, for a mob member, the member's own mob runtime, whose
    /// exact publisher for the attachment serves the live actor the mob
    /// published to this runtime. An attachment served by neither is refused.
    async fn require_attachment_publication_authority(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        witness: &meerkat_runtime::RuntimeExecutorAttachmentWitness,
    ) -> Result<(), RpcError> {
        let missing = match self.runtime_publication_handle_for_attachment(witness) {
            Ok(_) => return Ok(()),
            Err(missing) => missing,
        };
        #[cfg(feature = "mob")]
        if self.mob_actor_publishes_attachment(adapter, witness).await {
            return Ok(());
        }
        #[cfg(not(feature = "mob"))]
        let _ = adapter;
        Err(missing)
    }

    /// Whether `witness` is the attachment a mob member's own mob runtime
    /// published for the live actor the mob published to this runtime. The
    /// mob must own the session, and the machine's exact publisher for the
    /// attachment (same machine, epoch and attachment, with its retained
    /// capability) must serve that very actor. The publisher and the actor's
    /// liveness are read after the awaited ownership queries, so an
    /// attachment replaced or an actor revoked meanwhile is refused.
    #[cfg(feature = "mob")]
    async fn mob_actor_publishes_attachment(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        witness: &meerkat_runtime::RuntimeExecutorAttachmentWitness,
    ) -> bool {
        let session_id = witness.session_id();
        let Some(mob_state) = self.mob_state() else {
            return false;
        };
        let Ok(actor_witness) = self.mob_actor_witness(session_id) else {
            return false;
        };
        let owned = mob_state.owns_live_bridge_session(session_id).await
            || mob_state.owns_persisted_bridge_session(session_id).await;
        if !owned {
            return false;
        }
        let Ok(publisher) = adapter
            .publication_handle_for_executor_attachment(witness)
            .await
        else {
            return false;
        };
        let actor = actor_witness.executor_actor_identity();
        publisher
            .actor_identity()
            .is_some_and(|serving| serving.is_same_actor(&actor))
            && actor.is_live()
    }

    fn actor_publication_refresh_callback(
        &self,
        session_id: &SessionId,
    ) -> meerkat::surface::AttachedActorPublicationRefreshFn {
        let expected_session_id = session_id.clone();
        let runtime_publication_handles = Arc::clone(&self.runtime_publication_handles);
        let runtime_actor_witness_slots = Arc::clone(&self.runtime_actor_witness_slots);
        let persistent_service = Arc::clone(&self.service);
        #[cfg(feature = "mob")]
        let mob_actor_witnesses = Arc::clone(&self.mob_actor_witnesses);

        Arc::new(
            move |attachment_witness, actor_witness, actor_witness_slot| {
                if attachment_witness.session_id() != &expected_session_id
                    || actor_witness.session_id() != &expected_session_id
                    || !actor_witness.is_live()
                {
                    return Err(RuntimeDriverError::StaleAuthority {
                        reason: format!(
                            "RPC actor publication refresh for session {expected_session_id} received mismatched or stale exact authority"
                        ),
                    });
                }

                #[cfg(feature = "mob")]
                let publication_owner;
                let publication_handle = {
                    let attachments = runtime_publication_handles
                        .read()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    let attachment = attachments
                        .get(&expected_session_id)
                        .filter(|attachment| attachment.witness == *attachment_witness)
                        .ok_or_else(|| RuntimeDriverError::StaleAuthority {
                            reason: format!(
                                "RPC actor publication refresh for session {expected_session_id} does not own the prepared executor attachment and publication owner"
                            ),
                        })?;
                    #[cfg(feature = "mob")]
                    {
                        publication_owner = attachment.owner.clone();
                    }
                    attachment.publication_handle.clone()
                };

                #[cfg(feature = "mob")]
                let immutable_actor_handle = match &publication_owner {
                    RpcPublicationOwner::Mob { session_service } => {
                        crate::session_executor::mob_runtime_publication_handle_for_actor(
                            Arc::clone(session_service),
                            actor_witness.clone(),
                        )
                    }
                    RpcPublicationOwner::Persistent => {
                        meerkat::surface::persistent_runtime_publication_handle(
                            Arc::clone(&persistent_service),
                            actor_witness.clone(),
                        )
                    }
                };
                #[cfg(not(feature = "mob"))]
                let immutable_actor_handle =
                    meerkat::surface::persistent_runtime_publication_handle(
                        Arc::clone(&persistent_service),
                        actor_witness,
                    );

                // This callback runs while PreparedAttachedSessionActorRecovery
                // still owns the exact attachment mutation fence. The exact map
                // comparison above therefore cannot be invalidated by a pending
                // successor factory before these local authorities advance to B.
                publication_handle.replace(Arc::clone(&immutable_actor_handle));
                runtime_actor_witness_slots
                    .write()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .insert(expected_session_id.clone(), actor_witness_slot);
                #[cfg(feature = "mob")]
                {
                    let mut witnesses = mob_actor_witnesses
                        .write()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    match publication_owner {
                        RpcPublicationOwner::Mob { .. } => {
                            witnesses.insert(expected_session_id.clone(), actor_witness);
                        }
                        RpcPublicationOwner::Persistent => {
                            witnesses.remove(&expected_session_id);
                        }
                    }
                }
                Ok(immutable_actor_handle)
            },
        )
    }

    fn session_runtime_executor_for_actor_slot(
        self: &Arc<Self>,
        session_id: SessionId,
        attachment_witness: meerkat_runtime::RuntimeExecutorAttachmentWitness,
        actor_witness_slot: meerkat::LiveSessionActorWitnessSlot,
    ) -> Box<dyn meerkat_core::lifecycle::CoreExecutor> {
        let executor = crate::session_executor::SessionRuntimeExecutor::new_for_actor_slot(
            Arc::clone(self),
            session_id.clone(),
            actor_witness_slot.clone(),
        );
        self.record_runtime_publication_handle(
            attachment_witness,
            executor.replaceable_publication_handle(),
            RpcPublicationOwner::Persistent,
        );
        self.runtime_actor_witness_slots
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(session_id, actor_witness_slot);
        Box::new(executor)
    }

    #[cfg(feature = "mob")]
    pub(crate) fn mob_actor_witness(
        &self,
        session_id: &SessionId,
    ) -> Result<meerkat::LiveSessionActorWitness, RpcError> {
        self.mob_actor_witnesses
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(session_id)
            .filter(|actor_witness| actor_witness.is_live())
            .cloned()
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "mob session {session_id} has no captured live actor authority for runtime executor publication"
                ),
                data: None,
            })
    }

    async fn runtime_executor_actor_authority(
        self: &Arc<Self>,
        session_id: &SessionId,
    ) -> Result<RpcExecutorActorAuthority, RpcError> {
        #[cfg(feature = "mob")]
        {
            if let Some(mob_state) = self.mob_state().as_ref()
                && (mob_state.owns_live_bridge_session(session_id).await
                    || mob_state.owns_persisted_bridge_session(session_id).await)
            {
                let actor_witness = self.mob_actor_witness(session_id)?;
                let sink = self
                    .notification_sink
                    .read()
                    .ok()
                    .map(|slot| slot.clone())
                    .unwrap_or_else(crate::router::NotificationSink::noop);
                return Ok(RpcExecutorActorAuthority::Mob {
                    session_service: mob_state.session_service(),
                    actor_witness,
                    notification_sink: sink,
                });
            }
        }

        match self.runtime_actor_witness(session_id) {
            Ok(actor_witness) => Ok(RpcExecutorActorAuthority::PersistentWitness(actor_witness)),
            Err(missing_authority) => {
                // An actor whose task ended with the host's runtime it ran on
                // is not live: it takes no commands, and the live read asks
                // it and fails. The executor attached here meets it at its
                // pre-dequeue check, which leaves the input to the session's
                // next registration.
                let live_actor_exists = !self
                    .service
                    .session_task_ended_with_its_runtime(session_id)
                    .await
                    && match self.service.has_live_session(session_id).await {
                        Ok(exists) => exists,
                        Err(SessionError::NotFound { .. }) => false,
                        Err(error) => return Err(session_error_to_rpc(error)),
                    };
                if live_actor_exists {
                    return Err(missing_authority);
                }
                Ok(RpcExecutorActorAuthority::PersistentSlot(
                    self.runtime_actor_witness_slot(session_id),
                ))
            }
        }
    }

    fn runtime_executor_for_session(
        self: &Arc<Self>,
        session_id: SessionId,
        attachment_witness: meerkat_runtime::RuntimeExecutorAttachmentWitness,
        actor_authority: RpcExecutorActorAuthority,
    ) -> Box<dyn meerkat_core::lifecycle::CoreExecutor> {
        debug_assert_eq!(attachment_witness.session_id(), &session_id);
        match actor_authority {
            RpcExecutorActorAuthority::PersistentWitness(actor_witness) => {
                let executor = crate::session_executor::SessionRuntimeExecutor::new(
                    Arc::clone(self),
                    actor_witness,
                );
                self.record_runtime_publication_handle(
                    attachment_witness,
                    executor.replaceable_publication_handle(),
                    RpcPublicationOwner::Persistent,
                );
                Box::new(executor)
            }
            RpcExecutorActorAuthority::PersistentSlot(actor_witness_slot) => self
                .session_runtime_executor_for_actor_slot(
                    session_id,
                    attachment_witness,
                    actor_witness_slot,
                ),
            #[cfg(feature = "mob")]
            RpcExecutorActorAuthority::Mob {
                session_service,
                actor_witness,
                notification_sink,
            } => {
                let executor = crate::session_executor::MobRpcRuntimeExecutor::new(
                    Arc::clone(&session_service),
                    Some(Arc::clone(self)),
                    actor_witness,
                    notification_sink,
                );
                self.record_runtime_publication_handle(
                    attachment_witness,
                    executor.replaceable_publication_handle(),
                    RpcPublicationOwner::Mob { session_service },
                );
                Box::new(executor)
            }
        }
    }

    async fn ensure_runtime_executor_on_adapter(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        session_id: &SessionId,
    ) -> Result<(), RpcError> {
        self.ensure_runtime_executor_on_adapter_with_turn_boundary(
            adapter,
            session_id,
            LlmReconfigureBoundaryOwnership::Acquire,
        )
        .await
    }

    async fn ensure_runtime_executor_on_adapter_with_turn_boundary(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        session_id: &SessionId,
        boundary: LlmReconfigureBoundaryOwnership,
    ) -> Result<(), RpcError> {
        // A runtime whose shutdown began registers no session: refuse before
        // any attach work (see `refuse_admission_after_shutdown`). A session
        // it still serves keeps its executor, so the work that executor is
        // applying can still reach it until the registration teardown.
        if self.runtime_registration_fence.is_closing()
            && !adapter
                .session_has_executor(session_id)
                .await
                .map_err(runtime_driver_error_to_rpc)?
        {
            return Err(Self::runtime_shutting_down_rpc(session_id));
        }
        // A session whose task ended with the host's runtime it ran on, and
        // whose registration already waits for its reload, takes no input in
        // this process: the registration admits nothing until it reloads, and
        // a reload here would only meet the stopped runtime again. Refused,
        // typed, before anything is attached (see `host_runtime_stopped_rpc`).
        if self
            .service
            .session_task_ended_with_its_runtime(session_id)
            .await
            && adapter
                .durability_reload_required(session_id)
                .await
                .is_some()
        {
            return Err(Self::host_runtime_stopped_rpc(session_id));
        }
        // An executor means agent work can run, and agent work can author
        // schedules against this runtime's store — the firing host must be
        // live in the same process (see arm_schedule_host_for_agent_tools).
        self.arm_schedule_host_for_agent_tools().await;
        self.prepare_cold_attach_with_turn_boundary(session_id, boundary)
            .await?;
        if self
            .archived_persisted_session_without_live(session_id)
            .await?
        {
            return Err(Self::session_not_found_rpc(session_id));
        }
        // Check for a live executor (not just registration). Sessions
        // registered via `prepare_bindings()` exist in the adapter map but
        // have no RuntimeLoop — inputs would queue without being processed.
        //
        // Executor presence is not readiness: reuse needs the same exact
        // committed attachment and publication authority the boundary-held
        // path below checks (this runtime's, or a mob member's own runtime's).
        // An attachment still pending its commit, or one without that
        // authority, joins that path, which waits for the attaching owner and
        // checks again. This check takes no turn boundary: a running turn
        // holds it for its whole lap, and input admission must not queue
        // behind the turn.
        if adapter
            .session_has_executor(session_id)
            .await
            .map_err(runtime_driver_error_to_rpc)?
            && let Some(witness) = adapter
                .current_executor_attachment_witness(session_id)
                .await
            && self
                .require_attachment_publication_authority(adapter, &witness)
                .await
                .is_ok()
        {
            self.continuation_bindings.source_custody_changed();
            return Ok(());
        }

        // Existence is committed metadata: a session whose durable run is
        // open at a committed round exists, and the attach below, not this
        // read, decides that run's provisional tail.
        let persisted_session_exists = self
            .load_persisted_session_tolerating_tail(session_id)
            .await?
            .is_some();
        let adapter_registration_exists = adapter.contains_session(session_id).await;
        // An actor whose task ended with the host's runtime it ran on is not
        // live: the live read asks it and fails. A registration that already
        // waited for its reload was refused above; for any other, the attach
        // below proceeds, and the attached loop's pre-dequeue check leaves the
        // input to the session's next registration.
        let live_session_exists = !self
            .service
            .session_task_ended_with_its_runtime(session_id)
            .await
            && match self.service.has_live_session(session_id).await {
                Ok(exists) => exists,
                Err(SessionError::NotFound { .. }) => false,
                Err(error) => return Err(session_error_to_rpc(error)),
            };
        let session_exists = adapter_registration_exists
            || self.staged_sessions.contains(session_id).await
            || live_session_exists
            || persisted_session_exists;
        if !session_exists {
            return Err(RpcError {
                code: error::SESSION_NOT_FOUND,
                message: format!("session not found: {session_id}"),
                data: None,
            });
        }

        // Actor witness consumption and attachment follow the canonical B -> M
        // order. Holding B through pending commit prevents the selected actor
        // incarnation from being revoked between sidecar capture and exact
        // executor publication.
        let _actor_attachment_boundary = self
            .service
            .acquire_runtime_turn_finalization_guard(session_id)
            .await;
        if adapter
            .session_has_executor(session_id)
            .await
            .map_err(runtime_driver_error_to_rpc)?
        {
            let witness = adapter
                .current_executor_attachment_witness(session_id)
                .await
                .ok_or_else(|| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "session {session_id} became serving without exact attachment authority"
                    ),
                    data: None,
                })?;
            self.require_attachment_publication_authority(adapter, &witness)
                .await?;
            self.continuation_bindings.source_custody_changed();
            return Ok(());
        }

        // The registration below is admitted through the registration gate
        // and holds it until the attachment is in place: a shutdown that
        // began meanwhile refuses it here, and one that begins later waits
        // for it and tears it down with the rest.
        let _registration_admission = self.admit_runtime_registration(session_id).await?;
        let actor_authority = self.runtime_executor_actor_authority(session_id).await?;
        let runtime = Arc::clone(self);
        let executor_session_id = session_id.clone();
        match adapter
            .ensure_session_with_executor_factory_under_runtime_turn_finalization_boundary(
                session_id.clone(),
                move |witness| {
                    runtime.runtime_executor_for_session(
                        executor_session_id,
                        witness,
                        actor_authority,
                    )
                },
            )
            .await
            .map_err(runtime_driver_error_to_rpc)?
        {
            meerkat_runtime::EnsureRuntimeExecutorAttachment::Pending(mut pending) => {
                if let Err(commit_error) = pending
                    .try_commit_with_under_runtime_turn_finalization_boundary(false, |_| Ok(()))
                    .await
                {
                    let cleanup_error = pending
                        .abort_under_runtime_turn_finalization_boundary()
                        .await
                        .err();
                    return Err(runtime_driver_error_to_rpc(match cleanup_error {
                        Some(cleanup_error) => RuntimeDriverError::Internal(format!(
                            "{commit_error}; boundary-aware exact attachment cleanup also failed: {cleanup_error}"
                        )),
                        None => commit_error,
                    }));
                }
            }
            meerkat_runtime::EnsureRuntimeExecutorAttachment::Existing(witness) => {
                self.require_attachment_publication_authority(adapter, &witness)
                    .await?;
            }
        }
        // Fresh or reused, the session is served by the exact attachment this
        // runtime published. Delivery owners retry what they hold blocked; the
        // announcement grants nothing, they read the actual owners again.
        self.continuation_bindings.source_custody_changed();
        Ok(())
    }

    /// W3-H: install the correct runtime executor for the session, picking
    /// between `SessionRuntimeExecutor` (standalone sessions) and
    /// `MobRpcRuntimeExecutor` (mob-owned bridge sessions). Mirrors the
    /// `MethodRouter::ensure_runtime_session_registered` logic — used by the
    /// realtime WS observer after a MobMember channel's binding rotates to a
    /// new bridge session id (no RPC path crosses, so the pre-dispatch
    /// registration gate doesn't fire; we need to register the replacement
    /// session here so the next status poll does not see NotReady/Destroyed).
    ///
    /// Returns `Ok(())` if the session is already registered, newly registered,
    /// or not found (the observer closes the channel separately on terminal
    /// retire, so "not found after rotation" surfaces as a downstream status
    /// error on the next poll tick).
    #[cfg(feature = "mob")]
    pub async fn ensure_runtime_session_for_rotation(
        self: &Arc<Self>,
        session_id: &SessionId,
    ) -> Result<(), meerkat_core::service::SessionError> {
        let claim = self.service.grant_session_hosting(session_id)?;
        self.service.prepare_cold_attach(session_id, claim).await?;
        self.reject_archived_persisted_session_without_live(session_id)
            .await
            .map_err(|_| meerkat_core::service::SessionError::NotFound {
                id: session_id.clone(),
            })?;
        if self
            .runtime_adapter
            .session_has_executor(session_id)
            .await
            .map_err(runtime_driver_error_to_session_error)?
        {
            return Ok(());
        }
        self.ensure_runtime_executor_on_adapter(&self.runtime_adapter, session_id)
            .await
            .map_err(|error| {
                SessionError::Agent(meerkat_core::error::AgentError::InternalError(
                    error.message,
                ))
            })
    }

    /// Admit a runtime-routed turn's input with its completion waiter.
    async fn accept_turn_input_with_completion(
        &self,
        session_id: &SessionId,
        input: meerkat_runtime::input::Input,
    ) -> Result<
        (
            meerkat_runtime::accept::AcceptOutcome,
            Option<meerkat_runtime::completion::CompletionHandle>,
        ),
        RuntimeDriverError,
    > {
        #[cfg(test)]
        if let Some(fault) = self
            .runtime_accept_fault
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .take()
        {
            return Err(fault);
        }
        self.runtime_adapter
            .accept_input_with_completion(session_id, input)
            .await
    }

    /// Start a turn by routing through the runtime input/completion waiter path.
    ///
    /// Instead of calling `SessionService::start_turn()` directly, this method:
    /// 1. Creates an `Input::Prompt` from the request parameters
    /// 2. Accepts it via `MeerkatMachine::accept_input_with_completion()`
    /// 3. Awaits the completion handle
    /// 4. Returns the `RunResult` produced by the executor
    ///
    /// This ensures all session-driving work flows through the single runtime
    /// authority (the RuntimeLoop → CoreExecutor pipeline).
    #[allow(clippy::too_many_arguments, unused_variables)]
    pub async fn start_turn_via_runtime(
        self: &Arc<Self>,
        session_id: &SessionId,
        prompt: ContentInput,
        injected_context: Vec<ContentInput>,
        mcp_event_tx: mpsc::Sender<EventEnvelope<AgentEvent>>,
        skill_references: Option<Vec<meerkat_core::skills::SkillKey>>,
        turn_tool_overlay: Option<meerkat_core::service::TurnToolOverlay>,
        additional_instructions: Option<Vec<String>>,
        overrides: Option<crate::handlers::turn::TurnOverrides>,
    ) -> Result<RunResult, RpcError> {
        self.start_turn_via_runtime_with_request_context(
            session_id,
            prompt,
            injected_context,
            mcp_event_tx,
            skill_references,
            turn_tool_overlay,
            additional_instructions,
            overrides,
            None,
            true,
        )
        .await
    }

    /// Request-aware variant of [`Self::start_turn_via_runtime`].
    ///
    /// Before admission, cancellation is request-local because no session run
    /// belongs to the request. Once the runtime accepts an exact input, the
    /// action is upgraded to cancel only that accepted input.
    ///
    /// `session_events: false` is the request's opt-out of its turn's
    /// `session/event` copies: the turn applying this request's input writes
    /// none, unless another input of the same turn wants them (see
    /// `Self::turn_writes_session_events`).
    #[allow(clippy::too_many_arguments, unused_variables)]
    pub async fn start_turn_via_runtime_with_request_context(
        self: &Arc<Self>,
        session_id: &SessionId,
        prompt: ContentInput,
        injected_context: Vec<ContentInput>,
        mcp_event_tx: mpsc::Sender<EventEnvelope<AgentEvent>>,
        skill_references: Option<Vec<meerkat_core::skills::SkillKey>>,
        turn_tool_overlay: Option<meerkat_core::service::TurnToolOverlay>,
        additional_instructions: Option<Vec<String>>,
        overrides: Option<crate::handlers::turn::TurnOverrides>,
        request_context: Option<RequestContext>,
        session_events: bool,
    ) -> Result<RunResult, RpcError> {
        use meerkat_runtime::accept::AcceptOutcome;
        use meerkat_runtime::input::{Input, PromptInput};
        #[allow(unused_mut)]
        let mut prompt = prompt;
        // Build settings have no carrier on a runtime-routed turn: refuse
        // them before any session work, deferred sessions included. A
        // system_prompt is not one: it is an ordinary ordered System append
        // applied by the shared StartTurn boundary.
        if let Some(setting) = overrides.as_ref().and_then(|ov| {
            crate::handlers::turn::first_build_setting_on_turn(
                ov.max_tokens.is_some(),
                ov.output_schema.is_some(),
                ov.structured_output_retries.is_some(),
            )
        }) {
            return Err(RpcError {
                code: error::INVALID_PARAMS,
                message: crate::handlers::turn::build_setting_on_turn_message(
                    setting,
                    crate::handlers::turn::SET_BUILD_SETTINGS_ON_CREATE,
                ),
                data: None,
            });
        }
        if request_context
            .as_ref()
            .is_some_and(RequestContext::cancel_already_requested)
        {
            return Err(RpcError {
                code: error::REQUEST_CANCELLED,
                message: "request cancelled before start".to_string(),
                data: None,
            });
        }
        // A dormant mob member's session is woken by its owner before this
        // surface would attach the session on its own.
        self.wake_session_owner_if_unserved(session_id).await?;
        self.prepare_cold_attach(session_id).await?;
        self.reject_archived_persisted_session_without_live(session_id)
            .await?;
        let effective_identity = self
            .effective_llm_identity_for_turn(session_id, overrides.as_ref())
            .await?;
        self.validate_prompt_video_input(&prompt, &effective_identity)
            .await?;
        let workgraph_service = self.workgraph_service().ok();

        // The staleness check waits on a running turn's boundary, so a
        // shutdown may have begun meanwhile: such a turn is refused before it
        // registers or reserves anything, and before the check's own error,
        // which the run the shutdown stopped can cause.
        let stale = self
            .live_session_is_stale(session_id, LiveStalenessPosition::OutsideTurnBoundary)
            .await;
        self.refuse_admission_after_shutdown(session_id)?;
        // Held until this turn re-materializes the session (#1813).
        let _rematerialization_hosting = if stale? {
            self.discard_stale_live_session(session_id).await?
        } else {
            None
        };
        // A help session continues only on its live session: refuse to
        // rebuild it from storage before the turn is admitted.
        let help_session = self.refuse_cold_help_session(session_id).await;
        self.refuse_admission_after_shutdown(session_id)?;
        help_session?;

        let runtime_registration_lock = self.runtime_registration_lock(session_id);
        let runtime_registration_guard = runtime_registration_lock.mutex().lock().await;
        let runtime_was_registered = self.runtime_adapter.contains_session(session_id).await;
        let staged_session_existed = self.staged_sessions.contains(session_id).await;
        let staged_keep_alive = if staged_session_existed {
            self.staged_sessions.keep_alive(session_id).await
        } else {
            None
        };
        let mut pre_admission =
            RuntimePreAdmissionGuard::new(self.reserve_active_turn(session_id).await?);

        // Apply MCP boundary before building the input — staged MCP ops
        // (from mcp/add, mcp/remove, mcp/reload) must be connected and made
        // visible to the agent before the turn starts.
        #[cfg(feature = "mcp")]
        {
            let mut mcp_text = String::new();
            self.apply_mcp_boundary(session_id, &mcp_event_tx, &mut mcp_text)
                .await?;
            if !mcp_text.is_empty() {
                let mut blocks = prompt.into_blocks();
                blocks.insert(
                    0,
                    meerkat_core::types::ContentBlock::Text { text: mcp_text },
                );
                prompt = ContentInput::Blocks(blocks);
            }
        }

        let turn_metadata = Self::typed_text_turn(Self::turn_metadata_from_overrides(
            skill_references,
            turn_tool_overlay,
            additional_instructions,
            overrides.as_ref(),
            Some(effective_identity.provider.as_str()),
        ));

        // Injected context lowers through the prompt input's typed slot so
        // the runtime batch places the InjectedContext-role appends
        // immediately before the user append.
        let input = Input::Prompt(
            PromptInput::from_content_input(prompt, turn_metadata)
                .with_injected_context(injected_context),
        );
        let input_id = input.id().clone();
        // Recorded before the input is admitted, so the executor that applies
        // it already sees the opt-out; held until this request returns.
        let _session_events_opt_out = (!session_events)
            .then(|| self.record_turn_session_events_opt_out(session_id, &input_id));

        if let Err(primary) = self.ensure_runtime_executor(session_id).await {
            return Err(self
                .unregister_new_runtime_registration_after_rpc_error(
                    &self.runtime_adapter,
                    session_id,
                    runtime_was_registered,
                    staged_session_existed,
                    false,
                    primary,
                )
                .await);
        }

        // Manage comms drain lifecycle based on keep_alive override.
        #[cfg(feature = "comms")]
        {
            let keep_alive_override = overrides.as_ref().and_then(|ov| ov.keep_alive);
            let pending_keep_alive_override_applied = if let Some(keep_alive) = keep_alive_override
            {
                match self
                    .apply_pending_keep_alive_override(session_id, keep_alive)
                    .await
                {
                    Ok(applied) => applied,
                    Err(err) => {
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                &self.runtime_adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                false,
                                err,
                            )
                            .await);
                    }
                }
            } else {
                false
            };
            let keep_alive = match keep_alive_override {
                Some(val) => val,
                None => match staged_keep_alive {
                    Some(keep_alive) => keep_alive,
                    None => match self.persisted_keep_alive(session_id).await {
                        Ok(keep_alive) => keep_alive,
                        Err(err) => {
                            return Err(self
                                .unregister_new_runtime_registration_after_rpc_error(
                                    &self.runtime_adapter,
                                    session_id,
                                    runtime_was_registered,
                                    staged_session_existed,
                                    false,
                                    err,
                                )
                                .await);
                        }
                    },
                },
            };
            if !pending_keep_alive_override_applied {
                let comms_rt = self.service.comms_runtime(session_id).await;
                if keep_alive && comms_rt.is_none() {
                    // Check if the runtime adapter already has comms configured
                    // for this session (e.g., via enable_comms_drain). If so,
                    // the session-service comms check is not authoritative.
                    let adapter_has_comms =
                        match self.runtime_adapter.session_has_comms(session_id).await {
                            Ok(has_comms) => has_comms,
                            Err(error) => {
                                return Err(self
                                    .unregister_new_runtime_registration_after_rpc_error(
                                        &self.runtime_adapter,
                                        session_id,
                                        runtime_was_registered,
                                        staged_session_existed,
                                        false,
                                        runtime_driver_error_to_rpc(error),
                                    )
                                    .await);
                            }
                        };
                    let staged_keep_alive_authorized =
                        staged_session_existed && staged_keep_alive == Some(true);
                    if !adapter_has_comms && !staged_keep_alive_authorized {
                        let primary = RpcError {
                            code: error::INVALID_PARAMS,
                            message: "keep_alive requires a session created with comms_name"
                                .to_string(),
                            data: None,
                        };
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                &self.runtime_adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                false,
                                primary,
                            )
                            .await);
                    }
                }
                // RuntimeTurnMetadata is the only carrier for materialized
                // keep_alive mutation. The session service applies it after
                // generated turn-admission feedback; this surface only
                // refreshes machine-owned peer ingress below.
                // W2-G: never reconfigure a mob-owned drain from the session-runtime
                // turn-start path. The mob provisioner owns peer-ingress for its
                // members; the session runtime has no visibility into the mob's
                // comms context and must not substitute its own (this is the
                // s71 silent-downgrade class). The DSL's
                // `AttachSessionIngress` guard would already reject the swap,
                // but we short-circuit here so the turn-start path doesn't emit
                // a spurious WARN for every turn on every mob-owned member.
                let owner = self.runtime_adapter.peer_ingress_owner(session_id).await;
                if owner.is_mob_owned() {
                    tracing::debug!(
                        %session_id,
                        ?owner,
                        "start_turn_via_runtime: mob-owned peer ingress — skipping drain reconfigure"
                    );
                } else {
                    let peer_ingress_enabled = match self
                        .preserve_existing_peer_ingress(session_id, keep_alive)
                        .await
                    {
                        Ok(enabled) => enabled,
                        Err(primary) => {
                            return Err(self
                                .unregister_new_runtime_registration_after_rpc_error(
                                    &self.runtime_adapter,
                                    session_id,
                                    runtime_was_registered,
                                    staged_session_existed,
                                    false,
                                    primary,
                                )
                                .await);
                        }
                    };
                    // Preserve an already-active peer ingress channel for
                    // externally-enabled sessions even when the persisted
                    // keep_alive bit is false. Without this, ordinary turn
                    // routing can accidentally tear down the persistent comms
                    // drain that autonomous peers rely on for between-turn
                    // responses.
                    if (comms_rt.is_some() || peer_ingress_enabled)
                        && let Err(error) = self
                            .runtime_adapter
                            .update_peer_ingress_context(session_id, peer_ingress_enabled, comms_rt)
                            .await
                    {
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                &self.runtime_adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                false,
                                runtime_driver_error_to_rpc(error),
                            )
                            .await);
                    }
                }
            }
        }

        let pre_admission_guard =
            match Self::take_runtime_pre_admission_guard(&mut pre_admission, session_id) {
                Ok(admission) => admission,
                Err(err) => {
                    return Err(self
                        .unregister_new_runtime_registration_after_rpc_error(
                            &self.runtime_adapter,
                            session_id,
                            runtime_was_registered,
                            staged_session_existed,
                            false,
                            err,
                        )
                        .await);
                }
            };
        let pre_admission_registration = match self.register_runtime_pre_admission(
            session_id.clone(),
            input_id.clone(),
            pre_admission_guard,
        ) {
            Ok(registration) => registration,
            Err(err) => {
                return Err(self
                    .unregister_new_runtime_registration_after_rpc_error(
                        &self.runtime_adapter,
                        session_id,
                        runtime_was_registered,
                        staged_session_existed,
                        false,
                        err,
                    )
                    .await);
            }
        };
        let (outcome, handle) = match self
            .accept_turn_input_with_completion(session_id, input)
            .await
        {
            Ok(pair) => pair,
            Err(e) => {
                // An admission refusal keeps its typed code and data.
                let primary = runtime_driver_error_to_rpc(e);
                return Err(self
                    .unregister_new_runtime_registration_after_rpc_error(
                        &self.runtime_adapter,
                        session_id,
                        runtime_was_registered,
                        staged_session_existed,
                        false,
                        primary,
                    )
                    .await);
            }
        };
        if let AcceptOutcome::Accepted {
            input_id: accepted_input_id,
            ..
        } = &outcome
            && let Some(context) = request_context.as_ref()
        {
            let runtime_adapter = Arc::clone(&self.runtime_adapter);
            let cancel_session_id = session_id.clone();
            let cancel_input_id = accepted_input_id.clone();
            let _ = context
                .install_cancel_action_or_cancelled(request_action(move || {
                    let runtime_adapter = Arc::clone(&runtime_adapter);
                    let session_id = cancel_session_id.clone();
                    let input_id = cancel_input_id.clone();
                    async move {
                        if let Err(error) = runtime_adapter
                            .cancel_input_if_present(
                                &session_id,
                                &input_id,
                                "RPC request cancelled",
                            )
                            .await
                        {
                            tracing::warn!(
                                %session_id,
                                %input_id,
                                %error,
                                "exact RPC request input cancellation did not settle"
                            );
                        }
                    }
                }))
                .await;
        }
        // Forward events while waiting for completion
        // (Events are forwarded by the executor's forwarder task,
        // which is spawned inside SessionRuntimeExecutor::apply())

        let Some(handle) = handle else {
            let existing_id = match outcome {
                AcceptOutcome::Deduplicated { existing_id, .. } => existing_id.to_string(),
                _ => "unknown".to_string(),
            };
            let primary = RpcError {
                code: error::DUPLICATE_INPUT,
                message: "input already processed".to_string(),
                data: Some(serde_json::json!({ "existing_id": existing_id })),
            };
            return Err(self
                .unregister_new_runtime_registration_after_rpc_error(
                    &self.runtime_adapter,
                    session_id,
                    runtime_was_registered,
                    staged_session_existed,
                    false,
                    primary,
                )
                .await);
        };

        let waited_input_id = match &outcome {
            AcceptOutcome::Deduplicated { existing_id, .. } => existing_id.clone(),
            AcceptOutcome::Accepted { input_id, .. } => input_id.clone(),
            _ => input_id.clone(),
        };
        let completion_rx = self.spawn_runtime_pre_admission_cleanup_with_outcome(
            session_id.clone(),
            input_id,
            handle,
        );
        pre_admission_registration.disarm();
        drop(runtime_registration_guard);
        drop(runtime_registration_lock);
        let outcome = completion_rx.await.map_err(|_| RpcError {
            code: error::INTERNAL_ERROR,
            message: "runtime completion outcome unavailable after cleanup task ended".to_string(),
            data: Some(serde_json::json!({
                "session_id": session_id.to_string(),
                "reason": "missing_runtime_completion_outcome",
            })),
        })?;
        let outcome = match outcome {
            Ok(outcome) => outcome,
            Err(error) => {
                return Err(self
                    .runtime_completion_wait_error_to_rpc_error(
                        error,
                        session_id,
                        Some(&waited_input_id),
                    )
                    .await);
            }
        };
        completion_outcome_to_rpc_result(outcome, session_id)
    }

    /// Admit a canonical external event through the runtime-backed path.
    pub async fn accept_external_event_via_runtime(
        self: &Arc<Self>,
        session_id: &SessionId,
        event_type: String,
        payload: serde_json::Value,
        blocks: Option<Vec<meerkat_contracts::WireContentBlock>>,
    ) -> Result<meerkat_runtime::AcceptOutcome, RpcError> {
        self.accept_external_event_via_runtime_with_key(
            session_id, event_type, payload, blocks, None,
        )
        .await
    }

    /// [`Self::accept_external_event_via_runtime`] under an optional caller
    /// idempotency key (built by [`meerkat_runtime::IdempotencyKey::caller`]).
    /// The session's input index keeps the key with the admission: a retry
    /// with the same event deduplicates onto it, and other content under the
    /// key is refused as an idempotency conflict.
    pub(crate) async fn accept_external_event_via_runtime_with_key(
        self: &Arc<Self>,
        session_id: &SessionId,
        event_type: String,
        payload: serde_json::Value,
        blocks: Option<Vec<meerkat_contracts::WireContentBlock>>,
        idempotency_key: Option<meerkat_runtime::IdempotencyKey>,
    ) -> Result<meerkat_runtime::AcceptOutcome, RpcError> {
        self.accept_external_event_via_runtime_with_context(
            session_id,
            event_type,
            payload,
            blocks,
            ExternalEventRuntimeContext {
                handling_mode: meerkat_core::types::HandlingMode::Queue,
                idempotency_key,
                correlation_id: None,
            },
        )
        .await
    }

    async fn accept_external_event_via_runtime_with_context(
        self: &Arc<Self>,
        session_id: &SessionId,
        event_type: String,
        payload: serde_json::Value,
        blocks: Option<Vec<meerkat_contracts::WireContentBlock>>,
        context: ExternalEventRuntimeContext,
    ) -> Result<meerkat_runtime::AcceptOutcome, RpcError> {
        use meerkat_runtime::input::{
            ExternalEventInput, Input, InputDurability, InputHeader, InputOrigin, InputVisibility,
        };

        self.prepare_cold_attach(session_id).await?;
        self.reject_archived_persisted_session_without_live(session_id)
            .await?;

        if event_type.trim().is_empty() {
            return Err(RpcError {
                code: error::INVALID_PARAMS,
                message: "event_type cannot be empty".to_string(),
                data: None,
            });
        }

        let blocks = decode_wire_content_blocks(blocks)?;

        let input = Input::ExternalEvent(ExternalEventInput {
            objective_id: None,
            header: InputHeader {
                ingress_context: None,
                retained_resume: None,
                authority_association: None,
                id: meerkat_core::lifecycle::InputId::new(),
                timestamp: chrono::Utc::now(),
                source: InputOrigin::External {
                    source_name: event_type.clone(),
                },
                durability: InputDurability::Durable,
                visibility: InputVisibility::default(),
                idempotency_key: context.idempotency_key,
                supersession_key: None,
                correlation_id: context.correlation_id,
            },
            event_type,
            payload,
            blocks,
            handling_mode: context.handling_mode,
            render_metadata: None,
        });
        let input_id = input.id().clone();

        let runtime_registration_lock = self.runtime_registration_lock(session_id);
        let runtime_registration_guard = runtime_registration_lock.mutex().lock().await;
        let runtime_was_registered = self.runtime_adapter.contains_session(session_id).await;
        let staged_session_existed = self.staged_sessions.contains(session_id).await;

        // The staleness check waits on a running turn's boundary, so a
        // shutdown may have begun meanwhile: the event is refused before its
        // admission, and before the check's own error, which the run the
        // shutdown stopped can cause.
        let stale = self
            .live_session_is_stale(session_id, LiveStalenessPosition::OutsideTurnBoundary)
            .await;
        self.refuse_admission_after_shutdown(session_id)?;
        // Held until the executor below re-registers the session (#1813).
        let _rematerialization_hosting = if stale? {
            self.discard_stale_live_session(session_id).await?
        } else {
            None
        };
        let help_session = self.refuse_cold_help_session(session_id).await;
        self.refuse_admission_after_shutdown(session_id)?;
        help_session?;
        if let Err(primary) = self.ensure_runtime_executor(session_id).await {
            return Err(self
                .unregister_new_runtime_registration_after_rpc_error(
                    &self.runtime_adapter,
                    session_id,
                    runtime_was_registered,
                    staged_session_existed,
                    true,
                    primary,
                )
                .await);
        }

        let mut pre_admission_registration = None;
        let should_pre_admit = match self
            .runtime_adapter
            .input_requires_active_pre_admission_without_wake(session_id, &input)
            .await
        {
            Ok(should_pre_admit) => should_pre_admit,
            Err(error) => {
                return Err(self
                    .unregister_new_runtime_registration_after_rpc_error(
                        &self.runtime_adapter,
                        session_id,
                        runtime_was_registered,
                        staged_session_existed,
                        true,
                        runtime_driver_error_to_rpc(error),
                    )
                    .await);
            }
        };
        let cleanup_protects_active_admission = !should_pre_admit;
        let mut pre_admission = if should_pre_admit {
            match self.reserve_or_join_active_turn(session_id).await {
                Ok(admission) => Some(RuntimePreAdmissionGuard::new(admission)),
                Err(err) => {
                    return Err(self
                        .unregister_new_runtime_registration_after_rpc_error(
                            &self.runtime_adapter,
                            session_id,
                            runtime_was_registered,
                            staged_session_existed,
                            cleanup_protects_active_admission,
                            err,
                        )
                        .await);
                }
            }
        } else {
            None
        };
        if let Some(admission) = pre_admission.as_mut() {
            let admission_guard =
                match Self::take_runtime_pre_admission_guard(admission, session_id) {
                    Ok(admission) => admission,
                    Err(err) => {
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                &self.runtime_adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                cleanup_protects_active_admission,
                                err,
                            )
                            .await);
                    }
                };
            pre_admission_registration = Some(
                match self.register_runtime_pre_admission(
                    session_id.clone(),
                    input_id.clone(),
                    admission_guard,
                ) {
                    Ok(registration) => registration,
                    Err(err) => {
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                &self.runtime_adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                false,
                                err,
                            )
                            .await);
                    }
                },
            );
        }

        let mut result = self
            .runtime_adapter
            .accept_input_without_wake(session_id, input)
            .await
            .map_err(runtime_driver_error_to_rpc);
        result = match result {
            Ok(outcome) => Ok(outcome),
            Err(primary) => Err(self
                .unregister_new_runtime_registration_after_rpc_error(
                    &self.runtime_adapter,
                    session_id,
                    runtime_was_registered,
                    staged_session_existed,
                    cleanup_protects_active_admission,
                    primary,
                )
                .await),
        };
        if let Some(registration) = pre_admission_registration {
            let keep_admission_for_active_input =
                matches!(result, Ok(meerkat_runtime::AcceptOutcome::Accepted { .. }))
                    && self
                        .runtime_adapter
                        .list_active_inputs(session_id)
                        .await
                        .is_ok_and(|inputs| inputs.contains(&input_id));
            if keep_admission_for_active_input {
                self.spawn_runtime_pre_admission_idle_cleanup(session_id.clone(), input_id.clone());
                registration.disarm();
            }
        }
        drop(runtime_registration_guard);
        drop(runtime_registration_lock);
        result
    }

    pub(crate) async fn accept_runtime_input_with_active_admission(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        session_id: &SessionId,
        input: meerkat_runtime::Input,
    ) -> Result<meerkat_runtime::AcceptOutcome, RpcError> {
        self.accept_runtime_input_with_active_admission_typed(adapter, session_id, input)
            .await
            .map_err(RuntimeInputAdmissionFailure::into_rpc)
    }

    async fn accept_runtime_input_with_active_admission_typed(
        self: &Arc<Self>,
        adapter: &Arc<MeerkatMachine>,
        session_id: &SessionId,
        input: meerkat_runtime::Input,
    ) -> Result<meerkat_runtime::AcceptOutcome, RuntimeInputAdmissionFailure> {
        // Held until the admission below re-registers the session (#1813).
        let _rematerialization_hosting = self.prepare_runtime_input_ingress(session_id).await?;
        let input_id = input.id().clone();

        let runtime_registration_lock = self.runtime_registration_lock(session_id);
        let runtime_registration_guard = runtime_registration_lock.mutex().lock().await;
        let mut pre_admission_registration = None;

        let runtime_was_registered = adapter.contains_session(session_id).await;
        let staged_session_existed = self.staged_sessions.contains(session_id).await;
        if let Err(primary) = self
            .ensure_runtime_executor_on_adapter(adapter, session_id)
            .await
        {
            return Err(self
                .unregister_new_runtime_registration_after_rpc_error(
                    adapter,
                    session_id,
                    runtime_was_registered,
                    staged_session_existed,
                    true,
                    primary,
                )
                .await
                .into());
        }

        let should_pre_admit = match adapter
            .input_requires_active_pre_admission(session_id, &input)
            .await
        {
            Ok(should_pre_admit) => should_pre_admit,
            Err(error) => {
                return Err(self
                    .unregister_new_runtime_registration_after_native_error(
                        adapter,
                        session_id,
                        runtime_was_registered,
                        staged_session_existed,
                        true,
                        error,
                    )
                    .await);
            }
        };
        let cleanup_protects_active_admission = !should_pre_admit;
        let mut pre_admission = if should_pre_admit {
            match self.reserve_or_join_active_turn(session_id).await {
                Ok(admission) => Some(RuntimePreAdmissionGuard::new(admission)),
                Err(err) => {
                    return Err(self
                        .unregister_new_runtime_registration_after_rpc_error(
                            adapter,
                            session_id,
                            runtime_was_registered,
                            staged_session_existed,
                            cleanup_protects_active_admission,
                            err,
                        )
                        .await
                        .into());
                }
            }
        } else {
            None
        };

        if let Some(admission) = pre_admission.as_mut() {
            let admission_guard =
                match Self::take_runtime_pre_admission_guard(admission, session_id) {
                    Ok(admission) => admission,
                    Err(err) => {
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                cleanup_protects_active_admission,
                                err,
                            )
                            .await
                            .into());
                    }
                };
            pre_admission_registration = Some(
                match self.register_runtime_pre_admission(
                    session_id.clone(),
                    input_id.clone(),
                    admission_guard,
                ) {
                    Ok(registration) => registration,
                    Err(err) => {
                        return Err(self
                            .unregister_new_runtime_registration_after_rpc_error(
                                adapter,
                                session_id,
                                runtime_was_registered,
                                staged_session_existed,
                                cleanup_protects_active_admission,
                                err,
                            )
                            .await
                            .into());
                    }
                },
            );
        }

        let accepted = match adapter
            .accept_input_with_completion(session_id, input)
            .await
        {
            Ok(pair) => pair,
            Err(error) => {
                return Err(self
                    .unregister_new_runtime_registration_after_native_error(
                        adapter,
                        session_id,
                        runtime_was_registered,
                        staged_session_existed,
                        cleanup_protects_active_admission,
                        error,
                    )
                    .await);
            }
        };

        let (outcome, handle) = accepted;
        let accepted_with_completion =
            matches!(outcome, meerkat_runtime::AcceptOutcome::Accepted { .. }) && handle.is_some();
        if matches!(outcome, meerkat_runtime::AcceptOutcome::Accepted { .. })
            && let Some(registration) = pre_admission_registration.take()
        {
            if let Some(handle) = handle {
                self.spawn_runtime_pre_admission_cleanup(
                    session_id.clone(),
                    input_id.clone(),
                    handle,
                );
                registration.disarm();
            } else {
                drop(registration);
            }
        }
        if !accepted_with_completion {
            self.unregister_new_runtime_registration_if_idle(
                adapter,
                session_id,
                runtime_was_registered,
                staged_session_existed,
                cleanup_protects_active_admission,
            )
            .await?;
        }
        drop(runtime_registration_guard);
        drop(runtime_registration_lock);
        Ok(outcome)
    }

    /// Admit a typed correlated terminal peer response through the
    /// runtime-backed path.
    pub async fn accept_peer_response_terminal_via_runtime(
        self: &Arc<Self>,
        session_id: &SessionId,
        peer_id: meerkat_core::comms::PeerId,
        display_name: Option<meerkat_core::comms::PeerName>,
        request_id: meerkat_core::PeerCorrelationId,
        status: meerkat_contracts::PeerResponseTerminalStatusWire,
        result: serde_json::Value,
    ) -> Result<meerkat_runtime::AcceptOutcome, RpcError> {
        let input = meerkat_runtime::peer_response_terminal_input(
            peer_id,
            display_name,
            request_id,
            status,
            result,
        );

        let adapter = Arc::clone(&self.runtime_adapter);
        self.accept_runtime_input_with_active_admission(&adapter, session_id, input)
            .await
    }

    #[allow(clippy::too_many_arguments)]
    pub async fn apply_runtime_turn(
        self: &Arc<Self>,
        session_id: &SessionId,
        run_id: RunId,
        primitive: &RunPrimitive,
        prompt: ContentInput,
        event_tx: mpsc::Sender<EventEnvelope<AgentEvent>>,
        turn_tool_overlay: Option<meerkat_core::service::TurnToolOverlay>,
        overrides: Option<crate::handlers::turn::TurnOverrides>,
    ) -> Result<CoreApplyOutput, RpcError> {
        self.apply_runtime_turn_with_pre_admission(
            session_id,
            run_id,
            primitive,
            prompt,
            event_tx,
            turn_tool_overlay,
            overrides,
            None,
            LlmReconfigureBoundaryOwnership::Acquire,
        )
        .await
    }

    // Skill references travel exclusively on the primitive's
    // `RuntimeTurnMetadata` carrier (K10 fold); the apply seam takes no
    // parallel copy.
    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn apply_runtime_turn_with_pre_admission(
        self: &Arc<Self>,
        session_id: &SessionId,
        run_id: RunId,
        primitive: &RunPrimitive,
        prompt: ContentInput,
        event_tx: mpsc::Sender<EventEnvelope<AgentEvent>>,
        turn_tool_overlay: Option<meerkat_core::service::TurnToolOverlay>,
        overrides: Option<crate::handlers::turn::TurnOverrides>,
        pre_admission: Option<RpcRuntimePreAdmission>,
        llm_reconfigure_boundary: LlmReconfigureBoundaryOwnership,
    ) -> Result<CoreApplyOutput, RpcError> {
        // A session whose task ended with the host's runtime cannot run this
        // turn, and the steps ahead of the service apply (the per-turn LLM
        // hot swap, the live staleness read) would fail on the lost actor and
        // record the run as failed. The session service degrades the
        // session's registration first, so the runtime loop leaves the run to
        // the session's next registration, as the service apply does for a
        // turn the stop cut short.
        if self
            .service
            .runtime_turn_lost_its_host_runtime(session_id, Some(&run_id))
            .await
        {
            return Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "session {session_id} lost its session task to the runtime it ran on; run \
                     {run_id} is left to the session's next registration"
                ),
                data: None,
            });
        }
        // The configured native owner must hand this executor both the admitted
        // work context and the exact-input capacity/seed claim. A missing or
        // unresolved claim must never fall through to ordinary live/cold setup.
        if self.runtime_adapter.has_native_work_authorization_host()
            && (primitive
                .turn_metadata()
                .and_then(|meta| meta.work_authorization.as_ref())
                .is_none()
                || !pre_admission
                    .as_ref()
                    .is_some_and(RpcRuntimePreAdmission::can_apply))
        {
            return Err(runtime_driver_error_to_rpc(
                RuntimeDriverError::ControllerReadinessUnavailable {
                    reason: meerkat_runtime::traits::ControllerReadinessFailure::UnsupportedScope,
                },
            ));
        }
        let pre_admission = match pre_admission {
            Some(admission) => Some(admission.prepare().await?),
            None => None,
        };
        let mut pre_admission = pre_admission.map(RuntimePreAdmissionGuard::new);
        let workgraph_service = self.workgraph_service().ok();
        if let Some(reason) = primitive.peer_response_terminal_apply_intent_violation() {
            return Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: reason.to_string(),
                data: None,
            });
        }

        if self
            .archived_persisted_session_without_live_by_authority(session_id)
            .await?
        {
            return Err(Self::archived_session_teardown_required_rpc(session_id));
        }

        if self
            .archived_persisted_session_without_live_by_authority(session_id)
            .await?
        {
            return Err(Self::archived_session_teardown_required_rpc(session_id));
        }

        let effective_identity = self
            .effective_llm_identity_for_turn(session_id, overrides.as_ref())
            .await?;
        self.validate_prompt_video_input(&prompt, &effective_identity)
            .await?;

        let pending_session = match self.staged_sessions.begin_promotion(session_id).await {
            Ok(slot) => slot,
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                return Err(RpcError {
                    code: error::SESSION_BUSY,
                    message: format!("session {session_id} is already being materialized"),
                    data: None,
                });
            }
            Err(e) => {
                return Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("staged session lifecycle error: {e}"),
                    data: None,
                });
            }
        };

        let persisted_keep_alive = if pending_session.is_none() {
            Some(self.persisted_keep_alive(session_id).await?)
        } else {
            None
        };
        let keep_alive = overrides
            .as_ref()
            .and_then(|ov| ov.keep_alive)
            .or_else(|| {
                pending_session
                    .as_ref()
                    .map(|slot| slot.build_config.keep_alive)
            })
            .or(persisted_keep_alive)
            .ok_or_else(|| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("session {session_id} is missing keep_alive authority"),
                data: None,
            })?;

        if pending_session.is_none()
            && !self
                .live_session_is_stale(session_id, llm_reconfigure_boundary.staleness_position())
                .await?
        {
            let active_turn = match pre_admission.as_mut() {
                Some(admission) => {
                    Self::take_runtime_pre_admission_guard(admission, session_id)?.into_admission()
                }
                None => self.reserve_active_turn(session_id).await?.into_admission(),
            };
            // Hot-swap LLM client if model/provider overrides are present. A
            // resumed run continues under the LLM identity its first dispatch
            // swapped to: that swap saved the session with it before the
            // run's first round commit, and the resumed actor, seeded from
            // the run's provisional tail, carries it. Until the run commits,
            // that actor reads as ahead of the committed boundary, so the
            // swap's live reads and its save cannot run for it.
            let resumed_run = primitive
                .turn_metadata()
                .and_then(|metadata| metadata.execution_kind)
                == Some(meerkat_core::lifecycle::RuntimeExecutionKind::ResumeRun);
            if !resumed_run
                && let Some(ref ov) = overrides
                && (ov.model.is_some()
                    || ov.provider.is_some()
                    || ov.self_hosted_server_id.is_some()
                    || ov.provider_params.is_some()
                    || ov.auth_binding.is_some())
            {
                match llm_reconfigure_boundary {
                    LlmReconfigureBoundaryOwnership::Acquire => {
                        self.hot_swap_llm_client(session_id, ov).await?;
                    }
                    LlmReconfigureBoundaryOwnership::AlreadyHeld => {
                        self.hot_swap_llm_client_under_turn_finalization_boundary(session_id, ov)
                            .await?;
                    }
                }
            }

            let mut req = StartTurnRequest {
                injected_context: Vec::new(),
                prompt: prompt.clone(),
                system_prompt: None,
                event_tx: Some(event_tx.clone()),
                runtime: StartTurnRuntimeSemantics::new(
                    meerkat_core::types::HandlingMode::Queue,
                    turn_tool_overlay.clone(),
                    primitive.turn_metadata().cloned(),
                )
                .with_work_authorization(
                    primitive
                        .turn_metadata()
                        .and_then(|meta| meta.work_authorization.clone()),
                )
                .with_typed_turn_appends(primitive.typed_turn_appends()),
            };
            meerkat::surface::inject_workgraph_attention_turn_overlay(
                self.service.as_ref(),
                workgraph_service.as_ref(),
                session_id,
                &mut req,
            )
            .await
            .map_err(|error| RpcError {
                code: error::INTERNAL_ERROR,
                message: error.to_string(),
                data: None,
            })?;

            let result_rx = self.spawn_service_apply_runtime_turn_with_recoverable_admission_guard(
                session_id.clone(),
                run_id.clone(),
                req,
                match primitive {
                    RunPrimitive::StagedInput(staged) => staged.boundary,
                    _ => RunApplyBoundary::Immediate,
                },
                primitive.contributing_input_ids().to_vec(),
                active_turn,
            );
            let (result, recovered_admission) =
                Self::await_service_apply_runtime_turn_with_recoverable_admission(
                    session_id, result_rx,
                )
                .await?;
            match result {
                Ok(output) => return Ok(output),
                Err(SessionError::NotFound { .. }) => {
                    if let Some(admission) = recovered_admission {
                        pre_admission = Some(RuntimePreAdmissionGuard::new(admission));
                    }
                }
                Err(err) => {
                    drop(recovered_admission);
                    return Err(session_error_to_rpc(err));
                }
            }
        }

        if let Some(slot) = pending_session {
            let staged_capacity_admission = match pre_admission.as_mut() {
                Some(admission) => Some(
                    Self::take_runtime_pre_admission_guard(admission, session_id)?.into_admission(),
                ),
                None => self.take_staged_capacity_admission(session_id),
            };
            let mut promotion_cleanup = PendingPromotionCleanup::new(
                Arc::clone(&self.staged_sessions),
                Arc::clone(&self.staged_capacity_admissions),
                session_id,
                &slot,
                staged_capacity_admission,
            );
            let PromotingSlot {
                build_config,
                labels,
                deferred_prompt,
                deferred_injected_context,
                generated_machine_archived_resume_admission,
                ..
            } = slot;
            let mut build_config = *build_config;
            let mut runtime_prompt: ContentInput = prompt.clone();
            let mut typed_turn_appends = primitive.typed_turn_appends();
            let mut promotion_injected_context = Vec::new();
            if deferred_prompt.is_some() || !deferred_injected_context.is_empty() {
                if let Some(deferred) = deferred_prompt {
                    runtime_prompt = merge_content_inputs(deferred, runtime_prompt);
                }
                // The merged deferred prompt must be the transcript boundary;
                // current-turn primitive appends would otherwise replace it.
                // Direct lowering takes over, so injected context moves onto
                // the StartTurnRequest carrier: the deferred-create entries
                // first, then the promoting turn's own entries (extracted
                // from the appends being cleared) — both still land before
                // the single merged user message.
                promotion_injected_context = deferred_injected_context;
                promotion_injected_context.extend(primitive.injected_context_content_inputs());
                typed_turn_appends.clear();
            }

            if let Some(ref ov) = overrides {
                if ov.provider.is_some() && ov.model.is_none() {
                    promotion_cleanup.restore_now().await;
                    return Err(RpcError {
                        code: error::INVALID_PARAMS,
                        message: "provider override requires model on a session turn".to_string(),
                        data: None,
                    });
                }
                let base_identity = match self.llm_identity_from_pending_build(&build_config).await
                {
                    Ok(identity) => identity,
                    Err(err) => {
                        promotion_cleanup.restore_now().await;
                        return Err(err);
                    }
                };
                let resolved_identity =
                    match self.resolve_target_llm_identity(&base_identity, ov).await {
                        Ok(identity) => identity,
                        Err(err) => {
                            promotion_cleanup.restore_now().await;
                            return Err(err);
                        }
                    };
                if let Err(err) = self
                    .authorize_promoting_llm_identity_override(session_id, &resolved_identity)
                    .await
                {
                    promotion_cleanup.restore_now().await;
                    return Err(err);
                }
                Self::apply_llm_identity_to_build_config(&mut build_config, &resolved_identity);
                if let Some(max_tokens) = ov.max_tokens {
                    build_config.max_tokens = Some(max_tokens);
                }
                if let Some(ref output_schema) = ov.output_schema {
                    match meerkat_core::OutputSchema::from_json_value(output_schema.clone()) {
                        Ok(os) => build_config.output_schema = Some(os),
                        Err(e) => {
                            promotion_cleanup.restore_now().await;
                            return Err(RpcError {
                                code: error::INVALID_PARAMS,
                                message: format!("Invalid output_schema override: {e}"),
                                data: None,
                            });
                        }
                    }
                }
                if let Some(retries) = ov.structured_output_retries {
                    build_config.structured_output_retries = Some(retries);
                }
                if let Some(keep_alive) = ov.keep_alive {
                    if let Err(err) = self
                        .authorize_promoting_keep_alive_override(
                            session_id,
                            keep_alive,
                            build_config.comms_name.is_some(),
                        )
                        .await
                    {
                        promotion_cleanup.restore_now().await;
                        return Err(err);
                    }
                    build_config.keep_alive = keep_alive;
                }
            }

            if overrides.is_some() {
                promotion_cleanup.update_build_config(&build_config);
            }
            if build_config.llm_client_override.is_none()
                && let Some(client) = self.default_llm_client()
            {
                build_config.llm_client_override = Some(client);
                promotion_cleanup.update_build_config(&build_config);
            }
            // A staged slot may survive executor-required teardown and retry.
            // Its serialized build config therefore cannot remain the owner
            // of epoch-local SessionRuntimeBindings: refresh from the current
            // MeerkatMachine registration before selecting the executor and
            // preserve that witness if this attempt is restored again.
            let current_bindings = match self
                .runtime_adapter
                .prepare_bindings(session_id.clone())
                .await
            {
                Ok(bindings) => bindings,
                Err(error) => {
                    promotion_cleanup.restore_now().await;
                    return Err(RpcError {
                        code: error::INTERNAL_ERROR,
                        message: format!(
                            "failed to refresh runtime bindings for staged session {session_id}: {error}"
                        ),
                        data: None,
                    });
                }
            };
            build_config.runtime_build_mode =
                meerkat_core::RuntimeBuildMode::SessionOwned(current_bindings);
            promotion_cleanup.update_build_config(&build_config);
            let runtime_generation = if build_config.config_generation.is_none() {
                if let Some(runtime) = self.config_runtime() {
                    runtime.get().await.ok().map(|snapshot| snapshot.generation)
                } else {
                    None
                }
            } else {
                None
            };

            let mut build = build_config.to_session_build_options();
            build.realm_id = build.realm_id.or_else(|| self.inner.realm_id());
            build.instance_id = build.instance_id.or_else(|| self.inner.instance_id());
            build.backend = build.backend.or_else(|| {
                self.inner
                    .backend()
                    .as_deref()
                    .and_then(meerkat_core::RecoveryBackendKind::parse)
            });
            build.config_generation = build.config_generation.or(runtime_generation);
            let event_tx = self
                .pending_session_event_fanout_tx(session_id, event_tx)
                .await;
            let create_req = CreateSessionRequest {
                injected_context: Vec::new(),
                model: build_config.model.clone(),
                prompt: runtime_prompt.clone(),
                system_prompt: build_config.system_prompt.clone(),
                max_tokens: build_config.max_tokens,
                event_tx: None,
                initial_turn: meerkat_core::service::InitialTurnPolicy::Defer,
                deferred_prompt_policy: DeferredPromptPolicy::Discard,
                build: Some(build),
                labels: labels.clone(),
            };
            let mut start_request = StartTurnRequest {
                // Empty on the runtime-appends path (typed_turn_appends
                // carry the injected context); populated only when the
                // deferred merge cleared the appends and direct lowering
                // owns the turn.
                injected_context: promotion_injected_context,
                prompt: runtime_prompt,
                system_prompt: None,
                event_tx: Some(event_tx),
                runtime: StartTurnRuntimeSemantics::new(
                    meerkat_core::types::HandlingMode::Queue,
                    turn_tool_overlay,
                    primitive.turn_metadata().cloned(),
                )
                .with_work_authorization(
                    primitive
                        .turn_metadata()
                        .and_then(|meta| meta.work_authorization.clone()),
                )
                .with_typed_turn_appends(typed_turn_appends),
            };
            if let Some(workgraph_service) = workgraph_service.as_ref() {
                let empty_labels = BTreeMap::new();
                let attention_labels = labels.as_ref().unwrap_or(&empty_labels);
                if let Err(error) =
                    meerkat::surface::inject_workgraph_attention_turn_overlay_from_labels(
                        workgraph_service,
                        self.service.as_ref(),
                        session_id,
                        attention_labels,
                        &mut start_request,
                    )
                    .await
                {
                    promotion_cleanup.restore_now().await;
                    return Err(RpcError {
                        code: error::INTERNAL_ERROR,
                        message: error.to_string(),
                        data: None,
                    });
                }
            }
            if let Err(error) = self
                .ensure_runtime_executor_with_turn_boundary(session_id, llm_reconfigure_boundary)
                .await
            {
                promotion_cleanup.restore_now().await;
                return Err(error);
            }
            let output_rx = self.spawn_pending_create_and_apply_runtime_turn_with_admission_guard(
                session_id.clone(),
                create_req,
                run_id,
                start_request,
                match primitive {
                    RunPrimitive::StagedInput(staged) => staged.boundary,
                    _ => RunApplyBoundary::Immediate,
                },
                primitive.contributing_input_ids().to_vec(),
                promotion_cleanup,
                build_config.keep_alive,
                generated_machine_archived_resume_admission,
            );
            let output = self
                .await_service_apply_runtime_turn(session_id, output_rx)
                .await;
            self.bridge_pending_session_event_streams(session_id).await;
            return output;
        }

        // A durable run a killed host left open at a committed round is
        // continued without a write, so its provisional tail still stands
        // ahead of the committed boundary and the strict read refuses it.
        // Only that run, which this rebuild resumes, is read through the
        // committed snapshot: the snapshot serves the create request as its
        // locator and metadata, the create seeds its actor from the continued
        // tail, never from the snapshot, and its own recovery refuses a tail
        // that is not continued. Any other tail (held for reconciliation, or
        // refused) keeps the strict read's refusal, so no run starts over it.
        let continues_open_run = matches!(
            meerkat_runtime::recovery::observe_resumable_run(
                self.service.runtime_store().as_ref(),
                session_id,
            )
            .await,
            Ok(Some(_))
        );
        let stored_session = if continues_open_run {
            self.load_persisted_session_tolerating_tail(session_id)
                .await?
        } else {
            self.load_persisted_session(session_id).await?
        }
        .ok_or_else(|| RpcError {
            code: error::SESSION_NOT_FOUND,
            message: format!("session not found: {session_id}"),
            data: None,
        })?;
        // A help session continues only on its live session: refuse the
        // rebuild before the turn is admitted or any tool is composed.
        Self::refuse_help_session_rebuild(&stored_session)?;
        let recovery_overrides =
            self.recovery_overrides_from_turn(overrides.as_ref(), keep_alive)?;
        let active_turn = match pre_admission.as_mut() {
            Some(admission) => {
                Self::take_runtime_pre_admission_guard(admission, session_id)?.into_admission()
            }
            None => self.reserve_active_turn(session_id).await?.into_admission(),
        };
        #[cfg(feature = "mcp")]
        let mcp_attachment_intents = stored_session
            .build_state()
            .map(|state| state.mcp_attachment_intents)
            .unwrap_or_default();
        #[cfg_attr(not(feature = "mcp"), allow(unused_mut))]
        let mut recovered_create = self
            .recovered_create_request(session_id, stored_session, recovery_overrides)
            .await?;
        // A cold resume builds the session's live MCP adapter here, as the
        // materializing paths do, and restores its durable attachment
        // intents onto it.
        #[cfg(feature = "mcp")]
        {
            let (event_tx, _) = mpsc::channel(1);
            let build =
                AgentBuildConfig::from_create_session_request(&recovered_create.request, event_tx);
            let build = match self
                .attach_mcp_adapter_for_pending_session(
                    session_id.clone(),
                    build,
                    mcp_attachment_intents,
                )
                .await
            {
                Ok(build) => build,
                Err(primary) => {
                    return Err(self
                        .combine_with_recovered_runtime_cleanup(
                            session_id,
                            recovered_create.runtime_was_registered,
                            primary,
                            "clean up newly recovered runtime after MCP adapter attachment failure",
                        )
                        .await);
                }
            };
            if let Some(options) = recovered_create.request.build.as_mut() {
                options.external_tools = build.external_tools;
            }
        }
        if let Err(primary) = self
            .ensure_runtime_executor_with_turn_boundary(session_id, llm_reconfigure_boundary)
            .await
        {
            drop(active_turn);
            return Err(self
                .combine_with_recovered_runtime_cleanup(
                    session_id,
                    recovered_create.runtime_was_registered,
                    primary,
                    "clean up newly recovered runtime after executor attachment failure",
                )
                .await);
        }
        let recovered_labels = recovered_create.request.labels.clone();
        let mut start_request = StartTurnRequest {
            injected_context: Vec::new(),
            prompt,
            system_prompt: None,
            event_tx: Some(event_tx),
            runtime: StartTurnRuntimeSemantics::new(
                meerkat_core::types::HandlingMode::Queue,
                turn_tool_overlay,
                primitive.turn_metadata().cloned(),
            )
            .with_work_authorization(
                primitive
                    .turn_metadata()
                    .and_then(|meta| meta.work_authorization.clone()),
            )
            .with_typed_turn_appends(primitive.typed_turn_appends()),
        };
        if let Some(workgraph_service) = workgraph_service.as_ref() {
            let empty_labels = BTreeMap::new();
            let attention_labels = recovered_labels.as_ref().unwrap_or(&empty_labels);
            if let Err(error) =
                meerkat::surface::inject_workgraph_attention_turn_overlay_from_labels(
                    workgraph_service,
                    self.service.as_ref(),
                    session_id,
                    attention_labels,
                    &mut start_request,
                )
                .await
            {
                let primary = RpcError {
                    code: error::INTERNAL_ERROR,
                    message: error.to_string(),
                    data: None,
                };
                return Err(if recovered_create.runtime_was_registered {
                    primary
                } else {
                    staged_apply_runtime_turn_error_to_rpc(
                        meerkat::session_runtime::staged_promotion::StagedApplyRuntimeTurnError::unavailable_teardown(
                            primary.message,
                        ),
                    )
                });
            }
        }
        let output_rx = self.spawn_recovered_create_and_apply_runtime_turn_with_admission_guard(
            session_id.clone(),
            recovered_create.request,
            recovered_create.runtime_was_registered,
            run_id,
            start_request,
            match primitive {
                RunPrimitive::StagedInput(staged) => staged.boundary,
                _ => RunApplyBoundary::Immediate,
            },
            primitive.contributing_input_ids().to_vec(),
            active_turn,
            keep_alive,
        );
        let output = self
            .await_service_apply_runtime_turn(session_id, output_rx)
            .await?;
        Ok(output)
    }

    pub fn skill_identity_registry(&self) -> SourceIdentityRegistry {
        self.skill_identity_registry
            .read()
            .map(|state| state.registry.clone())
            .unwrap_or_default()
    }

    /// Build a source identity registry from runtime config.
    ///
    /// W3-A: thin RPC delegate to
    /// [`meerkat::session_runtime::runtime_state::build_skill_identity_registry`].
    pub fn build_skill_identity_registry(
        config: &Config,
        context_root: Option<&std::path::Path>,
        user_root: Option<&std::path::Path>,
    ) -> Result<SourceIdentityRegistry, SkillError> {
        meerkat::session_runtime::runtime_state::build_skill_identity_registry(
            config,
            context_root,
            user_root,
        )
    }

    /// Create a new session with the given build configuration.
    ///
    /// Returns the session ID on success. The session is staged as "pending"
    /// and will be materialized inside the service on the first `start_turn`.
    pub async fn create_session(
        self: &Arc<Self>,
        build_config: AgentBuildConfig,
        labels: Option<BTreeMap<String, String>>,
        deferred_prompt: Option<ContentInput>,
        deferred_injected_context: Vec<ContentInput>,
    ) -> Result<SessionId, RpcError> {
        self.create_session_from_seed(
            Session::new(),
            build_config,
            labels,
            deferred_prompt,
            deferred_injected_context,
            true,
        )
        .await
    }

    /// [`Self::create_session`] for a session whose tools are exactly its
    /// build's external tools, such as a help session: it gets no live MCP
    /// adapter, so no MCP server or catalog control tool joins them.
    pub(crate) async fn create_session_without_live_mcp(
        self: &Arc<Self>,
        build_config: AgentBuildConfig,
        labels: Option<BTreeMap<String, String>>,
        deferred_prompt: Option<ContentInput>,
        deferred_injected_context: Vec<ContentInput>,
    ) -> Result<SessionId, RpcError> {
        self.create_session_from_seed(
            Session::new(),
            build_config,
            labels,
            deferred_prompt,
            deferred_injected_context,
            false,
        )
        .await
    }

    /// Materialize an idle session without running a provider turn.
    ///
    /// Unlike [`Self::create_session`]'s in-memory pre-turn staging, this
    /// commits the session through the persistent service before returning.
    /// `resume_id` loads the existing session through this runtime's authority;
    /// callers cannot supply an unrelated snapshot or mint an existing identity.
    /// This is intended for hosts that must publish comms/trust readiness and
    /// survive restart before the first prompt arrives.
    ///
    /// On resume, durable configuration is inherited through the canonical
    /// recovery owner; `build_config` supplies only process-local resources.
    /// Build-policy changes must be explicit in `resume_overrides`. Failure or
    /// cancellation rolls back this operation's exact materialization claim,
    /// without archiving or replacing a durable predecessor.
    pub async fn create_or_resume_session_without_turn(
        self: &Arc<Self>,
        build_config: AgentBuildConfig,
        resume_id: Option<SessionId>,
        labels: Option<BTreeMap<String, String>>,
        resume_overrides: SurfaceSessionRecoveryOverrides,
    ) -> Result<SessionId, RpcError> {
        self.create_or_resume_session_without_turn_bound(
            build_config,
            resume_id,
            labels,
            resume_overrides,
            None,
            None,
        )
        .await
    }

    /// [`Self::create_or_resume_session_without_turn`] with a trusted host's
    /// binding of the actual new registration, run after the exact
    /// materialization claim prepared it and before the session's agent is
    /// constructed or anything is restored. A binding failure rolls back this
    /// operation's claim like any other failure. `cancelled`, when given,
    /// resolves once the caller's request is cancelled: the binding or the
    /// construction in progress is abandoned and compensated as for a caller
    /// that stopped waiting (the claim rolled back, the session's MCP state
    /// entry removed), and the result is a cancellation.
    pub(crate) async fn create_or_resume_session_without_turn_bound(
        self: &Arc<Self>,
        build_config: AgentBuildConfig,
        resume_id: Option<SessionId>,
        labels: Option<BTreeMap<String, String>>,
        resume_overrides: SurfaceSessionRecoveryOverrides,
        before_construction: Option<BeforeConstruction>,
        cancelled: Option<tokio::sync::watch::Receiver<bool>>,
    ) -> Result<SessionId, RpcError> {
        let runtime = Arc::clone(self);
        let (mut result_tx, result_rx) = tokio::sync::oneshot::channel();
        // Keep the registration fence until exact compensation has finished,
        // including when the caller drops its response future.
        tokio::spawn(async move {
            let seed = Session::new();
            let id = resume_id.clone().unwrap_or_else(|| seed.id().clone());
            let registration_lock = runtime.runtime_registration_lock(&id);
            let Ok(_registration_guard) = registration_lock.mutex().try_lock() else {
                let _ = result_tx.send(Err(session_error_to_rpc(SessionError::Busy { id })));
                return;
            };
            let result = async {
                if result_tx.is_closed() {
                    return Err(session_error_to_rpc(SessionError::Busy { id: id.clone() }));
                }
                if runtime.staged_sessions.contains(&id).await
                    || runtime
                        .runtime_adapter
                        .runtime_state(&id)
                        .await
                        .is_ok_and(|state| matches!(state, RuntimeState::Running))
                    || runtime
                        .runtime_adapter
                        .current_executor_attachment_witness(&id)
                        .await
                        .is_some()
                    || runtime
                        .service
                        .has_live_session(&id)
                        .await
                        .map_err(session_error_to_rpc)?
                {
                    return Err(session_error_to_rpc(SessionError::Busy { id: id.clone() }));
                }
                #[cfg(feature = "mcp")]
                if runtime.mcp_sessions.read().await.contains_key(&id) {
                    return Err(session_error_to_rpc(SessionError::Busy { id: id.clone() }));
                }
                // A session materialized here is a registration on this
                // runtime: refused once its shutdown began, and otherwise
                // admitted through the registration gate, held until the
                // materialization claim below is in place.
                let registration_admission = runtime.admit_runtime_registration(&id).await?;
                let session = if resume_id.is_some() {
                    runtime.prepare_cold_attach(&id).await?;
                    runtime
                        .reject_archived_persisted_session_without_live(&id)
                        .await?;
                    runtime
                        .load_persisted_session(&id)
                        .await?
                        .ok_or_else(|| Self::session_not_found_rpc(&id))?
                } else {
                    seed
                };
                let admission = runtime
                    .service
                    .reserve_create_session_admission()
                    .await
                    .map_err(session_error_to_rpc)?;
                let mut prepared = runtime
                    .runtime_adapter
                    .prepare_session_materialization(id.clone())
                    .await
                    .map_err(|error| RpcError {
                        code: error::INTERNAL_ERROR,
                        message: error.to_string(),
                        data: None,
                    })?;
                drop(registration_admission);
                // A cancelled request abandons the step in progress; the
                // claim is rolled back below like any other failure.
                let mut cancelled = cancelled;
                let request_cancelled =
                    async |cancelled: &mut Option<tokio::sync::watch::Receiver<bool>>| {
                        match cancelled.as_mut() {
                            Some(receiver) => {
                                if receiver.wait_for(|cancelled| *cancelled).await.is_err() {
                                    std::future::pending::<()>().await;
                                }
                            }
                            None => std::future::pending::<()>().await,
                        }
                    };
                let cancellation = || RpcError {
                    code: error::REQUEST_CANCELLED,
                    message: "request cancelled during session recovery".into(),
                    data: None,
                };
                // The host binds the actual new registration first: its
                // agent and anything restored decide under that binding.
                let bound = match before_construction {
                    Some(bind) => {
                        tokio::select! {
                            biased;
                            () = result_tx.closed() => None,
                            () = request_cancelled(&mut cancelled) => Some(Err(cancellation())),
                            result = bind(runtime.runtime_adapter(), id.clone()) => Some(result),
                        }
                    }
                    None => Some(Ok(())),
                };
                let materialized = match bound {
                    Some(Ok(())) => tokio::select! {
                        biased;
                        () = result_tx.closed() => None,
                        () = request_cancelled(&mut cancelled) => Some(Err(cancellation())),
                        result = runtime.materialize_without_turn(
                            session, build_config, labels, resume_id.is_some(),
                            resume_overrides, &mut prepared, admission,
                        ) => Some(result),
                    },
                    Some(Err(error)) => Some(Err(error)),
                    None => None,
                };
                match materialized {
                    Some(Ok(actor_slot)) => {
                        runtime
                            .runtime_actor_witness_slots
                            .write()
                            .unwrap_or_else(std::sync::PoisonError::into_inner)
                            .insert(id.clone(), actor_slot);
                        Ok(id.clone())
                    }
                    error => {
                        // Nothing was admitted (a no-turn materialization),
                        // so the rollback keeps every input the registration
                        // recovered (rollback_now): a refused resume ends
                        // nothing a later start would run.
                        let rollback = prepared.rollback_now().await;
                        #[cfg(feature = "mcp")]
                        runtime.mcp_sessions.write().await.remove(&id);
                        let primary = error.and_then(Result::err).unwrap_or_else(|| RpcError {
                            code: error::INTERNAL_ERROR,
                            message: "session materialization cancelled".into(),
                            data: None,
                        });
                        Err(match rollback {
                            Ok(_) => primary,
                            Err(cleanup) => {
                                tracing::warn!(
                                    session_id = %id,
                                    error = %cleanup,
                                    "no-turn materialization rollback failed"
                                );
                                combine_rpc_cleanup_error(
                                    primary,
                                    cleanup,
                                    "roll back exact no-turn materialization",
                                )
                            }
                        })
                    }
                }
            }
            .await;
            let _ = result_tx.send(result);
        });
        result_rx.await.map_err(|error| RpcError {
            code: error::INTERNAL_ERROR,
            message: format!("session materialization task ended without a result: {error}"),
            data: None,
        })?
    }

    #[allow(clippy::too_many_arguments)]
    async fn materialize_without_turn(
        self: &Arc<Self>,
        session: Session,
        mut resources: AgentBuildConfig,
        labels: Option<BTreeMap<String, String>>,
        recovering: bool,
        overrides: SurfaceSessionRecoveryOverrides,
        prepared: &mut meerkat_runtime::PreparedSessionMaterialization,
        admission: ActiveCapacityGuard,
    ) -> Result<meerkat::LiveSessionActorWitnessSlot, RpcError> {
        self.arm_schedule_host_for_agent_tools().await;
        let mut request = if recovering {
            Self::refuse_help_session_rebuild(&session)?;
            let snapshot = self.realm_context_snapshot();
            let mut request = self
                .recovery_context(&snapshot, Some(session.id()))
                .recovered_create_request_with_bindings(
                    session.clone(),
                    overrides,
                    prepared.bindings_clone(),
                )
                .await
                .map_err(Self::recovery_error_to_rpc)?;
            if let Some(build) = request.build.as_mut() {
                meerkat::session_runtime::recovery::inject_recovery_resources(build, &resources);
            }
            request
        } else {
            resources.llm_client_override = resources
                .llm_client_override
                .or_else(|| self.default_llm_client());
            resources.resume_session = Some(session.clone());
            resources.runtime_build_mode =
                meerkat_core::RuntimeBuildMode::SessionOwned(prepared.bindings_clone());
            let snapshot = self.realm_context_snapshot();
            resources.realm_id = resources.realm_id.or(snapshot.realm_id);
            resources.instance_id = resources.instance_id.or(snapshot.instance_id);
            resources.backend = resources.backend.or_else(|| {
                snapshot
                    .backend
                    .as_deref()
                    .and_then(meerkat_core::RecoveryBackendKind::parse)
            });
            if resources.config_generation.is_none()
                && let Some(config_runtime) = self.config_runtime()
            {
                resources.config_generation = config_runtime
                    .get()
                    .await
                    .ok()
                    .map(|snapshot| snapshot.generation);
            }
            CreateSessionRequest {
                model: resources.model.clone(),
                prompt: ContentInput::Text(String::new()),
                injected_context: Vec::new(),
                system_prompt: resources.system_prompt.clone(),
                max_tokens: resources.max_tokens,
                event_tx: None,
                initial_turn: InitialTurnPolicy::Defer,
                deferred_prompt_policy: DeferredPromptPolicy::Discard,
                build: Some(resources.to_session_build_options()),
                labels: None,
            }
        };
        request.labels = labels;
        #[cfg(feature = "mcp")]
        {
            let (event_tx, _) = mpsc::channel(1);
            let build = AgentBuildConfig::from_create_session_request(&request, event_tx);
            let intents = session
                .build_state()
                .map(|state| state.mcp_attachment_intents)
                .unwrap_or_default();
            let build = self
                .attach_mcp_adapter_for_pending_session(session.id().clone(), build, intents)
                .await?;
            if let Some(options) = request.build.as_mut() {
                options.external_tools = build.external_tools;
            }
        }
        #[cfg(test)]
        Self::wait_pending_promotion_pre_turn_hook(&self.runtime_routed_pre_promotion_hook).await;
        meerkat::surface::materialize_prepared_session_actor_unattached_with_actor_slot(
            &self.service,
            &self.runtime_adapter,
            prepared,
            session,
            request,
            admission,
        )
        .await
        .map(|(_, slot)| slot)
        .map_err(|error| match error {
            meerkat::surface::SurfaceRuntimeMaterializeError::Session(error) => {
                session_error_to_rpc(error)
            }
            error => RpcError {
                code: error::INTERNAL_ERROR,
                message: error.to_string(),
                data: None,
            },
        })
    }

    /// Create a deferred session from a caller-owned exact session identity.
    ///
    /// This is deliberately private to runtime-owned durable workflows such as
    /// schedule materialization. Public RPC creation continues to mint its own
    /// identity through [`Self::create_session`].
    async fn create_session_from_seed(
        self: &Arc<Self>,
        mut session: Session,
        mut build_config: AgentBuildConfig,
        labels: Option<BTreeMap<String, String>>,
        deferred_prompt: Option<ContentInput>,
        deferred_injected_context: Vec<ContentInput>,
        attach_live_mcp: bool,
    ) -> Result<SessionId, RpcError> {
        #[cfg(not(feature = "mcp"))]
        let _ = attach_live_mcp;
        // A session can author schedules on its first turn; the firing host
        // for this runtime's store must be live in the same process.
        self.arm_schedule_host_for_agent_tools().await;
        let effective_llm_identity = self.llm_identity_from_pending_build(&build_config).await?;
        build_config.self_hosted_server_id = effective_llm_identity.self_hosted_server_id.clone();
        if let Some(prompt) = deferred_prompt.as_ref() {
            self.validate_prompt_video_input(prompt, &effective_llm_identity)
                .await?;
        }
        // Injected context is a first-turn submit-work fact: it persists in
        // the staged slot only alongside a deferred first-turn prompt.
        if deferred_prompt.is_none() && !deferred_injected_context.is_empty() {
            return Err(RpcError {
                code: error::INVALID_PARAMS,
                message: "injected_context on a deferred create requires a deferred prompt"
                    .to_string(),
                data: None,
            });
        }

        // The staged document is a machine-created generation-zero session,
        // not a persisted resume. Record that typed fact before the staged
        // slot can accept ordered System appends: those appends make the
        // document non-empty before AgentFactory has minted SessionMetadata,
        // but must not turn it into a legacy metadata-less resume.
        if session.messages().is_empty()
            && session
                .try_session_metadata()
                .map_err(|error| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "failed to inspect precreated session metadata for {}: {error}",
                        session.id()
                    ),
                    data: None,
                })?
                .is_none()
            && session
                .try_deferred_turn_state()
                .map_err(|error| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "failed to inspect precreated deferred-turn state for {}: {error}",
                        session.id()
                    ),
                    data: None,
                })?
                .is_none()
        {
            let mut deferred_turn_state = meerkat_core::SessionDeferredTurnState::default();
            deferred_turn_state.mark_initial_turn_pending();
            session
                .set_deferred_turn_state(deferred_turn_state)
                .map_err(|error| RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!(
                        "failed to mark precreated session {} as deferred: {error}",
                        session.id()
                    ),
                    data: None,
                })?;
        }

        let session_id = session.id().clone();
        let admission = self
            .service
            .reserve_create_session_admission()
            .await
            .map_err(session_error_to_rpc)?;

        // Inject the pre-created session so the agent builder will reuse this ID.
        let registration_admission = self.admit_runtime_registration(&session_id).await?;
        let bindings = self
            .runtime_adapter
            .prepare_bindings(session_id.clone())
            .await
            .map_err(|e| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "failed to prepare runtime bindings for session {session_id}: {e}"
                ),
                data: None,
            })?;
        drop(registration_admission);

        // The seed is a machine-created generation-zero session (see above):
        // the build mints it under its pre-assigned id.
        let build_config = AgentBuildConfig {
            resume_session: Some(session),
            resume_session_intent: meerkat_core::SessionBuildIntent::Mint,
            runtime_build_mode: meerkat_core::RuntimeBuildMode::SessionOwned(bindings),
            ..build_config
        };

        #[cfg(test)]
        let create_session_after_prepare_bindings_error = {
            self.create_session_after_prepare_bindings_error
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .take()
        };
        #[cfg(test)]
        if let Some(message) = create_session_after_prepare_bindings_error {
            *self
                .create_session_after_prepare_bindings_session_id
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(session_id.clone());
            return Err(self
                .combine_with_recovered_runtime_cleanup(
                    &session_id,
                    false,
                    RpcError {
                        code: error::INTERNAL_ERROR,
                        message,
                        data: None,
                    },
                    "clean up prepared runtime after create failure",
                )
                .await);
        }

        #[cfg(feature = "mcp")]
        let build_config = if attach_live_mcp {
            match self
                .attach_mcp_adapter_for_pending_session(
                    session_id.clone(),
                    build_config,
                    Vec::new(),
                )
                .await
            {
                Ok(build_config) => build_config,
                Err(err) => {
                    return Err(self
                        .combine_with_recovered_runtime_cleanup(
                            &session_id,
                            false,
                            err,
                            "clean up prepared runtime after MCP attachment failure",
                        )
                        .await);
                }
            }
        } else {
            build_config
        };

        let now = now_unix_secs();
        if let Err(err) = self
            .staged_sessions
            .stage(
                session_id.clone(),
                StagedSlot::new_staged(
                    &session_id,
                    build_config,
                    effective_llm_identity,
                    labels,
                    deferred_prompt,
                    deferred_injected_context,
                    now,
                    now,
                    false,
                )
                .map_err(|err| match err {
                    meerkat::StagedLifecycleError::KeepAliveRequiresCommsName => RpcError {
                        code: error::INVALID_PARAMS,
                        message: "keep_alive requires a session created with comms_name"
                            .to_string(),
                        data: None,
                    },
                    err => RpcError {
                        code: error::INTERNAL_ERROR,
                        message: format!(
                            "generated authority rejected staged session {session_id}: {err}"
                        ),
                        data: None,
                    },
                })?,
            )
            .await
        {
            return Err(self
                .combine_with_recovered_runtime_cleanup(
                    &session_id,
                    false,
                    RpcError {
                        code: error::INTERNAL_ERROR,
                        message: format!("failed to stage session {session_id}: {err}"),
                        data: None,
                    },
                    "clean up prepared runtime after staged-session insertion failure",
                )
                .await);
        }
        if let Err(err) = self.insert_staged_capacity_admission(session_id.clone(), admission) {
            let _ = self.staged_sessions.abandon(&session_id).await;
            return Err(self
                .combine_with_recovered_runtime_cleanup(
                    &session_id,
                    false,
                    err,
                    "clean up prepared runtime after capacity-admission insertion failure",
                )
                .await);
        }

        Ok(session_id)
    }

    /// Start a turn on the given session.
    ///
    /// Events are forwarded to `event_tx` during the turn. Returns the
    /// `RunResult` when the turn completes.
    ///
    /// `overrides` may contain per-turn overrides. For pending (deferred)
    /// sessions, all overrides are applied to the staged `AgentBuildConfig`.
    /// For materialized sessions, build-only fields are rejected; turn-scoped
    /// identity and policy overrides are applied through runtime metadata.
    #[allow(clippy::too_many_arguments)]
    #[cfg(test)]
    pub async fn start_turn(
        &self,
        session_id: &SessionId,
        prompt: ContentInput,
        event_tx: mpsc::Sender<EventEnvelope<AgentEvent>>,
        skill_references: Option<Vec<meerkat_core::skills::SkillKey>>,
        turn_tool_overlay: Option<meerkat_core::service::TurnToolOverlay>,
        additional_instructions: Option<Vec<String>>,
        overrides: Option<crate::handlers::turn::TurnOverrides>,
    ) -> Result<RunResult, RpcError> {
        #[allow(unused_mut)]
        let mut turn_prompt = prompt;
        let workgraph_service = self.workgraph_service().ok();

        // Check if this is a pending (not-yet-materialized) session.
        let pending_session = match self.staged_sessions.begin_promotion(session_id).await {
            Ok(slot) => slot,
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                return Err(RpcError {
                    code: error::SESSION_BUSY,
                    message: format!("session {session_id} is already being materialized"),
                    data: None,
                });
            }
            Err(e) => {
                return Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("staged session lifecycle error: {e}"),
                    data: None,
                });
            }
        };

        if let Some(slot) = pending_session {
            let staged_capacity_admission = self.take_staged_capacity_admission(session_id);
            let mut promotion_cleanup = PendingPromotionCleanup::new(
                Arc::clone(&self.staged_sessions),
                Arc::clone(&self.staged_capacity_admissions),
                session_id,
                &slot,
                staged_capacity_admission,
            );
            let PromotingSlot {
                build_config,
                labels,
                deferred_prompt,
                generated_machine_archived_resume_admission,
                ..
            } = slot;
            let mut build_config = *build_config;
            #[cfg(feature = "mcp")]
            if let Err(err) = self
                .apply_mcp_boundary_to_turn_prompt(session_id, &event_tx, &mut turn_prompt)
                .await
            {
                promotion_cleanup.restore_now().await;
                return Err(err);
            }
            // Prepend the deferred create-time prompt to the turn prompt.
            // Keep copies for rollback paths that re-stage the pending session.
            if let Some(deferred) = deferred_prompt {
                turn_prompt = merge_content_inputs(deferred, turn_prompt);
            }
            // Apply per-turn overrides to the pending build config.
            if let Some(ref ov) = overrides {
                if ov.provider.is_some() && ov.model.is_none() {
                    promotion_cleanup.restore_now().await;
                    return Err(RpcError {
                        code: error::INVALID_PARAMS,
                        message: "provider override requires model on a session turn".to_string(),
                        data: None,
                    });
                }
                let base_identity = match self.llm_identity_from_pending_build(&build_config).await
                {
                    Ok(identity) => identity,
                    Err(err) => {
                        promotion_cleanup.restore_now().await;
                        return Err(err);
                    }
                };
                let resolved_identity =
                    match self.resolve_target_llm_identity(&base_identity, ov).await {
                        Ok(identity) => identity,
                        Err(err) => {
                            promotion_cleanup.restore_now().await;
                            return Err(err);
                        }
                    };
                if let Err(err) = self
                    .authorize_promoting_llm_identity_override(session_id, &resolved_identity)
                    .await
                {
                    promotion_cleanup.restore_now().await;
                    return Err(err);
                }
                Self::apply_llm_identity_to_build_config(&mut build_config, &resolved_identity);
                if let Some(max_tokens) = ov.max_tokens {
                    build_config.max_tokens = Some(max_tokens);
                }
                if let Some(ref output_schema) = ov.output_schema {
                    match meerkat_core::OutputSchema::from_json_value(output_schema.clone()) {
                        Ok(os) => build_config.output_schema = Some(os),
                        Err(e) => {
                            // Restore pending state before returning error.
                            promotion_cleanup.restore_now().await;
                            return Err(RpcError {
                                code: error::INVALID_PARAMS,
                                message: format!("Invalid output_schema override: {e}"),
                                data: None,
                            });
                        }
                    }
                }
                if let Some(retries) = ov.structured_output_retries {
                    build_config.structured_output_retries = Some(retries);
                }
                if let Some(keep_alive) = ov.keep_alive {
                    if let Err(err) = self
                        .authorize_promoting_keep_alive_override(
                            session_id,
                            keep_alive,
                            build_config.comms_name.is_some(),
                        )
                        .await
                    {
                        promotion_cleanup.restore_now().await;
                        return Err(err);
                    }
                    build_config.keep_alive = keep_alive;
                }
            }
            if overrides.is_some() {
                promotion_cleanup.update_build_config(&build_config);
            }
            // Inject default LLM client if the caller didn't provide one.
            if build_config.llm_client_override.is_none()
                && let Some(client) = self.default_llm_client()
            {
                build_config.llm_client_override = Some(client);
                promotion_cleanup.update_build_config(&build_config);
            }
            let runtime_generation = if build_config.config_generation.is_none() {
                if let Some(runtime) = self.config_runtime() {
                    runtime.get().await.ok().map(|snapshot| snapshot.generation)
                } else {
                    None
                }
            } else {
                None
            };

            let mut build = build_config.to_session_build_options();
            build.realm_id = build.realm_id.or_else(|| self.inner.realm_id());
            build.instance_id = build.instance_id.or_else(|| self.inner.instance_id());
            build.backend = build.backend.or_else(|| {
                self.inner
                    .backend()
                    .as_deref()
                    .and_then(meerkat_core::RecoveryBackendKind::parse)
            });
            build.config_generation = build.config_generation.or(runtime_generation);
            // #61/#67: resolve the initial-turn provider hint through
            // registered model ownership (the same fail-closed contract REST
            // uses at `resolve_validation_identity`), not a from-the-model
            // string inference. An explicit provider is validated against the
            // catalog owner; otherwise the registered owner supplies it; when
            // neither is present the create fails closed rather than guessing
            // a provider the registry never blessed.
            let initial_turn_provider = match self.resolve_create_provider(&build_config).await {
                Ok(provider) => provider,
                Err(err) => {
                    promotion_cleanup.restore_now().await;
                    return Err(err);
                }
            };
            let initial_turn_provider_hint = Some(initial_turn_provider.as_str());
            build.initial_turn_metadata =
                Some(Self::runtime_stamped_prompt_turn_metadata_from_overrides(
                    skill_references.clone(),
                    turn_tool_overlay.clone(),
                    additional_instructions.clone(),
                    overrides.as_ref(),
                    initial_turn_provider_hint,
                ));
            let turn_metadata = build.initial_turn_metadata.clone();
            let event_tx = self
                .pending_session_event_fanout_tx(session_id, event_tx)
                .await;

            let create_req = CreateSessionRequest {
                injected_context: Vec::new(),
                model: build_config.model.clone(),
                prompt: ContentInput::Text(String::new()),
                system_prompt: build_config.system_prompt.clone(),
                max_tokens: build_config.max_tokens,
                event_tx: None,
                initial_turn: meerkat_core::service::InitialTurnPolicy::Defer,
                deferred_prompt_policy: DeferredPromptPolicy::Discard,
                build: Some(build),
                labels: labels.clone(),
            };

            let mut start_request = StartTurnRequest {
                injected_context: Vec::new(),
                prompt: turn_prompt,
                system_prompt: None,
                event_tx: Some(event_tx),
                runtime: StartTurnRuntimeSemantics::new(
                    meerkat_core::types::HandlingMode::Queue,
                    turn_tool_overlay,
                    turn_metadata,
                ),
            };
            if let Some(workgraph_service) = workgraph_service.as_ref() {
                let empty_labels = BTreeMap::new();
                let attention_labels = labels.as_ref().unwrap_or(&empty_labels);
                if let Err(error) =
                    meerkat::surface::inject_workgraph_attention_turn_overlay_from_labels(
                        workgraph_service,
                        self.service.as_ref(),
                        session_id,
                        attention_labels,
                        &mut start_request,
                    )
                    .await
                {
                    promotion_cleanup.restore_now().await;
                    return Err(RpcError {
                        code: error::INTERNAL_ERROR,
                        message: error.to_string(),
                        data: None,
                    });
                }
            }
            let result_rx = self.spawn_pending_create_and_start_turn_with_admission_guard(
                session_id.clone(),
                create_req,
                start_request,
                promotion_cleanup,
                generated_machine_archived_resume_admission,
            );
            let result = Self::await_service_start_turn(session_id, result_rx).await;
            self.bridge_pending_session_event_streams(session_id).await;
            return result;
        }

        // Normal turn on an existing (materialized) session. Reject only
        // build-time overrides; System messages are valid on every turn.
        if let Some(ref ov) = overrides {
            let rejected = [
                ov.max_tokens.map(|_| "max_tokens"),
                ov.output_schema.as_ref().map(|_| "output_schema"),
                ov.structured_output_retries
                    .map(|_| "structured_output_retries"),
            ];
            let rejected: Vec<&str> = rejected.into_iter().flatten().collect();
            if !rejected.is_empty() {
                return Err(RpcError {
                    code: error::INVALID_PARAMS,
                    message: format!(
                        "Cannot override {} on a materialized session; use deferred session/create",
                        rejected.join(", ")
                    ),
                    data: None,
                });
            }
        }

        let effective_identity = self
            .effective_llm_identity_for_turn(session_id, overrides.as_ref())
            .await?;
        self.validate_prompt_video_input(&turn_prompt, &effective_identity)
            .await?;

        let keep_alive = match overrides.as_ref().and_then(|ov| ov.keep_alive) {
            Some(keep_alive) => keep_alive,
            None => self.persisted_keep_alive(session_id).await?,
        };
        let turn_metadata = Some(Self::runtime_stamped_prompt_turn_metadata_from_overrides(
            skill_references.clone(),
            turn_tool_overlay.clone(),
            additional_instructions.clone(),
            overrides.as_ref(),
            Some(effective_identity.provider.as_str()),
        ));

        if self
            .live_session_is_stale(session_id, LiveStalenessPosition::OutsideTurnBoundary)
            .await?
        {
            return Box::pin(self.try_recover_persisted_session(
                session_id,
                turn_prompt,
                event_tx,
                keep_alive,
                skill_references,
                turn_tool_overlay,
                additional_instructions,
                overrides.as_ref(),
            ))
            .await;
        }

        let active_turn = self.reserve_active_turn(session_id).await?;

        if overrides.as_ref().and_then(|ov| ov.keep_alive).is_some() {
            #[cfg(feature = "comms")]
            let comms_rt = self.service.comms_runtime(session_id).await;
            #[cfg(feature = "comms")]
            if keep_alive && comms_rt.is_none() {
                return Err(RpcError {
                    code: error::INVALID_PARAMS,
                    message: "keep_alive requires a session created with comms_name".to_string(),
                    data: None,
                });
            }
            // The session keep_alive fact itself is committed from
            // RuntimeTurnMetadata after generated turn-admission feedback.
            // W2-G: never reconfigure a mob-owned drain from the
            // keep_alive-override path. See `start_turn_via_runtime`.
            #[cfg(feature = "comms")]
            {
                let owner = self.runtime_adapter.peer_ingress_owner(session_id).await;
                if !owner.is_mob_owned() {
                    self.runtime_adapter
                        .update_peer_ingress_context(session_id, keep_alive, comms_rt)
                        .await
                        .map_err(runtime_driver_error_to_rpc)?;
                }
            }
        }

        // Hot-swap LLM client if model/provider/provider_params changed.
        if let Some(ref ov) = overrides
            && (ov.model.is_some()
                || ov.provider.is_some()
                || ov.self_hosted_server_id.is_some()
                || ov.provider_params.is_some()
                || ov.auth_binding.is_some())
        {
            self.hot_swap_llm_client(session_id, ov).await?;
        }

        #[cfg(feature = "mcp")]
        self.apply_mcp_boundary_to_turn_prompt(session_id, &event_tx, &mut turn_prompt)
            .await?;

        let mut req = StartTurnRequest {
            injected_context: Vec::new(),
            prompt: turn_prompt.clone(),
            system_prompt: None,
            event_tx: Some(event_tx.clone()),
            runtime: StartTurnRuntimeSemantics::new(
                meerkat_core::types::HandlingMode::Queue,
                turn_tool_overlay.clone(),
                turn_metadata,
            ),
        };
        meerkat::surface::inject_workgraph_attention_turn_overlay(
            self.service.as_ref(),
            workgraph_service.as_ref(),
            session_id,
            &mut req,
        )
        .await
        .map_err(|error| RpcError {
            code: error::INTERNAL_ERROR,
            message: error.to_string(),
            data: None,
        })?;

        let result_rx = self.spawn_service_start_turn_with_admission_guard(
            session_id.clone(),
            req,
            active_turn.into_admission(),
        );
        let result = Self::await_service_start_turn(session_id, result_rx).await;
        match result {
            Ok(result) => Ok(result),
            Err(err) if err.code == error::SESSION_NOT_FOUND => {
                // Attempt persisted session recovery: the session may exist in the
                // store from a previous runtime lifetime.
                Box::pin(self.try_recover_persisted_session(
                    session_id,
                    turn_prompt,
                    event_tx,
                    keep_alive,
                    skill_references,
                    turn_tool_overlay,
                    additional_instructions,
                    overrides.as_ref(),
                ))
                .await
            }
            Err(err) => Err(err),
        }
    }

    /// Attempt to recover a persisted session that is no longer live.
    ///
    /// Mirrors the REST recovery path: load the session from the store, extract
    /// stored metadata, build an `AgentBuildConfig`, stage as pending, and
    /// fall through to the normal materialization path.
    ///
    /// Returns `SESSION_NOT_FOUND` if the session cannot be recovered.
    #[allow(clippy::too_many_arguments)]
    #[cfg(test)]
    async fn try_recover_persisted_session(
        &self,
        session_id: &SessionId,
        prompt: ContentInput,
        event_tx: mpsc::Sender<EventEnvelope<AgentEvent>>,
        keep_alive: bool,
        skill_references: Option<Vec<meerkat_core::skills::SkillKey>>,
        turn_tool_overlay: Option<meerkat_core::service::TurnToolOverlay>,
        additional_instructions: Option<Vec<String>>,
        overrides: Option<&crate::handlers::turn::TurnOverrides>,
    ) -> Result<RunResult, RpcError> {
        let turn_system_prompt = overrides.and_then(|overrides| overrides.system_prompt.clone());
        let loaded_session = self.load_persisted_session(session_id).await?;

        let Some(session) = loaded_session else {
            return Err(RpcError {
                code: error::SESSION_NOT_FOUND,
                message: format!("Session not found: {session_id}"),
                data: None,
            });
        };
        let recovery_overrides = self.recovery_overrides_from_turn(overrides, keep_alive)?;
        let admission = self.reserve_active_turn(session_id).await?;
        if self
            .archived_persisted_session_without_live(session_id)
            .await?
        {
            return Err(Self::session_not_found_rpc(session_id));
        }
        let recovered_create = self
            .recovered_create_request(session_id, session, recovery_overrides)
            .await?;
        let runtime_was_registered = recovered_create.runtime_was_registered;
        let create_request = recovered_create.request;
        let build = match create_request.build.clone() {
            Some(build) => build,
            None => {
                return Err(self
                    .combine_with_recovered_runtime_cleanup(
                        session_id,
                        runtime_was_registered,
                        RpcError {
                            code: error::INTERNAL_ERROR,
                            message: format!(
                                "recovered create request for session {session_id} is missing build options"
                            ),
                            data: None,
                        },
                        "clean up newly recovered runtime after missing build options",
                    )
                    .await);
            }
        };
        let model = create_request.model.clone();
        let mut build_config = AgentBuildConfig::new(model);
        build_config.apply_session_build_options(&build);
        build_config.system_prompt = create_request.system_prompt.clone();
        build_config.max_tokens = create_request.max_tokens;

        // Stage as pending and re-enter the materialization path.
        // Labels are managed by the session service — pass None so
        // CreateSessionRequest.labels is empty and the service preserves
        // whatever labels were stored with the original session.
        let labels: Option<BTreeMap<String, String>> = None;

        {
            let effective_llm_identity =
                match self.llm_identity_from_pending_build(&build_config).await {
                    Ok(identity) => identity,
                    Err(err) => {
                        return Err(self
                        .combine_with_recovered_runtime_cleanup(
                            session_id,
                            runtime_was_registered,
                            err,
                            "clean up newly recovered runtime after identity resolution failure",
                        )
                        .await);
                    }
                };
            let now = now_unix_secs();
            if let Err(err) = self
                .staged_sessions
                .stage(
                    session_id.clone(),
                    StagedSlot::new_staged(
                        session_id,
                        build_config,
                        effective_llm_identity,
                        labels,
                        None,
                        Vec::new(),
                        now,
                        now,
                        false,
                    )
                    .map_err(|err| match err {
                        meerkat::StagedLifecycleError::KeepAliveRequiresCommsName => RpcError {
                            code: error::INVALID_PARAMS,
                            message: "keep_alive requires a session created with comms_name"
                                .to_string(),
                            data: None,
                        },
                        err => RpcError {
                            code: error::INTERNAL_ERROR,
                            message: format!(
                                "generated authority rejected recovered staged session {session_id}: {err}"
                            ),
                            data: None,
                        },
                    })?,
                )
                .await
            {
                return Err(self
                    .combine_with_recovered_runtime_cleanup(
                        session_id,
                        runtime_was_registered,
                        RpcError {
                            code: error::INTERNAL_ERROR,
                            message: format!(
                                "failed to stage recovered session {session_id}: {err}"
                            ),
                            data: None,
                        },
                        "clean up newly recovered runtime after staging failure",
                    )
                    .await);
            }
        }
        if let Err(err) =
            self.insert_staged_capacity_admission(session_id.clone(), admission.into_admission())
        {
            let _ = self.staged_sessions.abandon(session_id).await;
            return Err(self
                .combine_with_recovered_runtime_cleanup(
                    session_id,
                    runtime_was_registered,
                    err,
                    "clean up newly recovered runtime after capacity-admission insertion failure",
                )
                .await);
        }

        // Recursively call start_turn which will now find the pending session.
        // Recovery has already consumed the build overrides. Preserve only
        // the turn-authored System append so the normal StartTurn boundary
        // applies it exactly once.
        let turn_system_override =
            turn_system_prompt.map(|system_prompt| crate::handlers::turn::TurnOverrides {
                system_prompt: Some(system_prompt),
                ..Default::default()
            });
        // Use Box::pin to avoid infinite recursion concerns in async.
        Box::pin(self.start_turn(
            session_id,
            prompt,
            event_tx,
            skill_references,
            turn_tool_overlay,
            additional_instructions,
            turn_system_override,
        ))
        .await
    }

    /// Build the comms-context refresh callback fired after a staged
    /// promotion materializes the live session. With the `comms` feature
    /// enabled this re-syncs `update_peer_ingress_context`; otherwise it
    /// is a no-op (preserving the original `let _ = keep_alive` shape).
    fn comms_context_refresh_callback(
        &self,
        keep_alive: bool,
    ) -> meerkat::session_runtime::staged_promotion::CommsContextRefreshFn {
        #[cfg(feature = "comms")]
        {
            let service = Arc::clone(&self.service);
            let runtime_adapter = Arc::clone(&self.runtime_adapter);
            Arc::new(move |session_id| {
                let service = Arc::clone(&service);
                let runtime_adapter = Arc::clone(&runtime_adapter);
                Box::pin(async move {
                    // W2-G: never reconfigure a mob-owned drain during runtime
                    // materialization. See `start_turn_via_runtime`.
                    let owner = runtime_adapter.peer_ingress_owner(&session_id).await;
                    if !owner.is_mob_owned() {
                        let comms_rt = service.comms_runtime(&session_id).await;
                        let peer_ingress_enabled = match runtime_adapter
                            .session_has_comms(&session_id)
                            .await
                        {
                            Ok(adapter_has_comms) => keep_alive || adapter_has_comms,
                            Err(error) => {
                                tracing::warn!(
                                    %session_id,
                                    error = %error,
                                    "runtime refresh callback could not prove peer-ingress comms state; preserving requested keep_alive only"
                                );
                                keep_alive
                            }
                        };
                        if let Err(error) = runtime_adapter
                            .update_peer_ingress_context(
                                &session_id,
                                peer_ingress_enabled,
                                comms_rt,
                            )
                            .await
                        {
                            // The refresh callback seam is fire-and-forget by
                            // construction; surface the typed fault instead of
                            // silently dropping it.
                            tracing::warn!(
                                %session_id,
                                %error,
                                "comms context refresh after staged promotion failed"
                            );
                        }
                    }
                })
            })
        }
        #[cfg(not(feature = "comms"))]
        {
            let _ = keep_alive;
            Arc::new(move |_session_id| Box::pin(async move {}))
        }
    }

    /// Build the test-only pre-turn hook callback fired by the staged-
    /// promotion helpers immediately before the apply/start turn dispatch.
    /// Returns `None` when no hook is currently armed (or when the
    /// `cfg(test)` field is not present in the build).
    fn pending_promotion_pre_turn_hook_callback(
        &self,
    ) -> Option<meerkat::session_runtime::staged_promotion::PreTurnHookFn> {
        #[cfg(test)]
        {
            let hook_slot = Arc::clone(&self.pending_promotion_pre_turn_hook);
            let hook = hook_slot
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()?;
            Some(Arc::new(move || {
                let hook = Arc::clone(&hook);
                Box::pin(async move {
                    hook.reached_flag
                        .store(true, std::sync::atomic::Ordering::SeqCst);
                    hook.reached.notify_waiters();
                    hook.release.notified().await;
                })
            }))
        }
        #[cfg(not(test))]
        {
            None
        }
    }

    /// Stop one exact run on the given session and terminalize every
    /// contributor bound to it (the run-fenced Stop). A stale run is the
    /// typed `NotCurrent` receipt; an archived session is not found.
    pub async fn stop_run(
        &self,
        session_id: &SessionId,
        run_id: &meerkat_core::lifecycle::RunId,
        reason: String,
    ) -> Result<meerkat_runtime::RunStopReceipt, RpcError> {
        let staged = self
            .staged_sessions
            .info(session_id)
            .await
            .map_err(|err| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("staged session lifecycle error: {err}"),
                data: None,
            })?
            .is_some();
        // A staged (deferred) session has no run yet: the machine reports the
        // stop as `NotCurrent`. Any other session must exist and be live. The
        // check reads no body: the run it stops may hold a provisional tail.
        if !staged {
            match committed_source_archived(&self.service, session_id)
                .await
                .map_err(session_error_to_rpc)?
            {
                None => return Err(Self::session_not_found_rpc(session_id)),
                Some(true) => return Err(Self::archived_session_not_found_rpc(session_id)),
                Some(false) => {}
            }
        }
        self.runtime_adapter
            .stop_run(session_id, run_id, reason)
            .await
            .map_err(runtime_driver_error_to_rpc)
    }

    /// Interrupt a running turn on the given session.
    ///
    /// If the session is idle, this is a no-op.
    pub async fn interrupt(
        &self,
        session_id: &SessionId,
    ) -> Result<meerkat_contracts::wire::WireInterruptOutcome, RpcError> {
        let staged_info = self
            .staged_sessions
            .info(session_id)
            .await
            .map_err(|err| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("staged session lifecycle error: {err}"),
                data: None,
            })?;
        let staged_is_promoting = match staged_info {
            Some(info) if info.is_promoting => true,
            Some(_) if !self.has_staged_capacity_admission(session_id) => true,
            Some(_) => {
                let result = meerkat_runtime::resolve_user_interrupt_public_result(
                    UserInterruptObservation::StagedNoop,
                    true,
                    false,
                )
                .map_err(runtime_driver_error_to_rpc)?;
                return Self::user_interrupt_public_result_to_rpc(session_id, result, None);
            }
            None => false,
        };

        if staged_is_promoting {
            return match self
                .service
                .interrupt_with_machine_authority(
                    session_id,
                    self.runtime_adapter.session_control_authority(),
                )
                .await
            {
                Ok(()) => Ok(meerkat_contracts::wire::WireInterruptOutcome::Interrupted),
                Err(SessionError::NotRunning { .. } | SessionError::NotFound { .. }) => {
                    let result = meerkat_runtime::resolve_user_interrupt_public_result(
                        UserInterruptObservation::NotInterruptible,
                        true,
                        true,
                    )
                    .map_err(runtime_driver_error_to_rpc)?;
                    Self::user_interrupt_public_result_to_rpc(session_id, result, None)
                }
                Err(err) => Err(session_error_to_rpc(err)),
            };
        }

        if self.authoritative_session_archived(session_id).await? {
            return Err(Self::archived_session_not_found_rpc(session_id));
        }

        let (result, conflict_state) = match self
            .runtime_adapter
            .hard_cancel_current_run(session_id, "RPC session runtime interrupt")
            .await
        {
            Ok(()) => (
                meerkat_runtime::resolve_user_interrupt_public_result(
                    UserInterruptObservation::Accepted,
                    true,
                    false,
                ),
                None,
            ),
            Err(RuntimeDriverError::NotReady {
                state: observed_state @ (RuntimeState::Idle | RuntimeState::Attached),
            }) => (
                meerkat_runtime::resolve_user_interrupt_public_result(
                    UserInterruptObservation::NotReady(observed_state),
                    true,
                    false,
                ),
                Some(observed_state),
            ),
            Err(RuntimeDriverError::NotReady {
                state: RuntimeState::Destroyed,
            })
            | Err(RuntimeDriverError::Destroyed) => {
                let target_present = matches!(
                    self.interrupt_noop_target(session_id).await?,
                    InterruptNoopTarget::Present
                );
                (
                    meerkat_runtime::resolve_user_interrupt_public_result(
                        UserInterruptObservation::Destroyed,
                        target_present,
                        false,
                    ),
                    Some(RuntimeState::Destroyed),
                )
            }
            Err(RuntimeDriverError::NotReady { state }) => (
                meerkat_runtime::resolve_user_interrupt_public_result(
                    UserInterruptObservation::NotReady(state),
                    true,
                    false,
                ),
                Some(state),
            ),
            Err(e) => {
                return Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("Failed to interrupt session: {e}"),
                    data: None,
                });
            }
        };
        let result = result.map_err(runtime_driver_error_to_rpc)?;
        Self::user_interrupt_public_result_to_rpc(session_id, result, conflict_state)
    }

    fn promoting_session_busy_rpc(session_id: &SessionId) -> RpcError {
        RpcError {
            code: error::SESSION_BUSY,
            message: format!(
                "session {session_id} is still being materialized and cannot be interrupted yet"
            ),
            data: None,
        }
    }

    fn archived_session_not_found_rpc(session_id: &SessionId) -> RpcError {
        RpcError {
            code: error::SESSION_NOT_FOUND,
            message: format!("Session not found: {session_id}"),
            data: None,
        }
    }

    fn user_interrupt_public_result_to_rpc(
        session_id: &SessionId,
        result: UserInterruptPublicResult,
        conflict_state: Option<RuntimeState>,
    ) -> Result<meerkat_contracts::wire::WireInterruptOutcome, RpcError> {
        match result {
            // #348/K17: both non-error outcomes surface as the typed wire
            // tri-state — a staged-session no-op is reported honestly as
            // `staged_noop`, never collapsed into a fabricated live
            // cancellation.
            UserInterruptPublicResult::Interrupted => {
                Ok(meerkat_contracts::wire::WireInterruptOutcome::Interrupted)
            }
            UserInterruptPublicResult::StagedNoop => {
                Ok(meerkat_contracts::wire::WireInterruptOutcome::StagedNoop)
            }
            UserInterruptPublicResult::NotFound => Err(RpcError {
                code: error::SESSION_NOT_FOUND,
                message: format!("Session not found: {session_id}"),
                data: None,
            }),
            UserInterruptPublicResult::SessionBusy => {
                Err(Self::promoting_session_busy_rpc(session_id))
            }
            UserInterruptPublicResult::Conflict => Err(RpcError {
                code: error::INVALID_REQUEST,
                message: match conflict_state {
                    Some(state) => {
                        format!("Session is not interruptible while runtime is {state}")
                    }
                    None => "Session is not interruptible in its current runtime state".to_string(),
                },
                data: None,
            }),
        }
    }

    pub(crate) async fn interrupt_noop_target(
        &self,
        session_id: &SessionId,
    ) -> Result<InterruptNoopTarget, RpcError> {
        if self.staged_sessions.contains(session_id).await {
            return Ok(InterruptNoopTarget::Present);
        }

        if let Some(session) = self.load_persisted_session(session_id).await? {
            if session_metadata_marks_mob_member(&session) {
                #[cfg(feature = "mob")]
                if let Some(mob_state) = self.mob_state() {
                    let owns_mob_session = mob_state.owns_live_bridge_session(session_id).await
                        || mob_state.owns_persisted_bridge_session(session_id).await;
                    return Ok(interrupt_noop_target_for_presence(owns_mob_session));
                }
                #[cfg(not(feature = "mob"))]
                return Ok(InterruptNoopTarget::Missing);
            }
            return Ok(interrupt_noop_target_for_presence(true));
        }

        #[cfg(feature = "mob")]
        if let Some(mob_state) = self.mob_state()
            && (mob_state.owns_live_bridge_session(session_id).await
                || mob_state.owns_persisted_bridge_session(session_id).await)
        {
            match mob_state.session_service().read(session_id).await {
                Ok(_) => {
                    return Ok(interrupt_noop_target_for_presence(true));
                }
                Err(SessionError::NotFound { .. }) => {}
                Err(err) => return Err(session_error_to_rpc(err)),
            }
        }

        match self.service.read(session_id).await {
            Ok(_) => {
                return Ok(interrupt_noop_target_for_presence(true));
            }
            Err(SessionError::NotFound { .. }) => {}
            Err(err) => return Err(session_error_to_rpc(err)),
        }

        Ok(interrupt_noop_target_for_presence(false))
    }

    /// Ask a running turn to break out at the next cooperative boundary.
    ///
    /// Unlike `interrupt`, this must not hard-cancel the current run. It is used
    /// by runtime peer ingress so queued work can proceed after a wait/yield
    /// boundary without aborting the in-flight turn.
    pub async fn interrupt_yielding(
        &self,
        session_id: &SessionId,
    ) -> Result<meerkat_contracts::wire::WireInterruptOutcome, RpcError> {
        let staged_info = self
            .staged_sessions
            .info(session_id)
            .await
            .map_err(|err| RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("staged session lifecycle error: {err}"),
                data: None,
            })?;
        let staged_is_materializing = match staged_info.as_ref() {
            Some(info) if info.is_promoting => true,
            Some(_) if !self.has_staged_capacity_admission(session_id) => true,
            Some(_) => false,
            None => false,
        };
        if staged_info.is_some() && !staged_is_materializing {
            let result = meerkat_runtime::resolve_user_interrupt_public_result(
                UserInterruptObservation::StagedNoop,
                true,
                false,
            )
            .map_err(runtime_driver_error_to_rpc)?;
            return Self::user_interrupt_public_result_to_rpc(session_id, result, None);
        }
        if staged_is_materializing {
            let result = meerkat_runtime::resolve_user_interrupt_public_result(
                UserInterruptObservation::NotInterruptible,
                true,
                true,
            )
            .map_err(runtime_driver_error_to_rpc)?;
            return Self::user_interrupt_public_result_to_rpc(session_id, result, None);
        }

        if self.authoritative_session_archived(session_id).await? {
            let result = meerkat_runtime::resolve_user_interrupt_public_result(
                UserInterruptObservation::Destroyed,
                false,
                false,
            )
            .map_err(runtime_driver_error_to_rpc)?;
            return Self::user_interrupt_public_result_to_rpc(
                session_id,
                result,
                Some(RuntimeState::Destroyed),
            );
        }

        let (result, conflict_state) =
            match self.runtime_adapter.cancel_after_boundary(session_id).await {
                Ok(()) => (
                    meerkat_runtime::resolve_user_interrupt_public_result(
                        UserInterruptObservation::Accepted,
                        true,
                        false,
                    ),
                    None,
                ),
                Err(RuntimeDriverError::NotReady {
                    state: observed_state @ (RuntimeState::Idle | RuntimeState::Attached),
                }) => (
                    meerkat_runtime::resolve_user_interrupt_public_result(
                        UserInterruptObservation::NotReady(observed_state),
                        true,
                        false,
                    ),
                    Some(observed_state),
                ),
                Err(RuntimeDriverError::NotReady {
                    state: RuntimeState::Destroyed,
                })
                | Err(RuntimeDriverError::Destroyed) => {
                    let target_present = matches!(
                        self.interrupt_noop_target(session_id).await?,
                        InterruptNoopTarget::Present
                    );
                    (
                        meerkat_runtime::resolve_user_interrupt_public_result(
                            UserInterruptObservation::Destroyed,
                            target_present,
                            false,
                        ),
                        Some(RuntimeState::Destroyed),
                    )
                }
                Err(RuntimeDriverError::NotReady { state }) => (
                    meerkat_runtime::resolve_user_interrupt_public_result(
                        UserInterruptObservation::NotReady(state),
                        true,
                        false,
                    ),
                    Some(state),
                ),
                Err(e) => Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("Failed to interrupt session at boundary: {e}"),
                    data: None,
                })?,
            };
        let result = result.map_err(runtime_driver_error_to_rpc)?;
        Self::user_interrupt_public_result_to_rpc(session_id, result, conflict_state)
    }

    /// Append one ordinary durable System message to a pending, live, or
    /// persisted session.
    pub async fn append_system_context(
        &self,
        session_id: &SessionId,
        req: AppendSystemContextRequest,
    ) -> Result<AppendSystemContextResult, RpcError> {
        self.append_system_context_typed(session_id, req)
            .await
            .map_err(system_context_error_to_rpc)
    }

    /// Internal typed path also used by durable delivery. Never recover native
    /// authorization dispositions by parsing an RPC message.
    async fn append_system_context_typed(
        &self,
        session_id: &SessionId,
        req: AppendSystemContextRequest,
    ) -> Result<AppendSystemContextResult, SessionControlError> {
        if self.runtime_adapter.has_native_work_authorization_host() {
            let control = meerkat_core::service::SystemContextAppendControl::unavailable(
                session_id.clone(),
                req.clone(),
            )?;
            match self
                .staged_sessions
                .apply_system_context_control(&control, now_unix_secs())
                .await
            {
                Ok(Some(result)) => return result,
                Ok(None) => {}
                Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                    return self
                        .service
                        .append_system_context(session_id, req)
                        .await
                        .map_err(|error| system_context_promotion_error(error, session_id));
                }
                Err(error) => {
                    return Err(SessionControlError::InvalidRequest {
                        message: error.to_string(),
                    });
                }
            }
        } else {
            match self
                .staged_sessions
                .append_ordered_system_message(session_id, &req, now_unix_secs())
                .await
            {
                Ok(Some(status)) => return Ok(AppendSystemContextResult { status }),
                Ok(None) => {}
                Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                    return self
                        .service
                        .append_system_context(session_id, req)
                        .await
                        .map_err(|error| system_context_promotion_error(error, session_id));
                }
                Err(error) => {
                    return Err(SessionControlError::InvalidRequest {
                        message: error.to_string(),
                    });
                }
            }
        }
        self.service.append_system_context(session_id, req).await
    }

    pub async fn append_authenticated_system_context(
        &self,
        control: Arc<meerkat_core::service::SystemContextControlRequest>,
    ) -> Result<AppendSystemContextResult, SessionControlError> {
        let prepared = self
            .runtime_adapter
            .prepare_context_append_observed(Arc::clone(&control));
        let command = meerkat_core::service::SystemContextAppendControl::from_observed_preparation(
            Arc::clone(&control),
            prepared,
        );
        match self
            .staged_sessions
            .apply_system_context_control(&command, now_unix_secs())
            .await
        {
            Ok(Some(result)) => result,
            Ok(None) => {
                self.service
                    .append_authenticated_system_context(control)
                    .await
            }
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                let id = control.session_id().clone();
                self.service
                    .append_authenticated_system_context(control)
                    .await
                    .map_err(|error| system_context_promotion_error(error, &id))
            }
            Err(error) => Err(SessionControlError::InvalidRequest {
                message: error.to_string(),
            }),
        }
    }

    pub async fn append_authorized_system_context(
        &self,
        prepared: meerkat_core::service::PreparedSystemContextAppend,
    ) -> Result<AppendSystemContextResult, SessionControlError> {
        if !self.runtime_adapter.owns_context_append(&prepared) {
            return Err(meerkat_core::OperationAuthorizationError::Unavailable.into());
        }
        let control =
            meerkat_core::service::SystemContextAppendControl::authorized(prepared.clone());
        match self
            .staged_sessions
            .apply_system_context_control(&control, now_unix_secs())
            .await
        {
            Ok(Some(result)) => result,
            Ok(None) => {
                self.service
                    .append_authorized_system_context(prepared)
                    .await
            }
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                let id = prepared.session_id().clone();
                self.service
                    .append_authorized_system_context(prepared)
                    .await
                    .map_err(|error| system_context_promotion_error(error, &id))
            }
            Err(error) => Err(SessionControlError::InvalidRequest {
                message: error.to_string(),
            }),
        }
    }

    /// Get the current state of a session, or `Ok(None)` if the session does
    /// not exist.
    ///
    /// A store-layer failure is surfaced as a typed `RpcError` rather than
    /// collapsed to `Ok(None)`: collapsing would make a genuine store failure
    /// indistinguishable from "session not found", laundering a control-plane
    /// fault into a not-found at the wire boundary.
    pub async fn session_state(
        &self,
        session_id: &SessionId,
    ) -> Result<Option<SessionInfo>, RpcError> {
        // Check pending sessions first.
        {
            if let Some(info) = self.staged_sessions.project_info(session_id).await {
                return Ok(Some(SessionInfo {
                    session_id: session_id.clone(),
                    state: if info.is_promoting {
                        SessionState::Running
                    } else {
                        SessionState::Idle
                    },
                    labels: info.labels,
                }));
            }
        }

        // Use `list()` instead of `read()` to avoid blocking on a
        // `ReadSnapshot` command while a turn is in progress. `list()`
        // reads state from non-blocking watch receivers.
        let summaries = self
            .service
            .list(Default::default())
            .await
            .map_err(session_error_to_rpc)?;
        for summary in summaries {
            if summary.session_id == *session_id {
                return Ok(Some(SessionInfo {
                    session_id: summary.session_id,
                    state: if summary.is_active {
                        SessionState::Running
                    } else {
                        SessionState::Idle
                    },
                    labels: summary.labels,
                }));
            }
        }

        Ok(None)
    }

    pub async fn pending_session_exists(&self, session_id: &SessionId) -> bool {
        self.staged_sessions.contains(session_id).await
    }

    async fn apply_pending_keep_alive_override(
        &self,
        session_id: &SessionId,
        keep_alive: bool,
    ) -> Result<bool, RpcError> {
        match self
            .staged_sessions
            .update_keep_alive(session_id, keep_alive, now_unix_secs())
            .await
        {
            Ok(applied) => Ok(applied),
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => Err(RpcError {
                code: error::SESSION_BUSY,
                message: format!("session {session_id} is already being materialized"),
                data: None,
            }),
            Err(meerkat::StagedLifecycleError::KeepAliveRequiresCommsName) => Err(RpcError {
                code: error::INVALID_PARAMS,
                message: "keep_alive requires a session created with comms_name".to_string(),
                data: None,
            }),
            Err(err) => Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("staged session lifecycle error: {err}"),
                data: None,
            }),
        }
    }

    async fn authorize_promoting_keep_alive_override(
        &self,
        session_id: &SessionId,
        keep_alive: bool,
        has_comms_name: bool,
    ) -> Result<(), RpcError> {
        match self
            .staged_sessions
            .authorize_promoting_keep_alive(session_id, keep_alive, has_comms_name)
            .await
        {
            Ok(true) => Ok(()),
            Ok(false) => Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "staged session {session_id} disappeared during keep_alive authorization"
                ),
                data: None,
            }),
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => Err(RpcError {
                code: error::SESSION_BUSY,
                message: format!("session {session_id} is already being materialized"),
                data: None,
            }),
            Err(meerkat::StagedLifecycleError::KeepAliveRequiresCommsName) => Err(RpcError {
                code: error::INVALID_PARAMS,
                message: "keep_alive requires a session created with comms_name".to_string(),
                data: None,
            }),
            Err(err) => Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("staged session lifecycle error: {err}"),
                data: None,
            }),
        }
    }

    async fn authorize_promoting_llm_identity_override(
        &self,
        session_id: &SessionId,
        identity: &SessionLlmIdentity,
    ) -> Result<(), RpcError> {
        match self
            .staged_sessions
            .update_effective_llm_identity(session_id, identity)
            .await
        {
            Ok(true) => Ok(()),
            Ok(false) => Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!(
                    "staged session {session_id} disappeared during llm identity authorization"
                ),
                data: None,
            }),
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => Err(RpcError {
                code: error::SESSION_BUSY,
                message: format!("session {session_id} is already being materialized"),
                data: None,
            }),
            Err(err) => Err(RpcError {
                code: error::INTERNAL_ERROR,
                message: format!("staged session lifecycle error: {err}"),
                data: None,
            }),
        }
    }

    /// Read the authoritative session view from the owning session service.
    pub async fn read_session(
        &self,
        session_id: &SessionId,
    ) -> Result<meerkat_core::service::SessionView, RpcError> {
        self.service
            .read(session_id)
            .await
            .map_err(session_error_to_rpc)
    }

    /// Load the persisted session snapshot for authoritative post-turn inspection.
    pub async fn load_persisted_session(
        &self,
        session_id: &SessionId,
    ) -> Result<Option<Session>, RpcError> {
        let snapshot = self.realm_context_snapshot();
        self.recovery_context(&snapshot, Some(session_id))
            .load_persisted_session(session_id)
            .await
            .map_err(session_error_to_rpc)
    }

    /// The persisted session for a read of its metadata (LLM identity, help
    /// flag, keep-alive) taken before the attach or resume that decides an
    /// open run: the committed snapshot under the session's own run's
    /// provisional tail, with the archived-as-absent rule of
    /// [`Self::load_persisted_session`]. Metadata a run changes lands at the
    /// run's boundary, so the committed snapshot holds the session's
    /// metadata until that run ends; the attach or resume that follows still
    /// decides the tail strictly. A read failure stays an error.
    async fn load_persisted_session_tolerating_tail(
        &self,
        session_id: &SessionId,
    ) -> Result<Option<Session>, RpcError> {
        let Some(session) = self
            .service
            .load_committed_session_tolerating_tail(session_id)
            .await
            .map_err(session_error_to_rpc)?
        else {
            return Ok(None);
        };
        if self
            .service
            .session_archived_by_authority(session_id, &session)
            .await
            .map_err(session_error_to_rpc)?
        {
            return Ok(None);
        }
        Ok(Some(session))
    }

    /// Whether the RuntimeStore holds an absorbing archive terminal for the
    /// session. It reads no body, so an interrupt or a stop of a running
    /// durable run is not refused by the run's provisional tail.
    pub(crate) async fn authoritative_session_archived(
        &self,
        session_id: &SessionId,
    ) -> Result<bool, RpcError> {
        committed_source_archived(&self.service, session_id)
            .await
            .map(|archived| archived == Some(true))
            .map_err(session_error_to_rpc)
    }

    /// Archive (remove) a session.
    pub async fn archive_session(&self, session_id: &SessionId) -> Result<(), RpcError> {
        let archived = self.archive_session_inner(session_id).await;
        if archived.is_ok() {
            // An archived session has no live callback owner left to route to.
            self.unbind_session_callback_route(session_id);
        }
        archived
    }

    async fn archive_session_inner(&self, session_id: &SessionId) -> Result<(), RpcError> {
        let expected_attachment = self.publication_attachment_witness(session_id);
        // Check pending sessions first.
        match self.staged_sessions.begin_archive(session_id).await {
            Ok(true) => {
                let mut staged_archive_guard =
                    StagedArchiveRollbackGuard::new(Arc::clone(&self.staged_sessions), session_id);
                #[cfg(test)]
                let staged_archive_after_service_hook = {
                    let guard = self
                        .staged_archive_after_service_hook
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    guard.clone()
                };
                let staged_capacity_admission =
                    match self.take_staged_capacity_admission(session_id) {
                        Some(admission) => Some(admission),
                        None => {
                            self.staged_sessions.restore_archive(session_id).await;
                            staged_archive_guard.disarm();
                            return Err(RpcError {
                                code: error::SESSION_BUSY,
                                message: format!("session {session_id} has active work"),
                                data: None,
                            });
                        }
                    };

                await_guarded_staged_archive(
                    Arc::clone(&self.service),
                    Arc::clone(&self.staged_sessions),
                    Arc::clone(&self.staged_capacity_admissions),
                    staged_capacity_admission,
                    self.archive_runtime_cleanup(),
                    session_id.clone(),
                    staged_archive_guard,
                    #[cfg(test)]
                    staged_archive_after_service_hook,
                )
                .await
                .map_err(session_error_to_rpc)?;
                self.clear_publication_sidecars_if_current(
                    session_id,
                    expected_attachment.as_ref(),
                );
                return Ok(());
            }
            Ok(false) => {}
            Err(meerkat::StagedLifecycleError::AlreadyPromoting(_)) => {
                return Err(RpcError {
                    code: error::SESSION_BUSY,
                    message: format!("session {session_id} is already being materialized"),
                    data: None,
                });
            }
            Err(err) => {
                return Err(RpcError {
                    code: error::INTERNAL_ERROR,
                    message: format!("staged session lifecycle error: {err}"),
                    data: None,
                });
            }
        }

        let result = await_session_archive_with_runtime_cleanup(
            Arc::clone(&self.service),
            self.archive_runtime_cleanup(),
            session_id.clone(),
        )
        .await;
        if result.is_ok() || matches!(&result, Err(SessionError::NotFound { .. })) {
            self.clear_publication_sidecars_if_current(session_id, expected_attachment.as_ref());
        }
        result.map_err(session_error_to_rpc)
    }

    /// List all active sessions, optionally filtered by query parameters.
    ///
    /// A store-layer failure is surfaced as a typed `RpcError` rather than
    /// collapsed into a partial list (pending sessions only): a partial list
    /// would silently misreport a control-plane fault as an authoritative empty
    /// or short result.
    pub async fn list_sessions(&self, query: SessionQuery) -> Result<Vec<SessionInfo>, RpcError> {
        let mut result = Vec::new();

        // Include pending sessions as Idle, filtered by labels if requested.
        for (session_id, info) in self.staged_sessions.list(query.labels.as_ref()).await {
            result.push(SessionInfo {
                session_id,
                state: if info.is_promoting {
                    SessionState::Running
                } else {
                    SessionState::Idle
                },
                labels: info.labels,
            });
        }

        // Include active sessions from the service. The service's `list()`
        // already handles label filtering on materialized sessions.
        let summaries = self
            .service
            .list(query)
            .await
            .map_err(session_error_to_rpc)?;
        for summary in summaries {
            let state = if summary.is_active {
                SessionState::Running
            } else {
                SessionState::Idle
            };
            result.push(SessionInfo {
                session_id: summary.session_id,
                state,
                labels: summary.labels,
            });
        }

        Ok(result)
    }

    /// List all active sessions as canonical wire summaries, including pending sessions.
    ///
    /// A store-layer failure is surfaced as a typed `RpcError` rather than
    /// collapsed into a partial list (pending sessions only): a partial list
    /// would silently misreport a control-plane fault as an authoritative empty
    /// or short result on the wire.
    pub async fn list_sessions_rich(
        &self,
        query: SessionQuery,
    ) -> Result<Vec<meerkat_contracts::WireSessionSummary>, RpcError> {
        let mut result = Vec::new();
        let pending = self.staged_sessions.list(query.labels.as_ref()).await;
        let pending_count = pending.len();
        let requested_offset = query.offset.unwrap_or(0);
        let requested_limit = query.limit;

        // Include pending sessions as synthetic entries.
        let pending_iter = pending
            .into_iter()
            .skip(requested_offset)
            .take(requested_limit.unwrap_or(usize::MAX));
        for (session_id, info) in pending_iter {
            result.push(meerkat_contracts::WireSessionSummary {
                session_id,
                session_ref: None,
                created_at: info.created_at_secs,
                updated_at: info.updated_at_secs,
                message_count: 0,
                total_tokens: 0,
                is_active: info.is_promoting,
                labels: info.labels,
            });
        }

        // Continue pagination in the materialized store after the synthetic
        // pending prefix. Passing the remaining limit/offset into the service
        // prevents the RPC handler from loading the entire session catalog and
        // truncating only after allocation.
        let service_query = SessionQuery {
            labels: query.labels,
            offset: Some(requested_offset.saturating_sub(pending_count)),
            limit: requested_limit.map(|limit| limit.saturating_sub(result.len())),
        };
        let summaries = self
            .service
            .list(service_query)
            .await
            .map_err(session_error_to_rpc)?;
        for summary in summaries {
            result.push(summary.into());
        }

        Ok(result)
    }

    /// Read a session as a canonical wire info object, checking pending and materialized.
    ///
    /// Returns `Ok(None)` only when the session genuinely does not exist. A
    /// store-layer failure on `list()` or `read()` is surfaced as a typed
    /// `RpcError` rather than collapsed to `Ok(None)`: collapsing would launder
    /// a control-plane fault into a "session not found" at the wire boundary.
    pub async fn read_session_rich(
        &self,
        session_id: &SessionId,
    ) -> Result<Option<meerkat_contracts::WireSessionInfo>, RpcError> {
        // Check pending sessions first.
        if let Some(info) = self.staged_sessions.project_info(session_id).await {
            let wire = meerkat_contracts::WireSessionInfo {
                session_id: session_id.clone(),
                session_ref: None,
                created_at: info.created_at_secs,
                updated_at: info.updated_at_secs,
                message_count: 0,
                is_active: info.is_promoting,
                model: info.effective_llm_identity.model.clone(),
                provider: info.effective_llm_identity.provider.as_str().to_string(),
                last_assistant_text: None,
                resolved_capabilities: self
                    .wire_resolved_capabilities_for_identity(&info.effective_llm_identity)
                    .await,
                labels: info.labels,
            };
            // Staged sessions have no machine-resolved capability surface
            // yet; the identity-derived projection set above is the honest
            // pre-resolution advertisement.
            return Ok(Some(wire));
        }

        // Try list() first — non-blocking (uses watch receivers).
        let summaries = self
            .service
            .list(Default::default())
            .await
            .map_err(session_error_to_rpc)?;
        for summary in summaries {
            if summary.session_id == *session_id {
                if !summary.is_active {
                    // Idle session: safe to call read() without blocking,
                    // which provides last_assistant_text.
                    match self.service.read(session_id).await {
                        Ok(view) => {
                            let mut info = view.state.into();
                            self.attach_resolved_capabilities_to_wire_info(&mut info)
                                .await?;
                            return Ok(Some(info));
                        }
                        // The session was archived between list() and read():
                        // fall through to build from the summary below.
                        Err(SessionError::NotFound { .. }) => {}
                        // Any other store failure is a genuine control-plane
                        // fault and must not be laundered into a summary-only
                        // success or a not-found.
                        Err(other) => return Err(session_error_to_rpc(other)),
                    }
                }
                // Active session: return summary without last_assistant_text
                // to avoid blocking the caller during a running turn.
                let wire: meerkat_contracts::WireSessionSummary = summary.into();
                let llm_identity = self
                    .service
                    .live_session_llm_identity(session_id)
                    .await
                    .map_err(session_error_to_rpc)?;
                let mut info = meerkat_contracts::WireSessionInfo {
                    session_id: wire.session_id,
                    session_ref: None,
                    created_at: wire.created_at,
                    updated_at: wire.updated_at,
                    message_count: wire.message_count,
                    is_active: wire.is_active,
                    model: llm_identity.model,
                    provider: llm_identity.provider.as_str().to_string(),
                    last_assistant_text: None,
                    resolved_capabilities: None,
                    labels: wire.labels,
                };
                self.attach_resolved_capabilities_to_wire_info(&mut info)
                    .await?;
                return Ok(Some(info));
            }
        }

        // Fallback: try read() for archived/persisted sessions not in the live
        // list. A genuine not-found is reported as Ok(None); any other store
        // failure is surfaced as a typed error.
        match self.service.read(session_id).await {
            Ok(view) => {
                let mut info = view.state.into();
                self.attach_resolved_capabilities_to_wire_info(&mut info)
                    .await?;
                Ok(Some(info))
            }
            Err(SessionError::NotFound { .. }) => Ok(None),
            Err(other) => Err(session_error_to_rpc(other)),
        }
    }

    /// Whether this runtime has a durable event replay projection installed.
    pub fn supports_event_replay(&self) -> bool {
        self.service.has_event_projection()
    }

    /// Read the latest durable event cursor for a session scope.
    pub async fn event_latest_cursor(
        &self,
        scope: meerkat_contracts::EventReplayScope,
    ) -> Result<Option<meerkat_contracts::EventReplayCursor>, RpcError> {
        let session_id = scope.session_id().clone();
        let latest = self
            .service
            .event_log_latest_seq(&session_id)
            .await
            .map_err(session_error_to_rpc)?;
        let Some(sequence) = latest else {
            return Ok(None);
        };
        if sequence == 0 && self.read_session_rich(&session_id).await?.is_none() {
            return Err(RpcError {
                code: error::SESSION_NOT_FOUND,
                message: format!("Session not found: {session_id}"),
                data: None,
            });
        }
        Ok(Some(meerkat_contracts::EventReplayCursor::new(
            scope, sequence,
        )))
    }

    /// Read durable events after a typed cursor.
    pub async fn event_list_since(
        &self,
        params: meerkat_contracts::EventsListSinceParams,
    ) -> Result<Option<meerkat_contracts::EventsListSinceResult>, RpcError> {
        let latest = match self.event_latest_cursor(params.scope.clone()).await? {
            Some(cursor) => cursor,
            None => return Ok(None),
        };
        let from_cursor = params
            .cursor
            .unwrap_or_else(|| meerkat_contracts::EventReplayCursor::new(params.scope.clone(), 0));
        let from_seq = from_cursor
            .validate_for_list_since(&params.scope, latest.sequence)
            .map_err(|err| RpcError {
                code: error::INVALID_PARAMS,
                message: match err {
                    meerkat_contracts::EventReplayCursorError::ScopeMismatch => {
                        "event replay cursor scope does not match requested scope".to_string()
                    }
                    meerkat_contracts::EventReplayCursorError::AheadOfLatest {
                        requested_sequence,
                        latest_sequence,
                    } => format!(
                        "event replay cursor sequence {requested_sequence} is ahead of latest sequence {latest_sequence}"
                    ),
                    meerkat_contracts::EventReplayCursorError::SequenceOverflow => {
                        "event replay cursor sequence overflow".to_string()
                    }
                },
                data: None,
            })?;
        let session_id = params.scope.session_id().clone();
        let limit = params.limit.unwrap_or(1).max(1);
        let stored = self
            .service
            .event_log_read_page(&session_id, from_seq, limit.saturating_add(1))
            .await
            .map_err(session_error_to_rpc)?
            .unwrap_or_default();
        let has_more = stored.len() > limit;
        let events = stored
            .into_iter()
            .take(limit)
            .map(|stored| replay_envelope_from_stored(&session_id, stored))
            .collect();
        Ok(Some(meerkat_contracts::EventsListSinceResult {
            contract_version: meerkat_contracts::ContractVersion::CURRENT,
            scope: params.scope,
            from_cursor,
            latest_cursor: latest,
            events,
            has_more,
        }))
    }

    /// Read a point-in-time session snapshot and its paired replay cursor.
    pub async fn event_snapshot(
        &self,
        scope: meerkat_contracts::EventReplayScope,
    ) -> Result<Option<meerkat_contracts::EventsSnapshotResult>, RpcError> {
        let latest = match self.event_latest_cursor(scope.clone()).await? {
            Some(cursor) => cursor,
            None => return Ok(None),
        };
        let session = self
            .read_session_rich(scope.session_id())
            .await?
            .ok_or_else(|| RpcError {
                code: error::SESSION_NOT_FOUND,
                message: format!("Session not found: {}", scope.session_id()),
                data: None,
            })?;
        Ok(Some(meerkat_contracts::EventsSnapshotResult {
            contract_version: meerkat_contracts::ContractVersion::CURRENT,
            scope,
            cursor: latest,
            snapshot: meerkat_contracts::EventsSnapshotBody::Session { session },
        }))
    }

    /// Read a session transcript as canonical wire history, including pending sessions.
    pub async fn read_session_history_rich(
        &self,
        session_id: &SessionId,
        query: SessionHistoryQuery,
    ) -> Result<Option<meerkat_contracts::WireSessionHistory>, RpcError> {
        if self.staged_sessions.contains(session_id).await {
            return Ok(Some(meerkat_contracts::WireSessionHistory {
                session_id: session_id.clone(),
                session_ref: None,
                message_count: 0,
                offset: query.offset,
                limit: query.limit,
                has_more: false,
                messages: Vec::new(),
            }));
        }

        // A genuine not-found is Ok(None); any other store failure is a
        // control-plane fault and propagates as a typed RpcError — collapsing
        // it would launder a store fault into a "session not found".
        match self.service.read_history(session_id, query).await {
            Ok(history) => Ok(Some(history.into())),
            Err(SessionError::NotFound { .. }) => Ok(None),
            Err(other) => Err(session_error_to_rpc(other)),
        }
    }

