    /// A turn writes its `session/event` copies unless every one of its
    /// inputs was admitted by a request that opted out, and a request's
    /// opt-out ends with the request.
    #[tokio::test]
    async fn a_turn_writes_session_events_unless_every_input_opted_out() {
        let temp = tempfile::tempdir().expect("tempdir");
        let runtime = make_runtime(temp_factory(&temp), 4);
        let session = SessionId::new();
        let opted_out = InputId::new();
        let wants = InputId::new();
        let request = runtime.record_turn_session_events_opt_out(&session, &opted_out);

        assert!(!runtime.turn_writes_session_events(&session, std::slice::from_ref(&opted_out)));
        assert!(
            runtime.turn_writes_session_events(&session, &[opted_out.clone(), wants.clone()]),
            "another input of the same turn wants the events"
        );
        assert!(runtime.turn_writes_session_events(&session, std::slice::from_ref(&wants)));
        assert!(
            runtime.turn_writes_session_events(&SessionId::new(), std::slice::from_ref(&opted_out)),
            "the opt-out is per session"
        );
        assert!(runtime.turn_writes_session_events(&session, &[]));

        drop(request);
        assert!(
            runtime.turn_writes_session_events(&session, std::slice::from_ref(&opted_out)),
            "the opt-out ends with its request"
        );
    }

    /// #61/#67 gate: direct session-create provider resolution mirrors REST's
    /// fail-closed `resolve_validation_identity`.
    ///
    /// - A model string with **no** explicit provider and **no** registered
    ///   catalog owner returns `INVALID_PARAMS` — pre-fix this path inferred
    ///   a provider from the model string (`ModelCatalog::infer_provider`),
    ///   minting an unblessed provider hint instead of failing closed.
    /// - A registered catalog model with no provider resolves to the catalog
    ///   owner.
    /// - An explicit provider that contradicts the catalog owner is rejected.
    #[tokio::test]
    async fn create_provider_resolves_through_registered_owner_fail_closed() {
        let temp = tempfile::tempdir().expect("tempdir");
        let runtime = make_runtime(temp_factory(&temp), 4);

        // No registered owner + no explicit provider -> fail closed.
        let unknown = AgentBuildConfig::new("totally-unregistered-model-xyz");
        let err = runtime
            .resolve_create_provider(&unknown)
            .await
            .expect_err("unknown model with no provider must fail closed, not infer");
        assert_eq!(err.code, error::INVALID_PARAMS);
        assert!(
            err.message
                .contains("explicit provider or a registered model owner"),
            "fail-closed message must name the missing owner contract: {}",
            err.message
        );

        // Registered catalog model with no explicit provider -> catalog owner.
        let registered = AgentBuildConfig::new("claude-sonnet-4-5");
        let provider = runtime
            .resolve_create_provider(&registered)
            .await
            .expect("registered catalog model must resolve to its owner");
        assert_eq!(provider, meerkat_core::Provider::Anthropic);

        // Explicit provider that contradicts the catalog owner -> rejected.
        let mismatched = AgentBuildConfig {
            provider: Some(meerkat_core::Provider::OpenAI),
            ..AgentBuildConfig::new("claude-sonnet-4-5")
        };
        let err = runtime
            .resolve_create_provider(&mismatched)
            .await
            .expect_err("explicit provider contradicting the catalog owner must be rejected");
        assert_eq!(err.code, error::INVALID_PARAMS);
    }

    #[tokio::test]
    async fn pending_build_identity_rejects_unknown_model_without_provider() {
        let temp = tempfile::tempdir().expect("tempdir");
        let runtime = make_runtime(temp_factory(&temp), 4);
        let build_config = AgentBuildConfig::new("totally-unregistered-model-xyz");

        let err = runtime
            .llm_identity_from_pending_build(&build_config)
            .await
            .expect_err("pending staging identity must fail closed for unknown owner");

        assert_eq!(err.code, error::INVALID_PARAMS);
        assert!(
            err.message
                .contains("explicit provider or a registered model owner"),
            "error should name the missing registry owner contract: {}",
            err.message
        );
    }

    #[tokio::test]
    async fn create_session_rejects_unknown_model_before_staging_slot() {
        let temp = tempfile::tempdir().expect("tempdir");
        let runtime = make_runtime(temp_factory(&temp), 4);
        let build_config = AgentBuildConfig::new("totally-unregistered-model-xyz");

        let err = runtime
            .create_session(build_config, None, None, Vec::new())
            .await
            .expect_err("deferred create must reject before reserving a pending session");

        assert_eq!(err.code, error::INVALID_PARAMS);
        assert_eq!(
            runtime.staged_sessions.len().await,
            0,
            "unknown-model create must not leave a staged session behind"
        );
    }

    /// B19 helper sanity: realtime capability lookup must round-trip the
    /// catalogued `gpt-realtime*` rows as `realtime: true` and report any
    /// non-realtime catalog entry as `realtime: false`. This guards the
    /// `precheck_live_open` gate against silent catalog drift.
    #[test]
    fn realtime_capability_lookup_table() {
        use meerkat_core::Provider;
        use meerkat_models::capabilities_for;

        let realtime = capabilities_for(Provider::OpenAI, "gpt-realtime-2")
            .expect("gpt-realtime-2 should be present in the catalog");
        assert!(
            realtime.realtime,
            "gpt-realtime-2 is the canonical realtime model; capability row must mark it realtime"
        );
        // Round-5 catalog cleanup retired `gpt-realtime` and
        // `gpt-realtime-1.5`; gpt-realtime-2 is the only realtime row
        // in the catalog now. The B18/B19 precheck and surface
        // capability projections all flow through this single row.

        // Pick an arbitrary non-realtime OpenAI model from the catalog to
        // confirm the negative path: Codex/standard chat models are not
        // realtime-capable and must fail the precheck.
        let codex = capabilities_for(Provider::OpenAI, "gpt-5.3-codex")
            .expect("gpt-5.3-codex should be present in the catalog");
        assert!(
            !codex.realtime,
            "non-realtime catalog entries must report realtime=false"
        );

        // Unknown model must return None — callers must treat None as
        // "not realtime-capable" (precheck_live_open does this via
        // `unwrap_or(false)`).
        assert!(capabilities_for(Provider::OpenAI, "no-such-model").is_none());
    }

    /// Provider-adapter ownership pin.
    ///
    /// `apply_precheck_gates` is intentionally surface-agnostic and only owns
    /// the B19 realtime-capability gate. Provider-adapter support needs the
    /// concrete realtime session factory, so the live-open handler resolves it
    /// after precheck through `RealtimeSessionFactory::supports_provider`.
    #[test]
    fn apply_precheck_gates_allows_realtime_non_openai_for_factory_support_check() {
        apply_precheck_gates(
            meerkat_core::Provider::Gemini,
            "gemini-3-live-hypothetical",
            true,
        )
        .expect("provider adapter support is checked by the live session factory");
    }

    /// B19 gate pin.
    ///
    /// Non-realtime models fail before any provider-adapter support check,
    /// because adapter support is only meaningful for realtime-capable models.
    #[test]
    fn apply_precheck_gates_b19_fires_before_b18() {
        let result = apply_precheck_gates(
            meerkat_core::Provider::Gemini,
            "gemini-3.5-flash",
            // Synthesized: matches the catalog reality (Gemini chat models
            // are realtime: false). Without the explicit ordering check,
            // a refactor could plausibly choose to reject on provider
            // first; this test pins the contract.
            false,
        );
        match result {
            Err(LiveOpenPrecheckError::ModelNotRealtime { model, provider }) => {
                assert_eq!(model, "gemini-3.5-flash");
                assert_eq!(provider, "gemini");
            }
            other => panic!(
                "B19 must fire before B18 — expected ModelNotRealtime for non-realtime Gemini, \
                 got {other:?}"
            ),
        }
    }

    /// Positive control for the gate helper: realtime-capable OpenAI must
    /// pass both gates. Catches a regression where the helper accidentally
    /// rejects all inputs after a refactor.
    #[test]
    fn apply_precheck_gates_accepts_realtime_openai() {
        apply_precheck_gates(meerkat_core::Provider::OpenAI, "gpt-realtime-2", true)
            .expect("realtime-capable OpenAI must pass both gates");
    }

