    async fn await_no_turn_hook(hook: &PendingPromotionPreTurnHook) {
        tokio::time::timeout(std::time::Duration::from_secs(10), async {
            while !hook.reached_flag.load(AtomicOrdering::SeqCst) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("no-turn materialization reached barrier");
    }

    fn install_no_turn_hook(runtime: &SessionRuntime) -> Arc<PendingPromotionPreTurnHook> {
        let hook = Arc::new(PendingPromotionPreTurnHook {
            reached_flag: std::sync::atomic::AtomicBool::new(false),
            reached: Notify::new(),
            release: Notify::new(),
        });
        *runtime.runtime_routed_pre_promotion_hook.lock().unwrap() = Some(Arc::clone(&hook));
        hook
    }

    #[tokio::test]
    async fn no_turn_actor_build_cancellation_preserves_owned_capacity_and_durable_predecessor() {
        struct BlockingBuildConfig {
            inner: meerkat_core::MemoryConfigStore,
            hook: Arc<PendingPromotionPreTurnHook>,
            armed: std::sync::atomic::AtomicBool,
        }

        #[async_trait]
        impl ConfigStore for BlockingBuildConfig {
            async fn get(&self) -> Result<Config, meerkat_core::config::ConfigError> {
                if self.armed.swap(false, AtomicOrdering::SeqCst) {
                    let released = self.hook.release.notified();
                    self.hook.reached_flag.store(true, AtomicOrdering::SeqCst);
                    self.hook.reached.notify_waiters();
                    released.await;
                }
                self.inner.get().await
            }

            async fn set(&self, config: Config) -> Result<(), meerkat_core::config::ConfigError> {
                self.inner.set(config).await
            }

            async fn patch(
                &self,
                delta: meerkat_core::config::ConfigDelta,
            ) -> Result<Config, meerkat_core::config::ConfigError> {
                self.inner.patch(delta).await
            }
        }

        for recovering in [false, true] {
            let temp = tempfile::tempdir_in(".").unwrap();
            let seed_runtime = no_turn_disk_runtime(temp.path()).await;
            let resume_id = if recovering {
                let id = seed_runtime
                    .create_or_resume_session_without_turn(
                        mock_build_config(),
                        None,
                        None,
                        Default::default(),
                    )
                    .await
                    .unwrap();
                let (event_tx, _event_rx) = mpsc::channel(100);
                seed_runtime
                    .start_turn_via_runtime(
                        &id,
                        "preserve this committed predecessor".into(),
                        Vec::new(),
                        event_tx,
                        None,
                        None,
                        None,
                        None,
                    )
                    .await
                    .unwrap();
                Some(id)
            } else {
                None
            };
            let predecessor = match resume_id.as_ref() {
                Some(id) => Some(
                    serde_json::to_value(
                        seed_runtime
                            .load_persisted_session(id)
                            .await
                            .unwrap()
                            .unwrap(),
                    )
                    .unwrap(),
                ),
                None => None,
            };
            seed_runtime.try_shutdown().await.unwrap();
            drop(seed_runtime);

            let (_, persistence) = meerkat::open_realm_persistence_in(
                temp.path(),
                "no-turn-tests",
                Some(meerkat_store::RealmBackend::Sqlite),
                None,
            )
            .await
            .unwrap();
            let hook = Arc::new(PendingPromotionPreTurnHook {
                reached_flag: std::sync::atomic::AtomicBool::new(false),
                reached: Notify::new(),
                release: Notify::new(),
            });
            let config_store = Arc::new(BlockingBuildConfig {
                inner: meerkat_core::MemoryConfigStore::new(
                    Config::default(),
                    meerkat_models::canonical(),
                ),
                hook: Arc::clone(&hook),
                armed: std::sync::atomic::AtomicBool::new(false),
            });
            let runtime = Arc::new(
                SessionRuntime::new_with_config_store(
                    temp_factory(&temp),
                    Config::default(),
                    config_store.clone(),
                    1,
                    persistence,
                    crate::router::NotificationSink::noop(),
                )
                .expect("compose the RPC session runtime"),
            );
            runtime.ensure_schedule_host_started().await.unwrap();
            config_store.armed.store(true, AtomicOrdering::SeqCst);
            let cancelled_runtime = Arc::clone(&runtime);
            let cancelled_id = resume_id.clone();
            let task = tokio::spawn(async move {
                cancelled_runtime
                    .create_or_resume_session_without_turn(
                        mock_build_config(),
                        cancelled_id,
                        None,
                        Default::default(),
                    )
                    .await
            });
            // This barrier is in FactoryAgentBuilder::resolve_config, inside
            // the service's actor creation, not the outer promotion test hook.
            await_no_turn_hook(&hook).await;
            let id = runtime
                .runtime_registration_locks
                .lock()
                .unwrap()
                .keys()
                .next()
                .unwrap()
                .clone();
            let lock = runtime.runtime_registration_lock(&id);
            task.abort();
            assert!(task.await.unwrap_err().is_cancelled());
            hook.release.notify_one();
            let guard =
                tokio::time::timeout(std::time::Duration::from_secs(10), lock.mutex().lock())
                    .await
                    .expect("actor-build cancellation finishes exact rollback");
            assert!(!runtime.runtime_adapter.contains_session(&id).await);
            assert!(!runtime.service.has_live_session(&id).await.unwrap());
            assert!(!runtime.staged_sessions.contains(&id).await);
            #[cfg(feature = "mcp")]
            assert!(!runtime.mcp_sessions.read().await.contains_key(&id));
            match predecessor {
                Some(predecessor) => assert_eq!(
                    predecessor,
                    serde_json::to_value(
                        runtime.load_persisted_session(&id).await.unwrap().unwrap(),
                    )
                    .unwrap()
                ),
                None => assert!(
                    runtime
                        .list_sessions(Default::default())
                        .await
                        .unwrap()
                        .is_empty()
                ),
            }
            drop(guard);
            let retried = runtime
                .create_or_resume_session_without_turn(
                    mock_build_config(),
                    resume_id.clone(),
                    None,
                    Default::default(),
                )
                .await
                .expect("cancelled actor build releases capacity for retry");
            if let Some(resume_id) = resume_id {
                assert_eq!(retried, resume_id);
            }
            assert!(runtime.service.has_live_session(&retried).await.unwrap());
            runtime.try_shutdown().await.unwrap();
        }
    }

    /// Typed `session/event` notification params, as RPC clients read them.
    #[derive(serde::Deserialize)]
    struct SessionEventNotification {
        session_id: String,
        event: EventEnvelope<AgentEvent>,
    }

    /// Install a capturing notification sink on `runtime`. Runtime-routed
    /// turns publish their events only through the runtime's notification
    /// sink (`session/event`), which the executor reads at apply time, so the
    /// sink must be installed before the turn is admitted.
    fn capture_session_events(
        runtime: &SessionRuntime,
    ) -> mpsc::Receiver<crate::protocol::RpcNotification> {
        let (tx, rx) = mpsc::channel(1024);
        runtime.set_notification_sink(crate::router::NotificationSink::new(tx));
        rx
    }

    /// Read the runtime run id from the first `run_started` `session/event`
    /// notification of `session_id`, the value an RPC client passes to
    /// `turn/stop_run`.
    async fn run_started_run_id(
        notifications: &mut mpsc::Receiver<crate::protocol::RpcNotification>,
        session_id: &SessionId,
    ) -> meerkat_core::lifecycle::RunId {
        tokio::time::timeout(TEST_ASYNC_WITNESS_TIMEOUT, async {
            loop {
                let notification = notifications
                    .recv()
                    .await
                    .expect("notification sink stays open");
                if notification.method != "session/event" {
                    continue;
                }
                let params: SessionEventNotification =
                    serde_json::from_str(notification.params.get())
                        .expect("session/event params decode as a typed event envelope");
                if params.session_id != session_id.to_string() {
                    continue;
                }
                if let AgentEvent::RunStarted { identity, .. } = params.event.payload
                    && let Some(run_id) = identity.run_id
                {
                    return run_id;
                }
            }
        })
        .await
        .expect("run_started carries the runtime run id")
    }

    /// `turn/stop_run` end to end through `SessionRuntime`: a stale run id
    /// racing the live turn is `NotCurrent` and leaves the turn running; the
    /// exact run id stops it with a canonical receipt; a late stop of the
    /// same run is `NotCurrent` and harmless.
    #[tokio::test]
    async fn stop_run_stops_the_exact_runtime_turn_and_stale_or_late_stops_are_not_current() {
        let temp = tempfile::tempdir_in(".").unwrap();
        let runtime = make_runtime(temp_factory(&temp), 1);
        let (build, calls, _release) = blocking_build_config();
        let id = runtime
            .create_or_resume_session_without_turn(build, None, None, Default::default())
            .await
            .unwrap();
        // Subscribe before the turn starts: runtime-routed turn events reach
        // clients only as `session/event` notifications.
        let mut notifications = capture_session_events(&runtime);
        let turn_runtime = Arc::clone(&runtime);
        let turn_id = id.clone();
        let (event_tx, _event_rx) = mpsc::channel(100);
        let turn = tokio::spawn(async move {
            turn_runtime
                .start_turn_via_runtime(
                    &turn_id,
                    "stop me".into(),
                    Vec::new(),
                    event_tx,
                    None,
                    None,
                    None,
                    None,
                )
                .await
        });
        wait_for_llm_calls(&calls, 1, "provider in flight").await;
        let run_id = run_started_run_id(&mut notifications, &id).await;

        let stale = meerkat_core::lifecycle::RunId::new();
        match runtime
            .stop_run(&id, &stale, "stale selection".into())
            .await
            .expect("stale stop")
        {
            meerkat_runtime::RunStopReceipt::NotCurrent {
                run_id: reported,
                current_run_id,
            } => {
                assert_eq!(reported, stale);
                assert_eq!(current_run_id, Some(run_id.clone()));
            }
            other => panic!("a stale run id must be NotCurrent, got {other:?}"),
        }
        assert!(
            !turn.is_finished(),
            "a stale stop never interrupts the live run"
        );

        match runtime
            .stop_run(&id, &run_id, "user pressed stop".into())
            .await
            .expect("stop the live run")
        {
            meerkat_runtime::RunStopReceipt::Stopped {
                run_id: stopped,
                contributors,
            } => {
                assert_eq!(stopped, run_id);
                assert_eq!(contributors.len(), 1, "{contributors:?}");
                assert_eq!(
                    contributors[0].terminal,
                    Some(
                        meerkat_runtime::input_state::InputTerminalOutcome::Abandoned {
                            reason: meerkat_runtime::input_state::InputAbandonReason::Cancelled,
                        }
                    )
                );
            }
            other => panic!("the live run must be Stopped, got {other:?}"),
        }
        let turn_result = tokio::time::timeout(TEST_ASYNC_WITNESS_TIMEOUT, turn)
            .await
            .expect("stopped turn returns")
            .expect("turn task");
        assert!(turn_result.is_err(), "a stopped turn reports cancellation");

        match runtime
            .stop_run(&id, &run_id, "late".into())
            .await
            .expect("late stop")
        {
            meerkat_runtime::RunStopReceipt::NotCurrent {
                run_id: reported, ..
            } => {
                assert_eq!(reported, run_id);
            }
            other => panic!("a late stop must be NotCurrent, got {other:?}"),
        }
        assert_eq!(
            calls.load(AtomicOrdering::SeqCst),
            1,
            "no successor provider call"
        );
        runtime.try_shutdown().await.unwrap();
    }

