    #[tokio::test]
    async fn create_failure_combines_required_runtime_cleanup_failure_and_poison_blocks_retry() {
        let temp = tempfile::tempdir().expect("tempdir");
        let store: Arc<dyn meerkat::SessionStore> = Arc::new(meerkat::MemoryStore::new());
        let runtime_store = Arc::new(FailingLifecycleRuntimeStore::new());
        let runtime_store_dyn: Arc<dyn meerkat_runtime::RuntimeStore> = runtime_store.clone();
        let blob_store: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(meerkat_store::MemoryBlobStore::new());
        let runtime = Arc::new(
            SessionRuntime::new(
                temp_factory(&temp),
                Config::default(),
                1,
                meerkat::PersistenceBundle::new(store, runtime_store_dyn, blob_store)
                    .expect("construct runtime authority"),
                crate::router::NotificationSink::noop(),
            )
            .expect("compose the RPC session runtime"),
        );
        *runtime
            .create_session_after_prepare_bindings_error
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) =
            Some("synthetic post-prepare create failure".to_string());
        runtime_store.fail_lifecycle_commit_after(1);

        let failed = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .expect_err("create and its required cleanup should both fail");
        assert!(
            failed
                .message
                .contains("synthetic post-prepare create failure"),
            "combined error must retain the create failure: {failed:?}"
        );
        assert!(
            failed.message.ends_with("; required cleanup failed"),
            "combined error must retain the finite cleanup indication: {failed:?}"
        );
        assert!(
            !failed
                .message
                .contains("synthetic service-turn lifecycle commit failure"),
            "private unregister diagnostic must stay off the wire: {failed:?}"
        );
        let retry_session_id = runtime
            .create_session_after_prepare_bindings_session_id
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
            .expect("test hook should capture prepared session id");
        assert!(
            runtime
                .runtime_adapter
                .contains_session(&retry_session_id)
                .await,
            "failed unregister must retain the machine-owned retry anchor"
        );

        let retry = runtime
            .archive_runtime_cleanup()
            .run(&retry_session_id)
            .await
            .expect_err(
                "an ordinary lifecycle commit failure must block same-process cleanup retry",
            );
        assert!(
            retry
                .to_string()
                .contains("Runtime recovery is repair-blocked"),
            "retry must expose the poisoned lifecycle boundary: {retry}"
        );
        assert!(
            retry.to_string().contains("ordinary_lifecycle_commit"),
            "retry must retain the exact poisoned operation: {retry}"
        );
        assert!(
            runtime
                .runtime_adapter
                .contains_session(&retry_session_id)
                .await,
            "repair-blocked retry must retain the runtime entry for cold recovery"
        );
    }

