    #[tokio::test]
    async fn interrupt_on_cold_persisted_stopped_projection_is_noop_when_session_exists() {
        let temp = tempfile::tempdir().unwrap();
        let store: Arc<dyn meerkat::SessionStore> = Arc::new(meerkat::MemoryStore::new());
        let runtime_store: Arc<dyn meerkat_runtime::RuntimeStore> =
            Arc::new(meerkat_runtime::InMemoryRuntimeStore::new());
        let blob_store: Arc<dyn meerkat_core::BlobStore> =
            Arc::new(meerkat_store::MemoryBlobStore::new());
        let runtime = Arc::new(
            SessionRuntime::new(
                temp_factory(&temp),
                Config::default(),
                10,
                meerkat::PersistenceBundle::new(
                    Arc::clone(&store),
                    Arc::clone(&runtime_store),
                    Arc::clone(&blob_store),
                )
                .expect("construct runtime authority"),
                crate::router::NotificationSink::noop(),
            )
            .expect("compose the RPC session runtime"),
        );
        let build_config = mock_build_config();

        let created = runtime
            .service
            .create_session(CreateSessionRequest {
                injected_context: Vec::new(),
                model: build_config.model.clone(),
                prompt: "Hello".to_string().into(),
                system_prompt: build_config.system_prompt.clone(),
                max_tokens: build_config.max_tokens,
                event_tx: None,
                initial_turn: meerkat_core::service::InitialTurnPolicy::Defer,
                deferred_prompt_policy: DeferredPromptPolicy::Discard,
                build: Some(build_config.to_session_build_options()),
                labels: None,
            })
            .await
            .expect("service-owned idle session should be created");
        runtime
            .runtime_adapter
            .register_session(created.session_id.clone())
            .await
            .expect("register session");
        runtime
            .runtime_adapter
            .stop_runtime_executor(&created.session_id, "seed stopped projection")
            .await
            .expect("runtime state should persist");
        assert_eq!(
            runtime
                .service
                .persisted_runtime_state(&created.session_id)
                .await
                .expect("runtime-state projection load should succeed"),
            Some(meerkat_runtime::RuntimeState::Stopped)
        );

        // Rebuild the surface with fresh process-local runtime authority while
        // retaining both durable stores. Unregister would finalize Stopped to
        // Idle and would not represent a crash/restart boundary.
        drop(runtime);
        let runtime = Arc::new(
            SessionRuntime::new(
                temp_factory(&temp),
                Config::default(),
                10,
                meerkat::PersistenceBundle::new(store, runtime_store, blob_store)
                    .expect("construct runtime authority"),
                crate::router::NotificationSink::noop(),
            )
            .expect("compose the RPC session runtime"),
        );
        assert!(
            !runtime
                .runtime_adapter
                .contains_session(&created.session_id)
                .await,
            "cold RPC runtime must not inherit process-local registration"
        );

        runtime
            .interrupt(&created.session_id)
            .await
            .expect("persisted stopped projection must not reject cold interrupt no-op");
    }

    /// 7. Archiving a session removes it from the runtime.
    #[tokio::test]
    async fn archive_session_removes_handle() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);

        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();

        // Verify it exists
        assert!(runtime.session_state(&session_id).await.unwrap().is_some());

        // Archive it
        runtime.archive_session(&session_id).await.unwrap();

        // Verify it's gone
        assert!(
            runtime.session_state(&session_id).await.unwrap().is_none(),
            "Archived session should no longer exist"
        );

        // Archiving again should fail
        let result = runtime.archive_session(&session_id).await;
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().code, error::SESSION_NOT_FOUND);
    }

