    /// A direct create that resumes a durable session and is refused by its
    /// agent build rolls the registration it prepared back with the keep: a
    /// prompt an earlier process left queued in the session's durable
    /// runtime state, which the registration recovered, stays queued for the
    /// next start, not ended and with no requeue mark. RED before: the
    /// rollback stopped it.
    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn mob_session_service_refused_resume_keeps_a_recovered_prompt() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 2);
        let service = runtime.session_service();
        let session = Session::new();
        let session_id = session.id().clone();
        commit_runtime_session_authority(runtime.as_ref(), &session).await;
        let store = runtime.service.runtime_store();
        // An earlier process registered the session and accepted a prompt no
        // executor ran, so the store holds the prompt queued.
        let earlier = Arc::new(
            meerkat_runtime::MeerkatMachine::persistent_without_blobs(Arc::clone(&store))
                .expect("the earlier process's runtime"),
        );
        earlier
            .prepare_bindings(session_id.clone())
            .await
            .expect("the earlier process registers the session");
        let (accepted, _) = earlier
            .accept_input_with_completion(
                &session_id,
                meerkat_runtime::Input::Prompt(meerkat_runtime::PromptInput::new(
                    "queued when the process stopped",
                    None,
                )),
            )
            .await
            .expect("the registration holds the prompt");
        let meerkat_runtime::AcceptOutcome::Accepted {
            input_id: queued, ..
        } = accepted
        else {
            panic!("the registration accepts the prompt, got {accepted:?}");
        };
        let mut request = service_create_request(
            AgentBuildConfig {
                max_inline_peer_notifications: Some(-2),
                ..mock_build_config()
            },
            InitialTurnPolicy::Defer,
        );
        request
            .build
            .as_mut()
            .expect("direct create request build options")
            .resume_session = Some(session);

        let refused = service.create_session(request).await;
        assert!(
            refused.as_ref().err().is_some_and(|error| error
                .to_string()
                .contains("max_inline_peer_notifications=-2")),
            "the agent build refuses the resume: {refused:?}"
        );
        assert!(
            !runtime.runtime_adapter.contains_session(&session_id).await,
            "the refused resume rolls its registration back"
        );
        let row = store
            .load_input_state(
                &meerkat_runtime::LogicalRuntimeId::for_session(&session_id),
                &queued,
            )
            .await
            .expect("load the prompt's row")
            .expect("the prompt's row stays durable");
        assert_eq!(
            (row.seed.phase, &row.seed.terminal_outcome),
            (meerkat_runtime::InputLifecycleState::Queued, &None),
            "the recovered prompt stays queued for the next start: {:?}",
            row.state.history
        );
        assert!(
            row.state.stop_requeue.is_none(),
            "the prompt is kept as the store holds it, with no requeue mark"
        );
    }

    #[cfg(feature = "mob")]
    async fn insert_direct_archive_partial_destroy_mob(
        mob_state: &Arc<meerkat_mob_mcp::MobMcpState>,
        owner_session_id: &str,
    ) -> (
        meerkat_mob::MobId,
        Arc<meerkat_mob::store::InMemoryMobEventStore>,
    ) {
        let mob_id = meerkat_mob::MobId::from(format!(
            "direct-session-archive-partial-destroy-{}",
            uuid::Uuid::new_v4().simple()
        ));
        let mut definition = meerkat_mob::MobDefinition::explicit(mob_id.clone());
        definition.profiles.insert(
            meerkat_mob::ProfileName::from("worker"),
            meerkat_mob::ProfileBinding::Inline(Box::new(meerkat_mob::Profile {
                model_fallback: None,
                model: "claude-sonnet-4-5".to_string(),
                provider: None,
                self_hosted_server_id: None,
                image_generation_provider: None,
                auto_compact_threshold: None,
                resume_overrides: Vec::new(),
                skills: Vec::new(),
                tools: meerkat_mob::ToolConfig::default(),
                peer_description: "worker".to_string(),
                external_addressable: false,
                backend: None,
                runtime_mode: meerkat_mob::MobRuntimeMode::TurnDriven,
                max_inline_peer_notifications: None,
                output_schema: None,
                provider_params: None,
                durable: false,
            })),
        );
        let owner_session_id =
            SessionId::parse(owner_session_id).expect("valid owner bridge session id");
        let events = Arc::new(meerkat_mob::store::InMemoryMobEventStore::new());
        events.fail_clear_until_allowed();
        let storage = meerkat_mob::MobStorage::with_events(events.clone());
        let handle = meerkat_mob::MobBuilder::new(definition, storage)
            .with_owner_bridge_session_create_authority(owner_session_id, true, false)
            .with_session_service(mob_state.session_service())
            .allow_ephemeral_sessions(true)
            .create()
            .await
            .expect("create direct-archive-owned mob with failing event clear");
        mob_state.mob_insert_handle(mob_id.clone(), handle).await;
        (mob_id, events)
    }

    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn mob_session_service_archive_retry_preserves_not_found_after_retained_cleanup_completes()
     {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime_with_runtime_store(temp_factory(&temp), 10);
        let service = runtime.session_service();
        let mob_state = Arc::new(
            meerkat_mob_mcp::MobMcpState::new(
                service.clone(),
                meerkat_mob::MobControlPrincipal::Owner,
            )
            .expect("construct runtime authority"),
        );
        runtime.set_mob_state(mob_state.clone());
        let created = service
            .create_session(service_create_request(
                mock_build_config(),
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create direct session service session");
        let session_id = created.session_id;
        let (mob_id, events) =
            insert_direct_archive_partial_destroy_mob(&mob_state, &session_id.to_string()).await;

        let first = service
            .archive(&session_id)
            .await
            .expect_err("first direct archive should surface incomplete mob cleanup");
        assert!(
            matches!(first, SessionError::FailedWithData { .. }),
            "direct archive should return typed incomplete cleanup data: {first:?}"
        );
        let retry = service
            .archive(&session_id)
            .await
            .expect_err("retry should still report retained cleanup while fault persists");
        assert!(
            matches!(retry, SessionError::FailedWithData { .. }),
            "direct archive retry should not collapse to stale NotFound: {retry:?}"
        );

        events.allow_clear();
        let complete_retry = service
            .archive(&session_id)
            .await
            .expect_err("retry after retained mob cleanup completes should preserve NotFound");
        assert!(
            matches!(complete_retry, SessionError::NotFound { .. }),
            "direct archive retry should not turn cleanup into success: {complete_retry:?}"
        );
        assert!(
            mob_state.handle_for(&mob_id).await.is_err(),
            "post-NotFound direct archive cleanup must remove the retained mob cleanup anchor"
        );
    }

    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn mob_session_service_retained_metadata_matches_persistent_owner() {
        let temp = tempfile::tempdir().unwrap();
        let (runtime, runtime_store) =
            make_runtime_with_runtime_store_handle(temp_factory(&temp), 2);
        let wrapper = runtime.session_service();
        for archived in [false, true] {
            let mut session = Session::new();
            if archived {
                session
                    .set_lifecycle_terminal(meerkat_core::SessionLifecycleTerminal::Archived)
                    .unwrap();
            }
            runtime_store
                .commit_session_snapshot(
                    &meerkat_runtime::LogicalRuntimeId::for_session(session.id()),
                    meerkat_runtime::SerializedSessionSnapshot {
                        session_snapshot: serde_json::to_vec(&session).unwrap().into(),
                    },
                )
                .await
                .unwrap();
            let expected = meerkat_mob::MobSessionService::load_retained_session_metadata(
                runtime.service.as_ref(),
                session.id(),
            )
            .await
            .unwrap()
            .unwrap();
            let actual = meerkat_mob::MobSessionService::load_retained_session_metadata(
                wrapper.as_ref(),
                session.id(),
            )
            .await
            .unwrap()
            .unwrap();
            assert_eq!(actual.session_id, expected.session_id);
            assert_eq!(actual.lifecycle_terminal, expected.lifecycle_terminal);
            assert_eq!(
                serde_json::to_value(actual.session_metadata).unwrap(),
                serde_json::to_value(expected.session_metadata).unwrap()
            );
            if archived {
                assert!(
                    meerkat_mob::MobSessionService::load_persisted_session_metadata(
                        wrapper.as_ref(),
                        session.id(),
                    )
                    .await
                    .unwrap()
                    .is_none(),
                    "retained observation must not change ordinary archived visibility"
                );
            }

            let mut corrupt = serde_json::to_value(&session).unwrap();
            corrupt["metadata"][meerkat_core::session::SESSION_METADATA_KEY] =
                serde_json::json!("invalid-typed-session-metadata");
            runtime_store
                .commit_session_snapshot(
                    &meerkat_runtime::LogicalRuntimeId::for_session(session.id()),
                    meerkat_runtime::SerializedSessionSnapshot {
                        session_snapshot: serde_json::to_vec(&corrupt).unwrap().into(),
                    },
                )
                .await
                .unwrap();
            let expected_error = meerkat_mob::MobSessionService::load_retained_session_metadata(
                runtime.service.as_ref(),
                session.id(),
            )
            .await
            .unwrap_err();
            let actual_error = meerkat_mob::MobSessionService::load_retained_session_metadata(
                wrapper.as_ref(),
                session.id(),
            )
            .await
            .unwrap_err();
            assert_eq!(
                std::mem::discriminant(&actual_error),
                std::mem::discriminant(&expected_error)
            );
            assert_eq!(actual_error.to_string(), expected_error.to_string());
        }
        let absent = SessionId::new();
        for service in [
            runtime.service.as_ref() as &dyn meerkat_mob::MobSessionService,
            wrapper.as_ref(),
        ] {
            assert!(
                service
                    .load_retained_session_metadata(&absent)
                    .await
                    .unwrap()
                    .is_none()
            );
        }
    }

    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn mob_session_service_forwards_boundary_discard_to_exact_actor() {
        use futures::{FutureExt, StreamExt};
        use meerkat_core::event::BoundaryAppendsDiscarded;

        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 2);
        let service = runtime.session_service();
        let created = service
            .create_session(service_create_request(
                mock_build_config(),
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create RPC mob actor");
        let session_id = created.session_id;
        let witness = runtime
            .mob_actor_witness(&session_id)
            .expect("capture exact RPC mob actor");
        let mut events =
            meerkat_mob::MobSessionService::subscribe_session_events(service.as_ref(), &session_id)
                .await
                .unwrap();
        let discarded = BoundaryAppendsDiscarded {
            session_id: session_id.clone(),
            run_id: meerkat_core::lifecycle::RunId::new(),
            input_ids: vec![meerkat_core::lifecycle::InputId::new()],
        };
        service
            .publish_boundary_appends_discarded_for_actor(&witness, &discarded)
            .await
            .expect("wrapper must reach the persistent publication owner");
        let published = tokio::time::timeout(std::time::Duration::from_secs(2), events.next())
            .await
            .unwrap()
            .unwrap();
        assert_eq!(published.source_session_id(), Some(&session_id));
        assert!(matches!(published.payload,
            AgentEvent::BoundaryAppendsDiscarded(value) if value == discarded));

        let registry = meerkat_session::LiveSessionActorRegistry::default();
        let other = registry
            .insert_and_publish(
                &meerkat::LiveSessionActorWitnessSlot::default(),
                session_id.clone(),
                meerkat_core::TransientTurnContextStateHandle::new(),
            )
            .unwrap();
        assert!(matches!(
            service.publish_boundary_appends_discarded_for_actor(&other, &discarded).await,
            Err(SessionError::NotFound { id }) if id == session_id
        ));
        let mut mismatch = discarded;
        mismatch.session_id = SessionId::new();
        assert!(matches!(
            service
                .publish_boundary_appends_discarded_for_actor(&witness, &mismatch)
                .await,
            Err(SessionError::Agent(_))
        ));
        assert!(events.next().now_or_never().is_none());
    }

