    /// RPC-hosted mob members settle a cold predecessor through the
    /// persistent owner: the settlement's own checks answer (a claim of
    /// another session refused `ClaimNotOwned`, nothing touched), not the
    /// trait default's `Unsupported`.
    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn mob_session_service_forwards_the_cold_predecessor_settlement_to_persistent_owner() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);
        let service = runtime.session_service();
        let settled = SessionId::new();
        let other_session_claim = runtime
            .service
            .grant_session_hosting(&SessionId::new())
            .expect("a hosting claim of another session");

        let refused =
            meerkat_mob::MobSessionService::settle_cold_predecessor_with_mob_lifecycle_authority_before(
                service.as_ref(),
                &settled,
                &other_session_claim,
                meerkat_core::time_compat::Instant::now() + std::time::Duration::from_secs(10),
            )
            .await
            .expect_err("a claim of another session settles nothing");
        assert!(
            matches!(
                refused.refusal,
                meerkat::ColdPredecessorSettleRefusal::Settlement(
                    meerkat_runtime::PredecessorSettlementRefusal::ClaimNotOwned
                )
            ),
            "RPC-hosted mob members must reach the persistent owner instead of the Unsupported default: {refused:?}"
        );
    }

    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn mob_session_service_cancelled_deferred_create_after_ack_discards_admission() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 1);
        let hook = Arc::new(PendingPromotionPreTurnHook::default());
        let service = Arc::new(
            RpcMobSessionService::new(
                Arc::clone(&runtime.service),
                Arc::clone(&runtime.staged_sessions),
                Arc::clone(&runtime.runtime_adapter),
                Arc::clone(&runtime.mob_state),
                Arc::clone(&runtime.mob_actor_witnesses),
                Arc::clone(&runtime.runtime_actor_witness_slots),
                Arc::clone(&runtime.runtime_publication_handles),
                Arc::clone(&runtime.runtime_registration_fence),
            )
            .with_direct_create_after_ack_hook(Arc::clone(&hook)),
        );
        let session = Session::new();
        let session_id = session.id().clone();
        let mut request = service_create_request(mock_build_config(), InitialTurnPolicy::Defer);
        request
            .build
            .as_mut()
            .expect("direct create request build options")
            .resume_session = Some(session);
        let task_service = Arc::clone(&service);
        let create_task = tokio::spawn(async move { task_service.create_session(request).await });

        wait_hook_reached(&hook).await;
        create_task.abort();
        hook.release.notify_waiters();
        let _ = create_task.await;

        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                let runtime_registration_exists =
                    runtime.runtime_adapter.contains_session(&session_id).await;
                let live_actor_exists = runtime
                    .service
                    .has_live_session(&session_id)
                    .await
                    .expect("query cancelled direct create");
                if !runtime_registration_exists && !live_actor_exists {
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("cancelled direct create should discard actor and exact runtime registration");

        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                if runtime
                    .create_session(mock_build_config(), None, None, Vec::new())
                    .await
                    .is_ok()
                {
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("cancelled direct deferred create should release admission");
    }

