    /// Spawn the turn-driven `worker-1` member on `mob_id`, answering its
    /// identity and session.
    #[cfg(feature = "mob")]
    async fn spawn_rpc_worker(
        mob_state: &meerkat_mob_mcp::MobMcpState,
        mob_id: &meerkat_mob::MobId,
    ) -> (meerkat_mob::AgentIdentity, SessionId) {
        let identity = meerkat_mob::AgentIdentity::from("worker-1");
        mob_state
            .mob_spawn_spec(
                mob_id,
                meerkat_mob::SpawnMemberSpec::new("worker", identity.clone()),
            )
            .await
            .expect("spawn the worker");
        let session_id = mob_state
            .mob_resolve_bridge_session_id(mob_id, &identity)
            .await
            .expect("resolve the worker's session")
            .expect("the spawned worker has a session");
        (identity, session_id)
    }

    /// A mob member whose runtime a refused run-boundary commit left
    /// repair-blocked retires on the RPC host. Retirement disposes the
    /// degraded shell, cold-registers the member's durable authority, moves
    /// its member operation onto that registration, and archives through the
    /// RPC mob session service. The member leaves the roster, and its runtime
    /// is unregistered and durably Retired.
    #[cfg(feature = "mob")]
    #[tokio::test(flavor = "multi_thread")]
    async fn a_repair_blocked_mob_member_retires_on_the_rpc_host() {
        let temp = tempfile::tempdir().expect("tempdir");
        let (runtime, runtime_store) =
            make_runtime_with_failing_runtime_store(temp_factory(&temp), 10);
        let mob_state = rpc_mob_state_with_realm(&runtime);
        runtime.set_mob_state(Arc::clone(&mob_state));
        let mob_id = rpc_worker_mob(&mob_state, "rpc-mob-repair-blocked-retire").await;
        let (identity, session_id) = spawn_rpc_worker(&mob_state, &mob_id).await;
        let runtime_id = meerkat_runtime::LogicalRuntimeId::for_session(&session_id);

        // The store refuses the worker's next run boundary, as a failed
        // write would: the runtime is left repair-blocked.
        runtime_store.fail_next_run_boundary_of(runtime_id.clone());
        mob_state
            .mob_member_send(
                &mob_id,
                identity.clone(),
                "the turn whose boundary the store refuses".into(),
                meerkat_core::types::HandlingMode::Queue,
                None,
            )
            .await
            .expect("the worker admits the turn");
        tokio::time::timeout(
            Duration::from_secs(30),
            runtime_store.run_boundary_refused.notified(),
        )
        .await
        .expect("the store refuses the worker's run boundary");
        tokio::time::timeout(Duration::from_secs(30), async {
            while runtime
                .runtime_adapter
                .session_has_live_executor_attachment(&session_id)
                .await
            {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("the refused boundary's runtime loop exits");
        // Repair-blocked: the degraded shell, or the cold registration a
        // reload already put in its place, with no runtime owner.
        let degraded = runtime
            .runtime_adapter
            .durability_reload_required(&session_id)
            .await
            .is_some();
        let cold = match runtime
            .runtime_adapter
            .current_session_registration_witness(&session_id)
            .await
        {
            Some(registration) => {
                runtime
                    .runtime_adapter
                    .registration_is_current_without_runtime_owner(&registration)
                    .await
            }
            None => false,
        };
        assert!(
            degraded || cold,
            "the refused commit leaves the worker's runtime repair-blocked"
        );

        let retired = tokio::time::timeout(Duration::from_secs(30), async {
            loop {
                match mob_state.mob_retire(&mob_id, identity.clone()).await {
                    Err(meerkat_mob::MobError::MemberRetirementInProgress { .. }) => {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                    settled => return settled,
                }
            }
        })
        .await
        .expect("retiring the repair-blocked worker settles");
        if let Err(error) = retired {
            let mut redrives = Vec::new();
            for _ in 0..2 {
                redrives.push(
                    mob_state
                        .mob_retire(&mob_id, identity.clone())
                        .await
                        .err()
                        .map(|error| error.to_string()),
                );
            }
            panic!(
                "the repair-blocked worker retires (degraded {degraded}, cold {cold}): {error}; \
                 redrives: {redrives:?}"
            );
        }

        assert!(
            mob_state
                .mob_list_members(&mob_id)
                .await
                .expect("list the members")
                .iter()
                .all(|entry| entry.agent_identity != identity),
            "the retired worker leaves the roster"
        );
        assert!(
            !runtime.runtime_adapter.contains_session(&session_id).await,
            "retirement unregisters the worker's runtime"
        );
        assert_eq!(
            meerkat_runtime::store::load_runtime_state(runtime_store.as_ref(), &runtime_id)
                .await
                .expect("read the worker's durable runtime state"),
            Some(meerkat_runtime::RuntimeState::Retired),
            "the worker's runtime is durably Retired"
        );
    }

    /// The RPC mob session service answers what the persistent service it
    /// wraps answers wherever the trait default refuses or reports nothing:
    /// the persisted authority read cost and observation, live actor
    /// presence, the live visible tool definitions, metadata, the controller
    /// route and pin of an exact live actor, instruction activation and, with
    /// `openai-live`, the live bridge member preflight. The hook-bearing
    /// archive and run suspension have scenario rows of their own.
    #[cfg(feature = "mob")]
    #[tokio::test]
    async fn rpc_mob_session_service_answers_what_its_persistent_service_answers() {
        use meerkat_mob::MobSessionService as _;

        let temp = tempfile::tempdir().expect("tempdir");
        let runtime = make_runtime_with_runtime_store(temp_factory(&temp), 2);
        runtime.set_default_llm_client(Some(Arc::new(MockLlmClient)));
        let wrapper = runtime.session_service();
        let inner = runtime.service.as_ref();
        let session_id = wrapper
            .create_session(service_create_request(
                mock_build_config(),
                InitialTurnPolicy::Defer,
            ))
            .await
            .expect("create a mob actor")
            .session_id;
        let actor = runtime
            .mob_actor_witness(&session_id)
            .expect("capture the mob actor");

        let cost =
            meerkat_mob::MobSessionService::persisted_session_authority_read_cost(wrapper.as_ref());
        assert_eq!(
            cost,
            meerkat_mob::runtime::PersistedSessionAuthorityReadCost::Bounded,
            "every runtime store reads its persisted authority at a bounded cost"
        );
        assert_eq!(
            cost,
            meerkat_mob::MobSessionService::persisted_session_authority_read_cost(inner)
        );
        assert_eq!(
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::observe_persisted_session_authority(
                    wrapper.as_ref(),
                    &session_id
                )
                .await
            ),
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::observe_persisted_session_authority(
                    inner,
                    &session_id
                )
                .await
            ),
            "persisted authority"
        );
        assert_eq!(
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::live_session_actor_registered(
                    wrapper.as_ref(),
                    &session_id
                )
                .await
            ),
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::live_session_actor_registered(inner, &session_id)
                    .await
            ),
            "live actor presence"
        );
        let tool_names = |defs: Option<Vec<meerkat_core::ToolDef>>| {
            defs.map(|defs| {
                defs.into_iter()
                    .map(|def| def.name.to_string())
                    .collect::<Vec<_>>()
            })
        };
        let visible = tool_names(
            meerkat_mob::MobSessionService::live_visible_tool_defs(wrapper.as_ref(), &session_id)
                .await
                .expect("read the visible tools through the wrapper"),
        );
        assert!(visible.is_some(), "the wrapper reports the visible tools");
        assert_eq!(
            visible,
            tool_names(
                meerkat_mob::MobSessionService::live_visible_tool_defs(inner, &session_id)
                    .await
                    .expect("read the visible tools")
            )
        );
        assert_eq!(
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::load_persisted_session_metadata(
                    wrapper.as_ref(),
                    &session_id
                )
                .await
                .map(|view| view.map(|view| view.session_id))
            ),
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::load_persisted_session_metadata(inner, &session_id)
                    .await
                    .map(|view| view.map(|view| view.session_id))
            ),
            "metadata"
        );
        let route = meerkat_mob::MobSessionService::controller_route_under_runtime_turn_boundary(
            wrapper.as_ref(),
            &actor,
        )
        .await;
        assert!(
            !matches!(
                route,
                Ok(meerkat_mob::ControllerRouteObservation::Unsupported)
            ),
            "the wrapper reports the controller route: {route:?}"
        );
        assert_eq!(
            format!("{route:?}"),
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::controller_route_under_runtime_turn_boundary(
                    inner, &actor,
                )
                .await
            ),
            "controller route"
        );
        match (
            meerkat_mob::MobSessionService::pin_controller_client_under_runtime_turn_boundary(
                wrapper.as_ref(),
                &actor,
            )
            .await,
            meerkat_mob::MobSessionService::pin_controller_client_under_runtime_turn_boundary(
                inner, &actor,
            )
            .await,
        ) {
            (Ok(pinned), Ok(expected)) => assert_eq!(pinned.selection(), expected.selection()),
            (Err(refused), Err(expected)) => {
                assert_eq!(refused.to_string(), expected.to_string());
            }
            (Ok(_), Err(expected)) => panic!("only the persistent service refused: {expected}"),
            (Err(refused), Ok(_)) => panic!("only the wrapper refused the pin: {refused}"),
        }
        let body = "a standing instruction";
        let request = meerkat_core::InstructionActivationRequest {
            revision: meerkat_core::InstructionRevisionRef {
                namespace: meerkat_core::InstructionNamespace::new("host.standing")
                    .expect("namespace"),
                key: meerkat_core::InstructionKey::new("member").expect("key"),
                revision_id: meerkat_core::InstructionRevisionId::new("rev-1").expect("revision"),
                content_sha256: meerkat_core::InstructionContentDigest::for_body(body),
            },
            activation_id: meerkat_core::InstructionActivationId::new("activation-1")
                .expect("activation id"),
            expectation: meerkat_core::InstructionActivationExpectation::Absent,
            supersedes: None,
            body: body.to_string(),
        };
        let activated =
            meerkat_mob::MobSessionService::activate_instruction_under_runtime_turn_boundary(
                wrapper.as_ref(),
                &session_id,
                request,
                None,
            )
            .await;
        assert!(
            activated.is_ok(),
            "the wrapper activates the instruction: {activated:?}"
        );
        #[cfg(feature = "openai-live")]
        assert_eq!(
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::validate_live_bridge_member_eligibility(
                    wrapper.as_ref(),
                    &session_id
                )
                .await
            ),
            format!(
                "{:?}",
                meerkat_mob::MobSessionService::validate_live_bridge_member_eligibility(
                    inner,
                    &session_id
                )
                .await
            ),
            "live bridge member preflight"
        );
    }

    /// rkat-rpc's graceful shutdown keeps a running mob member's run for the
    /// next start, as it keeps a plain session's: the stop suspends the
    /// member's run instead of cancelling it, so the run's input stays live
    /// in the store, and a runtime started again on the same stores runs the
    /// kept run once when the member's session is opened again, ahead of the
    /// new turn.
    #[cfg(feature = "mob")]
    #[tokio::test(flavor = "multi_thread")]
    async fn a_graceful_shutdown_keeps_a_running_mob_members_run_for_the_next_start() {
        let realm = GracefulShutdownRealm::new(GracefulShutdownStores::InMemoryWholeBlob);
        let runtime = realm.start().await;
        let mob_state = rpc_mob_state_with_realm(&runtime);
        runtime.set_mob_state(Arc::clone(&mob_state));
        let calls = Arc::new(BlockingLlmCallWitness::default());
        runtime.set_default_llm_client(Some(Arc::new(BlockingMockLlmClient {
            calls: Arc::clone(&calls),
            release: Arc::new(Notify::new()),
        })));
        let mob_id = rpc_worker_mob(&mob_state, "rpc-mob-graceful-requeue").await;
        let (identity, session_id) = spawn_rpc_worker(&mob_state, &mob_id).await;
        let runtime_id = meerkat_runtime::LogicalRuntimeId::for_session(&session_id);
        mob_state
            .mob_member_send(
                &mob_id,
                identity,
                "the member's running turn".into(),
                meerkat_core::types::HandlingMode::Queue,
                None,
            )
            .await
            .expect("the worker admits the turn");
        wait_for_llm_calls(&calls, 1, "the member's running turn").await;
        let running = runtime
            .runtime_adapter
            .list_active_inputs(&session_id)
            .await
            .expect("list the member's active inputs");
        assert_eq!(running.len(), 1, "one input runs: {running:?}");

        runtime
            .try_shutdown()
            .await
            .expect("the runtime shuts down");
        let kept = realm
            .runtime_store
            .load_input_state(&runtime_id, &running[0])
            .await
            .expect("read the member's input")
            .expect("the member's input is stored");
        assert!(
            !matches!(
                kept.seed.phase,
                meerkat_runtime::input_state::InputLifecycleState::Abandoned
                    | meerkat_runtime::input_state::InputLifecycleState::Consumed
            ),
            "the stop suspends the member's run and keeps its input, never ends it: {:?}",
            kept.seed.phase
        );
        drop(mob_state);
        drop(runtime);

        let restarted = realm.start().await;
        restarted.set_default_llm_client(Some(Arc::new(MockLlmClient)));
        runtime_turn(&restarted, &session_id, "after the restart").await;
        let session = restarted
            .load_persisted_session(&session_id)
            .await
            .expect("load the member's session")
            .expect("the member's session is persisted");
        let users: Vec<String> = user_channel_messages(&session)
            .into_iter()
            .filter(|(injected, _)| !injected)
            .map(|(_, text)| text)
            .collect();
        assert_eq!(
            users
                .iter()
                .filter(|text| text.contains("the member's running turn"))
                .count(),
            1,
            "the kept run runs once at the next start: {users:?}"
        );
        assert_eq!(
            users.last().map(String::as_str),
            Some("after the restart"),
            "the kept run runs ahead of the new turn: {users:?}"
        );
        restarted
            .try_shutdown()
            .await
            .expect("the restarted runtime shuts down");
    }

    /// A member identity that converged on the RPC host keeps reconciling.
    /// Once converged, a pass of the unchanged intent checks the cached
    /// session witness against the store's persisted authority. The RPC mob
    /// session service answers that read as the persistent service does, so
    /// the pass converges again and records it. A pass that cannot read it
    /// fails before it observes anything, records nothing and backs off, so
    /// the identity reconciliation would no longer act on the member.
    #[cfg(feature = "mob")]
    #[tokio::test(flavor = "multi_thread")]
    async fn a_converged_member_identity_keeps_reconciling_on_the_rpc_host() {
        use meerkat_mob::identity::{
            AdoptMemberIdentityDeclaration, DesiredExecution, DesiredSessionAuthorityPolicy,
            DesiredSessionTarget, IdentityAdoptionId, IdentityAdoptionOutcome,
            IdentityAdoptionPrecondition, IdentityConvergenceMode, IdentityConvergenceStatus,
            IdentityDeclarationScopeId, IdentityProfileMemberDeclaration,
            IdentityReconcileDecision, IdentityStoredObservation, IdentityWiringCustody,
        };

        let temp = tempfile::tempdir().expect("tempdir");
        let runtime = make_runtime_with_runtime_store(temp_factory(&temp), 10);
        let mob_state = rpc_mob_state_with_realm(&runtime);
        runtime.set_mob_state(Arc::clone(&mob_state));
        let mob_id = rpc_worker_mob(&mob_state, "rpc-mob-identity-reconcile").await;
        let (identity, session_id) = spawn_rpc_worker(&mob_state, &mob_id).await;
        let adoption = AdoptMemberIdentityDeclaration {
            mob_id: mob_id.clone(),
            agent_identity: identity.clone(),
            request_id: IdentityAdoptionId::new("adopt-worker-1").expect("adoption id"),
            precondition: IdentityAdoptionPrecondition::ExpectedAbsent,
            declaration_scope: IdentityDeclarationScopeId::new("rpc-identity-reconcile")
                .expect("declaration scope"),
            declaration_revision: 1,
            session: DesiredSessionTarget {
                session_id: session_id.clone(),
                lineage_id: meerkat_core::SessionLineageId::for_session(&session_id),
                lineage_generation: meerkat_core::SessionGeneration::INITIAL,
                authority_policy: DesiredSessionAuthorityPolicy::RequireExisting,
            },
            member: IdentityProfileMemberDeclaration {
                profile_name: meerkat_mob::ProfileName::from("worker"),
                profile_override: None,
                model_override: None,
                external_addressable_override: None,
                context: None,
                labels: None,
                additional_instructions: None,
                system_prompt_override: None,
                tool_access_policy: None,
                auth_binding: None,
                budget_limits: None,
                runtime_mode: Some(meerkat_contracts::wire::WireMobRuntimeMode::TurnDriven),
                required_env_keys: Vec::new(),
                required_local_callback_tools: Vec::new(),
                execution: DesiredExecution::ControllingSession,
            },
            wiring_custody: IdentityWiringCustody::ExternalManaged,
            owned_wiring: std::collections::BTreeSet::new(),
            convergence: IdentityConvergenceMode::Drain { max_wait_ms: 5_000 },
        };
        let adopted = mob_state
            .mob_adopt_member_identity_declaration(&mob_id, adoption.clone())
            .await
            .expect("adopt the worker's identity");
        assert!(
            matches!(
                adopted.adoption,
                IdentityAdoptionOutcome::Adopted {
                    desired_revision: 1
                }
            ),
            "{:?}",
            adopted.adoption
        );
        // The time of the latest converged status, once one is newer than
        // `after`.
        let converged_after = |after: u64| {
            let mob_state = Arc::clone(&mob_state);
            let mob_id = mob_id.clone();
            let identity = identity.clone();
            async move {
                tokio::time::timeout(Duration::from_secs(30), async {
                    loop {
                        if let IdentityStoredObservation::Valid(IdentityConvergenceStatus {
                            decision: Some(IdentityReconcileDecision::Converged),
                            observed_at_ms,
                            ..
                        }) = mob_state
                            .mob_identity_convergence_status(&mob_id, &identity)
                            .await
                            .expect("read the identity's convergence")
                            && observed_at_ms > after
                        {
                            break observed_at_ms;
                        }
                        tokio::time::sleep(Duration::from_millis(10)).await;
                    }
                })
                .await
            }
        };
        let converged_at = converged_after(0)
            .await
            .expect("the adopted identity converges");

        // The adoption's replay wakes a pass of the unchanged intent.
        tokio::time::sleep(Duration::from_millis(5)).await;
        mob_state
            .mob_adopt_member_identity_declaration(&mob_id, adoption)
            .await
            .expect("replay the adoption");
        let again = converged_after(converged_at).await;
        assert!(
            again.is_ok(),
            "a pass after convergence converges again; status: {:?}",
            mob_state
                .mob_identity_convergence_status(&mob_id, &identity)
                .await
        );
    }

    /// A login lifts a sign-out's suppression only for the exact attachment
    /// it suppressed: equal unbound identities (withheld parts, no key) prove
    /// nothing, another account is not the same attachment, and an exact,
    /// unchanged one is.
    #[cfg(feature = "mcp")]
    #[test]
    fn login_reinstates_only_an_exactly_proven_suppressed_attachment() {
        use meerkat_core::McpAttachmentDescriptorIdentity as Identity;
        let stdio = |args: &[&str]| {
            McpServerConfig::stdio(
                "guarded",
                "server",
                args.iter().map(|arg| (*arg).to_owned()).collect(),
                HashMap::new(),
            )
        };
        // Recorded without a key: the arguments are withheld and unbound, so
        // another installation that differs only there compares equal.
        let unbound = Identity::of(&stdio(&["--token=a"]), None);
        assert!(!unbound.target.is_exact());
        assert!(
            !SessionRuntime::login_proves_suppressed_attachment(
                &unbound,
                &stdio(&["--token=b"]),
                None
            ),
            "an unbound record is not proven by an equal unbound identity"
        );

        let exact = Identity::of(&stdio(&[]), None);
        assert!(
            SessionRuntime::login_proves_suppressed_attachment(&exact, &stdio(&[]), None),
            "the exact, unchanged attachment is reinstated"
        );

        let http = |account: &str| {
            let mut config = McpServerConfig::streamable_http(
                "guarded",
                "https://mcp.example.test/mcp",
                HashMap::new(),
            );
            if let meerkat_core::mcp_config::McpTransportConfig::Http(http) = &mut config.transport
            {
                http.oauth_account = Some(account.to_owned());
            }
            config
        };
        let account_a = Identity::of(&http("account-a"), None);
        assert!(account_a.target.is_exact());
        assert!(
            !SessionRuntime::login_proves_suppressed_attachment(
                &account_a,
                &http("account-b"),
                None
            ),
            "another account's installation does not lift the suppression"
        );
        assert!(SessionRuntime::login_proves_suppressed_attachment(
            &account_a,
            &http("account-a"),
            None
        ));
    }

    /// A removal whose caller leaves after its durable withdrawal was entered
    /// still settles under the session's intent order: a restore attempted
    /// meanwhile waits for it, then finds the request withdrawn and neither
    /// stages nor reports anything, and the staged add is withdrawn (the next
    /// boundary connects nothing).
    #[cfg(feature = "mcp")]
    #[tokio::test]
    async fn cancelled_mcp_remove_settles_before_a_waiting_restore() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();
        let (event_tx, _event_rx) = mpsc::channel(32);
        runtime
            .start_turn(
                &session_id,
                "hello".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("the first turn materializes the session");
        runtime
            .mcp_stage_add(
                &session_id,
                McpServerConfig::stdio("restored", "echo", Vec::new(), HashMap::new()),
            )
            .await
            .expect("stage add");
        let requested = runtime
            .durable_mcp_attachment_intents(&session_id)
            .await
            .expect("read the durable intents");
        assert_eq!(requested.len(), 1, "the add is durable: {requested:?}");

        let hook = Arc::new(PendingPromotionPreTurnHook::default());
        *runtime
            .mcp_intent_settlement_hook
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));
        let remover = Arc::clone(&runtime);
        let removed_session = session_id.clone();
        let remove = tokio::spawn(async move {
            remover
                .mcp_stage_remove(&removed_session, "restored".to_string())
                .await
        });
        // The withdrawal is recorded; its live removal waits on the hook.
        wait_hook_reached(&hook).await;
        remove.abort();
        let _ = remove.await;

        let adapter = runtime
            .mcp_adapter_for_session(&session_id)
            .await
            .expect("the session's adapter");
        let (lifecycle_tx, mut lifecycle_rx) = mpsc::unbounded_channel();
        let contended = runtime.mcp_intent_order_contended.notified();
        let restorer = Arc::clone(&runtime);
        let restored_session = session_id.clone();
        let restore = tokio::spawn(async move {
            restorer
                .restore_mcp_attachments(
                    &restored_session,
                    &adapter,
                    &lifecycle_tx,
                    &requested,
                    HashMap::new(),
                    Vec::new(),
                    None,
                )
                .await;
        });
        tokio::time::timeout(Duration::from_secs(5), contended)
            .await
            .expect("the restore reaches the order the entered removal holds");
        assert!(
            !restore.is_finished(),
            "the restore waits for the entered removal to settle"
        );
        hook.release.notify_waiters();
        tokio::time::timeout(Duration::from_secs(5), restore)
            .await
            .expect("the restore runs once the removal settled")
            .expect("the restore task completes");

        let after = runtime
            .durable_mcp_attachment_intents(&session_id)
            .await
            .expect("read the durable intents");
        assert!(
            after
                .iter()
                .all(|intent| intent.descriptor.server_name != "restored"),
            "the cancelled removal still withdrew the request: {after:?}"
        );
        assert!(
            lifecycle_rx.try_recv().is_err(),
            "the withdrawn request is neither restored nor reported"
        );
        assert_eq!(
            runtime
                .mcp_apply_staged_for_test(&session_id)
                .await
                .expect("apply the staged operations"),
            0,
            "the settled removal withdrew the staged add: nothing connects"
        );
    }

    /// A session with one parked governed restore entry (`restored`), whose
    /// current installation the restore does not find: settling the batch
    /// reports it once on the session's lifecycle stream.
    #[cfg(feature = "mcp")]
    async fn pending_restore_fixture(temp: &tempfile::TempDir) -> (Arc<SessionRuntime>, SessionId) {
        let runtime = make_runtime(temp_factory(temp), 10);
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();
        let (event_tx, _event_rx) = mpsc::channel(32);
        runtime
            .start_turn(
                &session_id,
                "hello".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("the first turn materializes the session");
        runtime
            .mcp_stage_add(
                &session_id,
                McpServerConfig::stdio("restored", "echo", Vec::new(), HashMap::new()),
            )
            .await
            .expect("stage add");
        let requested = runtime
            .durable_mcp_attachment_intents(&session_id)
            .await
            .expect("read the durable intents");
        assert_eq!(requested.len(), 1, "the add is durable: {requested:?}");
        runtime
            .mcp_sessions
            .write()
            .await
            .get_mut(&session_id)
            .expect("the session's MCP state")
            .pending_restore = requested;
        (runtime, session_id)
    }

    #[cfg(feature = "mcp")]
    fn spawn_pending_restore(
        runtime: &Arc<SessionRuntime>,
        session_id: &SessionId,
    ) -> tokio::task::JoinHandle<()> {
        let runtime = Arc::clone(runtime);
        let session_id = session_id.clone();
        tokio::spawn(async move {
            runtime
                .restore_pending_mcp_attachments(&session_id, Some(Vec::new()), |_server| async {
                    Err(meerkat_core::mcp_attachment::McpAttachmentRefusal::Unavailable)
                })
                .await;
        })
    }

    /// The restore outcomes queued on `session_id`'s lifecycle stream.
    #[cfg(feature = "mcp")]
    async fn queued_mcp_lifecycle_actions(
        runtime: &SessionRuntime,
        session_id: &SessionId,
    ) -> usize {
        let mut sessions = runtime.mcp_sessions.write().await;
        let state = sessions
            .get_mut(session_id)
            .expect("the session's MCP state");
        let mut queued = 0;
        while state.lifecycle_rx.try_recv().is_ok() {
            queued += 1;
        }
        queued
    }

    /// A governed restore holds the session's intent order from taking its
    /// batch until the batch is staged: a concurrent request's restore waits
    /// on the order instead of finding the queue emptied and proceeding as
    /// if restored, and the batch settles once.
    #[cfg(feature = "mcp")]
    #[tokio::test]
    async fn a_concurrent_governed_restore_waits_for_the_batch_taken_first() {
        let temp = tempfile::tempdir().unwrap();
        let (runtime, session_id) = pending_restore_fixture(&temp).await;
        let hook = Arc::new(PendingPromotionPreTurnHook::default());
        *runtime
            .mcp_restore_batch_hook
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));
        let first = spawn_pending_restore(&runtime, &session_id);
        // The first restore took the real batch and holds there.
        wait_hook_reached(&hook).await;
        let contended = runtime.mcp_intent_order_contended.notified();
        let second = spawn_pending_restore(&runtime, &session_id);
        tokio::time::timeout(Duration::from_secs(5), contended)
            .await
            .expect("the second restore reaches the order the first holds");
        assert!(
            !second.is_finished(),
            "the second restore waits until the first one's batch settles"
        );
        hook.release.notify_waiters();
        tokio::time::timeout(Duration::from_secs(5), first)
            .await
            .expect("the first restore settles")
            .expect("the first restore task completes");
        tokio::time::timeout(Duration::from_secs(5), second)
            .await
            .expect("the second restore runs once the first settled")
            .expect("the second restore task completes");
        assert_eq!(
            queued_mcp_lifecycle_actions(&runtime, &session_id).await,
            1,
            "the batch settles once"
        );
    }

    /// A governed restore whose caller stops waiting right after it took
    /// the batch still settles it: the outcome is queued for the session's
    /// next boundary, and the queue is not left with a lost batch.
    #[cfg(feature = "mcp")]
    #[tokio::test]
    async fn a_governed_restore_settles_its_batch_after_its_waiter_left() {
        let temp = tempfile::tempdir().unwrap();
        let (runtime, session_id) = pending_restore_fixture(&temp).await;
        let hook = Arc::new(PendingPromotionPreTurnHook::default());
        *runtime
            .mcp_restore_batch_hook
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));
        let waiter = spawn_pending_restore(&runtime, &session_id);
        wait_hook_reached(&hook).await;
        waiter.abort();
        let _ = waiter.await;
        hook.release.notify_waiters();
        let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
        let mut queued = 0;
        while queued == 0 {
            assert!(
                tokio::time::Instant::now() < deadline,
                "the abandoned restore settles its batch"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
            queued = queued_mcp_lifecycle_actions(&runtime, &session_id).await;
        }
        assert_eq!(queued, 1, "the batch settles once");
        assert!(
            runtime
                .mcp_sessions
                .read()
                .await
                .get(&session_id)
                .is_some_and(|state| state.pending_restore.is_empty()),
            "the settled batch is not parked again"
        );
    }

    /// A suppressed-login reinstatement whose caller leaves after the durable
    /// Reinstate was entered still hands the reinstated request to the
    /// session's restore queue, and the next boundary restages it from there
    /// against the matching current installation.
    #[cfg(feature = "mcp")]
    #[tokio::test]
    async fn cancelled_login_reinstatement_still_hands_off_to_the_restore_queue() {
        let installation = McpServerConfig::stdio("restored", "echo", Vec::new(), HashMap::new());
        let mut config = Config::default();
        config.tools.mcp_servers.push(installation.clone());
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);
        runtime.set_config_runtime(Arc::new(meerkat_core::ConfigRuntime::new(
            Arc::new(meerkat_core::MemoryConfigStore::new(
                config,
                meerkat_models::canonical(),
            )),
            temp.path().join("config_state.json"),
        )));
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();
        let (event_tx, _event_rx) = mpsc::channel(32);
        runtime
            .start_turn(
                &session_id,
                "hello".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("the first turn materializes the session");
        runtime
            .mcp_stage_add(&session_id, installation)
            .await
            .expect("stage add");
        // Suppressed, as a sign-out leaves it: the live surface withdrawn
        // (nothing pending at a boundary) and the durable request suppressed.
        runtime
            .mcp_adapter_for_session(&session_id)
            .await
            .expect("the session's adapter")
            .stage_remove("restored")
            .await
            .expect("withdraw the staged add");
        assert_eq!(
            runtime
                .mcp_apply_staged_for_test(&session_id)
                .await
                .expect("apply the withdrawal"),
            0,
            "nothing of the original add remains staged"
        );
        runtime
            .enter_mcp_intent_transition(&session_id)
            .await
            .record(
                meerkat_core::McpAttachmentIntentMutation::SuppressByLogout {
                    server_name: "restored".to_string(),
                },
            )
            .await
            .expect("record the sign-out");
        let suppressed = runtime
            .durable_mcp_attachment_intents(&session_id)
            .await
            .expect("read the durable intents");
        let [suppressed] = suppressed.as_slice() else {
            panic!("one durable intent: {suppressed:?}");
        };
        assert_eq!(
            suppressed.disposition,
            meerkat_core::McpAttachmentIntentDisposition::SuppressedByLogout
        );

        let hook = Arc::new(PendingPromotionPreTurnHook::default());
        *runtime
            .mcp_intent_settlement_hook
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));
        let transition = runtime.enter_mcp_intent_transition(&session_id).await;
        let reinstate = meerkat_core::McpAttachmentIntentMutation::Reinstate {
            server_name: "restored".to_string(),
            expected_revision: suppressed.revision,
        };
        let caller = tokio::spawn(SessionRuntime::settle_mcp_intent_transition(
            transition.reinstate_and_hand_off(reinstate, "restored".to_string()),
        ));
        // The Reinstate is recorded; the hand-off waits on the hook.
        wait_hook_reached(&hook).await;
        caller.abort();
        let _ = caller.await;
        *runtime
            .mcp_intent_settlement_hook
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        hook.release.notify_waiters();

        let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
        let queued = loop {
            let queued = runtime
                .mcp_sessions
                .read()
                .await
                .get(&session_id)
                .map(|state| state.pending_restore.clone())
                .unwrap_or_default();
            if !queued.is_empty() || tokio::time::Instant::now() >= deadline {
                break queued;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        };
        let requested = runtime
            .durable_mcp_attachment_intents(&session_id)
            .await
            .expect("read the durable intents");
        assert_eq!(
            requested
                .iter()
                .map(|intent| intent.disposition)
                .collect::<Vec<_>>(),
            vec![meerkat_core::McpAttachmentIntentDisposition::Requested],
            "the entered Reinstate settled"
        );
        assert_eq!(
            queued, requested,
            "the settlement handed that exact request to the restore queue"
        );

        // The next boundary's restore takes it from the queue and restages it
        // from the current installation: that boundary starts its add.
        let (event_tx, mut event_rx) = mpsc::channel(64);
        runtime
            .start_turn(
                &session_id,
                "again".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await
            .expect("the next turn");
        let events = collect_tool_config_events(&mut event_rx).await;
        assert!(
            events.iter().any(|payload| {
                payload.operation == ToolConfigChangeOperation::Add
                    && payload.target == "restored"
                    && payload.status_text() == "pending"
            }),
            "the next boundary applies the restaged add: {events:?}"
        );
        assert!(
            events.iter().all(|payload| !matches!(
                payload.status_info(),
                meerkat_core::ToolConfigChangeStatus::ExternalToolDelta {
                    restore: Some(_),
                    ..
                }
            )),
            "no restore refusal is reported: {events:?}"
        );
        assert!(
            runtime
                .mcp_sessions
                .read()
                .await
                .get(&session_id)
                .is_some_and(|state| state.pending_restore.is_empty()),
            "the boundary restored the queued request"
        );
    }

    /// A live `mcp/add` launches through the host factory's MCP stdio launch
    /// profile, as a factory-built router does. Under a required profile the
    /// backend refuses (`require_descendant_termination` is unsupported on
    /// every backend), so the server is refused typed and its process never
    /// starts: the live router never launches outside the host's boundary.
    #[cfg(all(feature = "mcp", unix))]
    #[tokio::test]
    async fn live_mcp_add_launches_inside_the_factory_stdio_launch_profile() {
        use meerkat_core::confinement::{
            ConfinementRefusal, ConfinementSpec, FilesystemAccess, IpNetworkAccess, PathAccess,
            PlatformBaseline,
        };

        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let marker = root.join("live-add-launch-marker");
        let requirement = ConfinementSpec {
            baseline: PlatformBaseline::CommandRuntimeV1,
            read: FilesystemAccess::Paths(vec![PathAccess::Subtree(root.clone())]),
            write: FilesystemAccess::Paths(vec![PathAccess::Subtree(root.clone())]),
            deny_read: vec![],
            deny_write: vec![],
            network: IpNetworkAccess::Denied,
            unix_connect: vec![],
            require_descendant_termination: true,
        }
        .try_into()
        .unwrap();
        let factory = temp_factory(&temp).with_mcp_stdio_launch_profile(
            meerkat::McpStdioLaunchProfile::required(requirement, root.clone()),
        );
        let runtime = make_runtime(factory, 10);
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();
        let adapter = runtime
            .mcp_sessions
            .read()
            .await
            .get(&session_id)
            .map(|state| Arc::clone(&state.adapter))
            .expect("the session's live MCP adapter");

        adapter
            .stage_add(McpServerConfig::stdio(
                "confined-live-add",
                "/bin/sh",
                vec!["-c".into(), "printf entered > \"$MARKER\"".into()],
                HashMap::from([("MARKER".into(), marker.display().to_string())]),
            ))
            .await
            .unwrap();
        adapter.apply_staged().await.unwrap();
        let deltas = adapter
            .wait_until_ready(Duration::from_secs(15))
            .await
            .unwrap();

        assert!(
            deltas.iter().any(|delta| {
                delta.target == "confined-live-add"
                    && delta.phase == meerkat_core::ExternalToolDeltaPhase::Failed
                    && delta.confinement_refusal == Some(ConfinementRefusal::UnsupportedRequirement)
            }),
            "the live add is refused by the factory's launch boundary: {deltas:?}"
        );
        assert!(
            !marker.exists(),
            "a refused live add never starts the server process"
        );
        adapter.shutdown().await;
    }

    /// A live `mcp/add` on a guarded host begins the factory's attempt guard
    /// before anything of the attempt runs, for this session: a refusing
    /// host refuses the add, and its process never starts.
    #[cfg(all(feature = "mcp", unix))]
    #[tokio::test]
    async fn live_mcp_add_begins_the_factory_attempt_guard() {
        #[derive(Default)]
        struct Refusing(std::sync::Mutex<Vec<meerkat::McpAttemptGuardRequest>>);
        #[async_trait::async_trait]
        impl meerkat::McpAttemptGuardFactory for Refusing {
            async fn begin(
                &self,
                request: meerkat::McpAttemptGuardRequest,
                _cancel: meerkat::McpAttemptCancellation,
            ) -> Result<
                Option<Box<dyn meerkat::McpAttemptGuard>>,
                meerkat_core::mcp_attachment::McpAttachmentRefusal,
            > {
                self.0.lock().unwrap().push(request);
                Err(meerkat_core::mcp_attachment::McpAttachmentRefusal::Denied)
            }
        }

        let temp = tempfile::tempdir().unwrap();
        let marker = temp.path().join("guarded-live-add-marker");
        let refusing = Arc::new(Refusing::default());
        let guards = meerkat::McpAttemptGuards::new(
            Arc::clone(&refusing) as Arc<dyn meerkat::McpAttemptGuardFactory>,
            meerkat::McpAttemptGuardBounds::DEFAULT,
        );
        let factory = temp_factory(&temp).with_mcp_attempt_guards(guards.clone());
        let runtime = make_runtime(factory, 10);
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();
        let adapter = runtime
            .mcp_sessions
            .read()
            .await
            .get(&session_id)
            .map(|state| Arc::clone(&state.adapter))
            .expect("the session's live MCP adapter");

        adapter
            .stage_add(McpServerConfig::stdio(
                "guarded-live-add",
                "/bin/sh",
                vec!["-c".into(), "printf entered > \"$MARKER\"".into()],
                HashMap::from([("MARKER".into(), marker.display().to_string())]),
            ))
            .await
            .unwrap();
        adapter.apply_staged().await.unwrap();
        let deltas = adapter
            .wait_until_ready(Duration::from_secs(15))
            .await
            .unwrap();

        assert!(
            deltas.iter().any(|delta| {
                delta.target == "guarded-live-add"
                    && delta.phase == meerkat_core::ExternalToolDeltaPhase::Failed
            }),
            "the host's guard refuses the live add: {deltas:?}"
        );
        assert!(
            !marker.exists(),
            "a refused live add never starts the server process"
        );
        let requests = refusing.0.lock().unwrap().clone();
        assert_eq!(requests.len(), 1, "the guard began once: {requests:?}");
        assert_eq!(requests[0].key.server, "guarded-live-add");
        assert_eq!(requests[0].key.construction, adapter.construction_id());
        assert_eq!(requests[0].owner.session_id, session_id);
        adapter.shutdown().await;
        let _ = guards
            .close_and_join(tokio::time::Instant::now() + Duration::from_secs(10))
            .await;
    }

    #[cfg(feature = "mcp")]
    #[tokio::test]
    async fn start_turn_applies_staged_mcp_ops_at_turn_boundary() {
        let temp = tempfile::tempdir().unwrap();
        let runtime = make_runtime(temp_factory(&temp), 10);
        let session_id = runtime
            .create_session(mock_build_config(), None, None, Vec::new())
            .await
            .unwrap();

        runtime
            .mcp_stage_add(
                &session_id,
                McpServerConfig::stdio("broken-server", "echo", Vec::new(), HashMap::new()),
            )
            .await
            .expect("staging should succeed");

        // Non-blocking: apply_staged spawns background task and succeeds
        // (the broken server fails asynchronously, not at staging time).
        let (event_tx, mut event_rx) = mpsc::channel(32);
        let first = runtime
            .start_turn(
                &session_id,
                "hello".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await;
        assert!(
            first.is_ok(),
            "non-blocking apply_staged should not fail synchronously"
        );
        let first_events = collect_tool_config_events(&mut event_rx).await;
        assert!(
            first_events.iter().any(|payload| {
                payload.operation == ToolConfigChangeOperation::Add
                    && payload.target == "broken-server"
                    && payload.status_text() == "pending"
            }),
            "should emit pending event for staged add"
        );

        let (event_tx, _event_rx) = mpsc::channel(32);
        let second = runtime
            .start_turn(
                &session_id,
                "hello again".into(),
                event_tx,
                None,
                None,
                None,
                None,
            )
            .await;
        assert!(
            second.is_ok(),
            "failed staged operation should not poison subsequent turns"
        );
    }

