    #[test]
    fn session_error_to_rpc_preserves_sticky_fallback_teardown_requirement() {
        use meerkat_core::lifecycle::core_executor::{
            CoreExecutorError, CoreExecutorTeardownReason,
        };

        let rpc_err = session_error_to_rpc(SessionError::Agent(
            meerkat_core::AgentError::StickyModelFallbackAuthorityUnknown {
                message: "sticky fallback CAS outcome is ambiguous".to_string(),
            },
        ));
        assert_eq!(
            rpc_err
                .data
                .as_ref()
                .and_then(|data| data.get("core_executor_teardown_reason"))
                .and_then(serde_json::Value::as_str),
            Some(CoreExecutorTeardownReason::SessionUnavailable.as_str())
        );

        let decoded = crate::session_executor::core_executor_error_from_rpc(rpc_err);
        assert!(matches!(
            decoded,
            CoreExecutorError::TeardownRequired {
                reason: CoreExecutorTeardownReason::SessionUnavailable,
                ..
            }
        ));
    }

    #[test]
    fn session_error_to_rpc_preserves_durable_projection_teardown_requirement() {
        use meerkat_core::lifecycle::core_executor::{
            CoreExecutorError, CoreExecutorTeardownReason,
        };

        let rpc_err = session_error_to_rpc(SessionError::Agent(
            meerkat_core::AgentError::session_durable_projection_authority_unknown(
                "system-context sidecar and shared handle diverged",
            ),
        ));
        assert_eq!(
            rpc_err
                .data
                .as_ref()
                .and_then(|data| data.get("core_executor_teardown_reason"))
                .and_then(serde_json::Value::as_str),
            Some(CoreExecutorTeardownReason::DurableProjectionAuthorityUnknown.as_str())
        );

        let decoded = crate::session_executor::core_executor_error_from_rpc(rpc_err);
        assert!(matches!(
            decoded,
            CoreExecutorError::TeardownRequired {
                reason: CoreExecutorTeardownReason::DurableProjectionAuthorityUnknown,
                ..
            }
        ));
    }

    /// A durable resume hold must never reach a caller as an internal fault:
    /// the session is intact and withheld. The hold class survives as typed
    /// structured data in both directions, so a caller across the transport
    /// classifies identically to one in-process — no prose parsing anywhere.
    #[test]
    fn session_error_to_rpc_surfaces_durable_resume_holds_as_typed_holds() {
        let id = SessionId::new();
        for (session_err, hold) in [
            (
                SessionError::DurableTailHeldForRecovery { id: id.clone() },
                DurableResumeHold::TailHeldForRecovery,
            ),
            (
                SessionError::DurableTailRecoveryRefused { id: id.clone() },
                DurableResumeHold::RecoveryRefused,
            ),
            (
                SessionError::DurableEvidenceQuarantined { id: id.clone() },
                DurableResumeHold::EvidenceQuarantined,
            ),
        ] {
            let expected_code = session_err.code();
            let rpc_err = session_error_to_rpc(session_err);
            assert_eq!(rpc_err.code, error::SESSION_NOT_RUNNING);
            let data = rpc_err.data.clone().expect("hold must carry typed data");
            assert_eq!(
                SessionError::durable_resume_hold_from_data(&data),
                Some(hold)
            );
            assert_eq!(
                data.get("session_error_code")
                    .and_then(serde_json::Value::as_str),
                Some(expected_code)
            );
            assert_eq!(
                data.get("content_retained")
                    .and_then(serde_json::Value::as_bool),
                Some(true),
                "a hold retains durable content; it never reports loss"
            );
            let round_tripped = rpc_error_to_session_error(rpc_err, &id);
            assert_eq!(round_tripped.durable_resume_hold(), Some(hold));
            assert_eq!(round_tripped.code(), expected_code);
        }
    }

    #[test]
    fn session_error_to_rpc_surfaces_skill_resolution_failures_as_skill_errors()
    -> Result<(), Box<dyn std::error::Error>> {
        let skill_name = meerkat_core::skills::SkillName::parse("example")?;
        let key = meerkat_core::skills::SkillKey::builtin(skill_name);
        let session_err = SessionError::Agent(meerkat_core::AgentError::SkillResolutionFailed {
            skill_key: Some(key.clone()),
            reason: Box::new(meerkat_core::event::SkillResolutionFailureReason::NotFound { key }),
        });
        let rpc_err = session_error_to_rpc(session_err);

        assert_eq!(rpc_err.code, error::SKILL_RESOLUTION_FAILED);
        Ok(())
    }

